function requestFlowdownCard(r){P.syncRequestFlowdown(App.state,r);const plan=r.capturePlan||{},f=plan.flowdown||{},batch=plan.batchFields||[],sample=plan.sampleFields||[],photos=plan.photoSlots||[];const chips=(arr,empty='None')=>arr.length?arr.map(x=>`<span class="pill">${esc(x.label||x)}</span>`).join(' '):`<span class="subtle">${empty}</span>`;return `<div class="card flowdown-card"><div class="section-title-row"><div><span class="eyebrow">REQUEST → PROCESS → EVIDENCE</span><h2>Controlled flow-down · Rev ${esc(plan.revision||1)}</h2><div class="subtle">The request defines the downstream evidence structure once. Sample operators fill values; they do not redefine the required fields.</div></div>${status(r.productSafety?'Product safety':'Controlled')}</div><div class="flowdown-context-grid"><div><span>Build maturity</span><strong>${esc(f.buildMaturity||'—')}</strong></div><div><span>Configuration</span><strong>${esc(f.configuration||'—')}</strong></div><div><span>BOM</span><strong>${esc(f.bomRef||'—')}</strong></div><div><span>Material source</span><strong>${esc(f.materialSource||'—')}</strong></div></div><div class="flowdown-groups"><div><strong>Batch data</strong><div>${chips(batch,'No extra batch fields defined')}</div></div><div><strong>Sample data</strong><div>${chips(sample,'No extra sample fields defined')}</div></div><div><strong>Photo evidence</strong><div>${chips(photos,'No mandatory photo slots defined')}</div></div><div><strong>Characterisation</strong><div>${chips((r.characterisation||[]).map(x=>({label:x})),'None requested')}</div></div><div><strong>Special characteristics</strong><div>${chips((r.specialCharacteristics||[]).map(x=>({label:x})),'None defined')}</div></div></div></div>`}
