 const cpRequired=cpDefs.reduce((n,d)=>n+(d.sampling?.count||0),0),cpCaptured=cpDefs.reduce((n,d)=>n+(App.state.measurements||[]).filter(m=>m.requestId===r.id&&m.routeStepId===selected.id&&m.characteristicId===d.cpCharacteristicId&&(d.sampling?.refs||[]).includes(m.serial)&&(!run?.id||m.executionRunId===run.id)).length,0);
