 failedMeasurements.forEach(m=>{const c=chars.get(m.characteristicId),label=String(c?.characteristic||c?.name||m.name||m.characteristic||'Controlled measurement'),serial=String(m.sampleId||m.serial||''),alreadyCovered=linkedMeasurementIds.has(String(m.id))||(serial&&qualitySerials.has(serial))||qualityWords.some(w=>label.toLowerCase().includes(w)||w.includes(label.toLowerCase()));if(alreadyCovered)return;push('measurement',m.id,'Process / Control Plan',`${label} recorded a failure.`,`Sample ${serial||'batch'} · ${m.value??m.result??'FAIL'} ${m.unit||c?.unit||''}`.trim(),`Review the reaction-plan outcome and update the reusable control/process only if the verified cause is systemic.`)});
