  rules.push(auditRule(stat(cpBad.length),'Major','8.5.1.1','Formal builds have approved Control Plans',cpBad.length?`${cpBad.length} active validation/production build(s) lack an approved Control Plan`:'Active formal builds have approved Control Plans','Complete Control Plan definition and independent approval','Control plan'));
  rules.push(auditRule(stat(scMissing.length),'Major','8.5.1.1','Special / safety characteristics are flowed to objective controls',scMissing.length?`${scMissing.length} formal build(s) have incomplete SC/safety controls`:'Special-characteristic controls are defined where applicable','Complete specification, method, evidence and reaction plan','Special characteristics'));
  rules.push(auditRule(stat(invalidMeas.length),'Major','7.1.5','Measurement evidence is traceable to valid equipment',invalidMeas.length?`${invalidMeas.length} measurement record(s) reference invalid calibration state`:'No invalid-calibration measurement evidence detected','Contain affected evidence and remeasure with valid traceability','Measurement traceability'));
