  rules.push(auditRule(stat(unreleased.length),'Major','7.2','Methods are controlled / verified before use',unreleased.length?`${unreleased.length} used method(s) lack released work instructions`:'Used controlled process methods are released','Validate/verify and release methods or document justified deviation','Methods'));
  rules.push(auditRule(stat(missingEvidence.length>5,true),'Minor','7.5','Technical records retain sufficient evidence',missingEvidence.length?`${missingEvidence.length} measurement record(s) lack an evidence reference`:'Measurement records include evidence references','Complete technical-record references and source-data linkage','Technical records'));
