function auditProfileModal(){P.ensureEnterpriseModel(App.state);const d=App.state.settings.auditProfile||{};openModal('Audit scope & references',`<div class="form-grid"><div class="field"><label>Organisation</label><input id="auditOrg" value="${esc(d.organisation||'')}"></div><div class="field"><label>Site / laboratory</label><input id="auditSite" value="${esc(d.site||'')}"></div><div class="field full"><label>Scope statement</label><textarea id="auditScopeStatement" placeholder="Activities, products/processes and laboratory boundary covered by this audit">${esc(d.scopeStatement||'')}</textarea></div><div class="field"><label>Audit owner</label><input id="auditOwner" value="${esc(d.auditOwner||App.state.identity.name)}"></div><div class="field"><label>Controlled scope reference <small>optional</small></label><input id="auditRef" value="${esc(d.controlledReference||'')}"></div><div class="field"><label>Records-retention reference</label><input id="auditRetentionRef" placeholder="e.g. QMS-PRO-014" value="${esc(d.recordsRetentionReference||'')}"></div><div class="field"><label>Internal-audit programme / report reference <small>ISO 17025</small></label><input id="auditInternalRef" placeholder="e.g. IA-2026-04" value="${esc(d.internalAuditReference||'')}"></div><div class="field full"><label>Exclusions / boundaries <small>optional</small></label><textarea id="auditExclusions">${esc(d.exclusions||'')}</textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save','data-save-audit-profile','button primary')}`);setTimeout(()=>{$('[data-save-audit-profile]').onclick=async()=>{const organisation=$('#auditOrg').value.trim(),site=$('#auditSite').value.trim(),scopeStatement=$('#auditScopeStatement').value.trim();if(!organisation||!site||!scopeStatement){toast('Organisation, site/laboratory and scope statement are required.',true);return}App.state.settings.auditProfile={organisation,site,scopeStatement,auditOwner:$('#auditOwner').value.trim(),controlledReference:$('#auditRef').value.trim(),recordsRetentionReference:$('#auditRetentionRef').value.trim(),internalAuditReference:$('#auditInternalRef').value.trim(),exclusions:$('#auditExclusions').value.trim()};P.audit(App.state,'Audit scope updated','Settings','auditProfile','Previous audit scope',scopeStatement,`${organisation} · ${site}`);await persist();closeModal();render();toast('Audit scope and references saved.')}},0)}
function auditFindingAffected(rule){const area=String(rule.area||'').toLowerCase(),today=P.todayISO();if(area==='audit scope'){const d=App.state.settings?.auditProfile||{},out=[];if(!String(d.organisation||'').trim())out.push('Organisation');if(!String(d.site||'').trim())out.push('Site / laboratory');if(!String(d.scopeStatement||'').trim())out.push('Scope statement');return out}if(area==='audit trail'){const d=App.state.settings?.auditProfile||{},out=[];if(!(App.state.auditTrail||[]).length)out.push('No audit-trail events retained');if(!String(d.recordsRetentionReference||'').trim())out.push('Records-retention reference');return out}if(area==='internal audit'){const d=App.state.settings?.auditProfile||{};return String(d.internalAuditReference||'').trim()?[]:['Internal-audit programme / report reference']}if(area==='maintenance state'||/maintenance state/.test(String(rule.title||'').toLowerCase()))return (App.state.equipment||[]).filter(e=>e.maintenanceDue&&e.maintenanceDue<today).map(e=>`${e.id} · ${e.name} · maintenance due ${e.maintenanceDue}`);if(/measurement resources|^equipment$/.test(area))return (App.state.equipment||[]).filter(e=>e.calibrationRequired!==false&&(!P.validCalibrationCertificate(App.state,e.id,today)||e.calibrationStatus!=='Valid'||(e.calibrationDue&&e.calibrationDue<today))).map(e=>`${e.id} · ${e.name} · calibration ${e.calibrationStatus||'unknown'} / due ${e.calibrationDue||'not set'}`);if(/laboratory scope/.test(area))return auditScopeRows().filter(x=>!x.activity||!x.range||!x.method).map(x=>`${x.category} · ${x.equipmentCount} equipment item(s)`);if(/measurement uncertainty/.test(area))return auditScopeRows().filter(x=>/measurement|calibration|dimensional|pressure|electrical|leak|temperature|torque/i.test(`${x.activity} ${x.capability}`)&&(!x.uncertainty||/N\/A/i.test(x.uncertainty))).map(x=>`${x.category} · ${x.equipmentCount} equipment item(s)`);if(/competence|personnel/.test(area))return (App.state.trainingCertificates||[]).filter(c=>c.status==='Valid'&&c.expiresAt&&c.expiresAt<today).map(c=>{const st=App.state.staff.find(x=>x.id===c.staffId),sk=App.state.competencies.find(x=>x.id===c.skillId);return `${st?.name||c.staffId} · ${sk?.name||c.skillId} · expired ${c.expiresAt}`});if(/standardized work|methods/.test(area)){const active=(App.state.requests||[]).filter(r=>r.status!=='CLOSED'),ids=new Set((App.state.routes||[]).filter(rt=>active.some(r=>r.id===rt.requestId)).flatMap(rt=>(rt.steps||[]).map(s=>s.processId).filter(Boolean)));return (App.state.processes||[]).filter(p=>ids.has(p.id)&&(p.status!=='Released'||!p.workInstruction?.steps?.length||p.workInstruction?.status!=='Released')).map(p=>`${p.id} · ${p.name}`)}if(/control plan/.test(area)){return (App.state.requests||[]).filter(r=>r.status!=='CLOSED'&&P.ensureAssuranceProfile(r).formalLevel>=2).filter(r=>{const cp=(App.state.controlPlans||[]).find(c=>c.id===r.controlPlanId);return !cp||cp.status!=='Approved'}).map(r=>`${r.id} · ${r.title}`)}if(/special characteristics/.test(area)){return (App.state.requests||[]).filter(r=>r.status!=='CLOSED'&&P.ensureAssuranceProfile(r).formalLevel>=2&&(r.specialCharacteristics||[]).length).filter(r=>{const cp=(App.state.controlPlans||[]).find(c=>c.id===r.controlPlanId);return !cp||(cp.characteristics||[]).filter(c=>c.classification).some(c=>!P.controlCharacteristicReady(c))}).map(r=>`${r.id} · ${r.title}`)}if(/measurement traceability|metrological traceability/.test(area))return (App.state.measurements||[]).filter(m=>m.calibrationRequired&&m.equipmentCalibrationStatus!=='Valid').map(m=>`${m.id} · ${m.requestId||'no build'} · ${m.equipmentId||'equipment not linked'}`);if(/corrective action|validity of results/.test(area))return (App.state.deviations||[]).filter(d=>d.releaseHold&&d.status!=='CLOSED').map(d=>`${d.id} · ${d.requestId||'portfolio'} · ${d.title||d.type||'release hold'}`);if(/technical records/.test(area))return (App.state.measurements||[]).filter(m=>!m.evidence).slice(0,20).map(m=>`${m.id} · ${m.requestId||'no build'} · evidence missing`);if(/documented information|reporting/.test(area))return (App.state.requests||[]).filter(r=>r.status==='CLOSED'&&P.ensureBuildReportApproval(App.state,r).status!=='Approved').map(r=>`${r.id} · ${r.title}`);return []}
function auditFindingTargets(rule){const area=String(rule.area||'').toLowerCase();if(area==='audit scope')return {label:'Define scope',action:'audit-profile'};if(area==='audit trail'||area==='internal audit')return {label:'Add controlled reference',action:'audit-profile'};if(area==='maintenance state'||/maintenance state/.test(String(rule.title||'').toLowerCase()))return {label:'Schedule maintenance',action:'maintenance'};if(/laboratory scope|measurement uncertainty/.test(area))return {label:'Complete equipment scope',action:'scope-equipment'};if(/measurement resources|^equipment$/.test(area))return {label:'Resolve calibration',action:'calibration'};if(/competence|personnel/.test(area))return {label:'Schedule training',action:'training'};if(/standardized work|methods/.test(area))return {label:'Open affected method',action:'process-library'};if(/control plan|special characteristics/.test(area))return {label:'Open affected build',action:'controls'};if(/measurement traceability|metrological traceability|technical records/.test(area))return {label:'Open affected evidence',action:'affected-evidence'};if(/corrective action|validity of results/.test(area))return {label:'Resolve quality hold',action:'quality'};if(/documented information|reporting/.test(area))return {label:'Open Build Reports',action:'reports'};if(/audit trail|internal audit/.test(area))return {label:'Open audit evidence pack',action:'audit-pack'};return {label:'Open evidence pack',action:'audit-pack'}}
function auditCareResolution(type,items){
 const svc=new P.ResourceCareService(),forecast=svc.forecast(App.state,52),tokens=(items||[]).flatMap(x=>String(x).split(' · ').slice(0,2)).map(x=>x.trim()).filter(Boolean),matches=forecast.filter(x=>x.type===type&&tokens.some(t=>String(x.targetId||'')===t||String(x.targetName||'').includes(t)||(x.equipmentId&&x.equipmentId===t)||(x.staffId&&((App.state.staff||[]).find(s=>s.id===x.staffId)?.name===t))));
 if(matches.length){careScheduleModal(matches.map(x=>x.id));return}
 if(type==='Training'){const first=String(items?.[0]||'').split(' · ')[0],st=(App.state.staff||[]).find(x=>x.name===first||x.id===first);if(st){const skillName=String(items?.[0]||'').split(' · ')[1]?.trim(),skill=(App.state.competencies||[]).find(x=>x.name===skillName||x.id===skillName);editStaffSkills(st.id,skill?.id||null);return}}
 if(type==='Calibration'||type==='Maintenance'){const id=String(items?.[0]||'').split(' · ')[0];const eq=(App.state.equipment||[]).find(x=>x.id===id);if(eq){careNewScheduleModal(type);setTimeout(()=>{const sel=$('#newCareEquipment');if(sel){sel.value=eq.id;sel.dispatchEvent(new Event('change'))}},0);return}}
 toast(`No unresolved ${type.toLowerCase()} item could be found. Audit Readiness has been refreshed.`,true);render();
}
function auditFindingModal(key){const a=auditAssessment(App.filters.auditFramework||'iatf'),rule=a.rules.find(x=>x.key===key);if(!rule)return;const t=auditFindingTargets(rule),affected=auditFindingAffected(rule),list=affected.length?`<div class="audit-affected"><strong>Affected</strong>${affected.slice(0,5).map(x=>`<div>• ${esc(x)}</div>`).join('')}${affected.length>5?`<small>+ ${affected.length-5} more</small>`:''}</div>`:'';openModal(`${rule.status} · ${rule.area}`,`<div class="audit-guided-finding"><div class="audit-finding-focus">${auditSeverityPill(rule.status)}<h2>${esc(rule.title)}</h2>${list}</div><ol class="guided-mini-steps"><li><strong>1 · Resolve</strong><span>${esc(rule.action)}</span></li><li><strong>2 · Evidence</strong><span>Record the controlled evidence in the guided workflow.</span></li><li><strong>3 · Recheck</strong><span>LabOS recalculates this finding automatically.</span></li></ol></div>`,`${btn('Close','data-modal-close','button')}${btn(t.label,`data-audit-resolve-action="${esc(t.action)}" data-audit-rule="${esc(rule.key)}"`,'button primary')}`);setTimeout(()=>{$$('[data-audit-resolve-action]').forEach(el=>el.onclick=()=>{const action=el.dataset.auditResolveAction,items=auditFindingAffected(rule);closeModal();if(action==='audit-profile')return auditProfileModal();if(action==='calibration')return auditCareResolution('Calibration',items);if(action==='maintenance')return auditCareResolution('Maintenance',items);if(action==='training')return auditCareResolution('Training',items);if(action==='scope-equipment'){const id=String(items[0]||'').split(' · ')[0];if(id)return editEquipmentScopeModal(id);return nav('equipment-master')}if(action==='controls'){const id=String(items[0]||'').split(' · ')[0];if(id&&requestById(id))return openRequest(id,'controls');return nav('requests')}if(action==='affected-evidence'){const hit=(App.state.measurements||[]).find(m=>items.some(x=>String(x).startsWith(m.id+' · ')));if(hit?.requestId)return openRequest(hit.requestId,'verify');return nav('characterisation')}if(action==='quality'){const first=String(items[0]||'').split(' · ')[0],d=(App.state.deviations||[]).find(x=>x.id===first);if(d)return qualityCaseModal(d.id);App.filters.qualityTab='actions';return nav('quality')}if(action==='reports'){const rid=String(items[0]||'').split(' · ')[0];if(requestById(rid))return openRequest(rid,'closeout');return nav('reports')}if(action==='audit-pack')return auditEvidencePackModal();nav(action)})},0)}
function auditEvidencePackModal(){const a=auditAssessment(App.filters.auditFramework||'iatf'),profile=App.state.settings.auditProfile||{},scopeReady=String(profile.organisation||'').trim()&&String(profile.site||'').trim()&&String(profile.scopeStatement||'').trim();if(!scopeReady){toast('Define the organisation, site/laboratory and audit scope before generating the audit pack.',true);auditProfileModal();return}const care=App.state.resourceCareBookings||[],cal=(App.state.calibrationCertificates||[]).slice().sort((x,y)=>String(y.completedAt||'').localeCompare(String(x.completedAt||''))),mnt=(App.state.maintenanceRecords||[]).filter(x=>x.type==='Maintenance').slice().sort((x,y)=>String(y.completedAt||'').localeCompare(String(x.completedAt||''))),trn=(App.state.trainingCertificates||[]).filter(x=>x.status!=='Revoked').slice().sort((x,y)=>String(y.expiresAt||'').localeCompare(String(x.expiresAt||''))),docs=[['Audit scope & boundaries',`${profile.organisation} · ${profile.site}`],['Readiness / findings register',`${a.major} major · ${a.minor} minor · ${a.ready} ready`],['Laboratory capability / uncertainty scope',`${auditScopeRows().length} equipment category scope record(s)`],['Calibration register & certificate index',`${cal.length} certificate(s)`],['Maintenance register & evidence index',`${mnt.length} record(s)`],['Competence / training matrix & certificate index',`${trn.length} certificate(s)`],['Controlled methods / work-instruction register',`${(App.state.processes||[]).filter(x=>x.status==='Released').length} released process(es)`],['Control Plan / special-characteristic register',`${(App.state.controlPlans||[]).length} plan(s)`],['Sample genealogy / traceability records',`${(App.state.serials||[]).length} sample record(s)`],['Quality / nonconformity / corrective-action register',`${(App.state.deviations||[]).length} case(s)`],['Approved build / release dossiers',`${(App.state.requests||[]).filter(r=>P.ensureBuildReportApproval(App.state,r).status==='Approved').length} approved report(s)`],['Change & approval audit trail',`${(App.state.auditTrail||[]).length} event(s) · retention ${profile.recordsRetentionReference||'reference not set'}`],['Internal-audit programme / latest report',profile.internalAuditReference||'reference not set'],['Calibration / maintenance / training schedule',`${care.filter(x=>x.status==='Scheduled').length} scheduled item(s)`],['Management KPI snapshot','Available from Management KPIs when requested by the auditor']];const certSection=(title,rows,fn)=>`<details><summary>${esc(title)} (${rows.length})</summary><div class="audit-evidence-links">${rows.slice(0,30).map(fn).join('')||'<div class="empty compact">No records.</div>'}${rows.length>30?`<small>Showing first 30 of ${rows.length}; use the source report for the full register.</small>`:''}</div></details>`;openModal('Audit evidence pack',`<article class="report"><div class="report-head"><div class="report-title-block">${reportBrand()}<div><h1>Audit evidence index</h1><div>${esc(a.label)} · ${P.formatDateTime(P.now())}</div></div></div></div><div class="report-grid">${[['Organisation',profile.organisation],['Site / laboratory',profile.site],['Scope',profile.scopeStatement],['Owner',profile.auditOwner||'—'],['Controlled scope reference',profile.controlledReference||'—'],['Records-retention reference',profile.recordsRetentionReference||'—'],['Internal-audit reference',profile.internalAuditReference||'—'],['Boundaries / exclusions',profile.exclusions||'None stated']].map(([k,v])=>`<div class="report-field"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Audit evidence set</th><th>Current record</th></tr></thead><tbody>${docs.map(([n,v])=>`<tr><td><strong>${esc(n)}</strong></td><td>${esc(v)}</td></tr>`).join('')}</tbody></table></div><details><summary>Open findings (${a.major+a.minor})</summary>${a.rules.filter(x=>x.status!=='Ready').map(x=>`<div class="score-row"><span>${auditSeverityPill(x.status)} ${esc(x.area)}</span><strong>${esc(x.evidence)}</strong></div>`).join('')||'<div class="empty">No automated evidence gaps detected.</div>'}</details>${certSection('Calibration certificates',cal,c=>`<div><strong>${esc(c.certificateNo||c.id)}</strong> · ${esc(App.state.equipment.find(e=>e.id===c.equipmentId)?.name||c.equipmentId)} · ${evidenceDocumentLink(c,'Open certificate')}</div>`)}${certSection('Maintenance evidence',mnt,c=>`<div><strong>${esc(c.id)}</strong> · ${esc(App.state.equipment.find(e=>e.id===c.equipmentId)?.name||c.equipmentId)} · ${evidenceDocumentLink(c,'Open evidence')}</div>`)}${certSection('Training certificates',trn,c=>`<div><strong>${esc(c.certificateNo||c.id)}</strong> · ${esc(App.state.staff.find(x=>x.id===c.staffId)?.name||c.staffId)} · ${evidenceDocumentLink(c,'Open certificate')}</div>`)}</article>`,`${btn('Close','data-modal-close','button')}${btn('Print / save PDF','onclick="window.print()"','button primary')}`,true)}
function editEquipmentScopeModal(category){
 P.ensureEnterpriseModel(App.state);const row=auditScopeRows().find(x=>x.id===category||x.category===category);if(!row)return;const s=App.state.settings.auditEquipmentScopes?.[row.category]||{};
 openModal(`Capability scope · ${row.category}`,`<div class="callout"><strong>${row.equipmentCount} equipment item${row.equipmentCount===1?'':'s'} in this category</strong><p>${row.equipmentNames.map(esc).join('<br>')}</p></div><div class="form-grid"><div class="field full"><label>Activity / measurand</label><input id="scopeActivity" value="${esc(s.activity||'')}"></div><div class="field"><label>Range / envelope</label><input id="scopeRange" value="${esc(s.range||'')}"></div><div class="field"><label>Resolution</label><input id="scopeResolution" value="${esc(s.resolution||'')}"></div><div class="field full"><label>Uncertainty / capability statement or controlled reference</label><input id="scopeUncertainty" value="${esc(s.uncertainty||'')}"></div><div class="field full"><label>Method / work instruction</label><input id="scopeMethod" value="${esc(s.method||'')}"></div><div class="field full"><label>Note <small>optional</small></label><textarea id="scopeNote">${esc(s.note||'')}</textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save category scope','data-save-equipment-scope','button primary')}`);
 setTimeout(()=>{$('[data-save-equipment-scope]').onclick=async()=>{const activity=$('#scopeActivity').value.trim(),range=$('#scopeRange').value.trim(),resolution=$('#scopeResolution').value.trim(),uncertainty=$('#scopeUncertainty').value.trim(),method=$('#scopeMethod').value.trim();if(!activity||!range||!method){toast('Activity, range and method cannot be empty.',true);return}const measurementLike=/measurement|calibration|dimensional|pressure|electrical|leak|temperature|torque/i.test(`${activity} ${row.category}`);if(measurementLike&&(!resolution||!uncertainty)){toast('Measurement scope also requires resolution and an uncertainty/capability statement or reference.',true);return}App.state.settings.auditEquipmentScopes[row.category]={category:row.category,activity,range,resolution,uncertainty,method,note:$('#scopeNote').value.trim()};P.audit(App.state,'Equipment-category audit scope updated','Equipment category',row.category,'Previous category scope',JSON.stringify(App.state.settings.auditEquipmentScopes[row.category]),`${row.equipmentCount} equipment item(s)`);await persist();closeModal();render();toast('Category capability scope updated.')}},0)
}
function renderAuditReadiness(){if(!can('audit:view')&&currentRole()!=='administrator')return pageHeader('Audit Readiness','Audit access required.')+'<div class="empty">Auditor, Quality, Lab Manager or Administrator access is required.</div>';const framework=App.filters.auditFramework||'iatf',a=auditAssessment(framework),scope=auditScopeRows(),profile=App.state.settings?.auditProfile||{},open=a.rules.filter(x=>x.status!=='Ready'),ready=a.rules.filter(x=>x.status==='Ready'),scoreClass=a.major?'bad':a.minor?'warn':'good';return pageHeader('Audit Readiness','Fix evidence gaps through guided actions.',`${btn('Audit evidence pack','data-audit-pack','button primary')}`)+`<div class="card audit-framework-card"><div class="section-title-row"><div><span class="eyebrow">AUDIT SCOPE</span><h2>${esc(profile.scopeStatement||'Scope not defined')}</h2><div class="subtle">${profile.organisation?esc(profile.organisation):'Organisation required'}${profile.site?' · '+esc(profile.site):' · Site/lab required'}</div></div>${btn(profile.scopeStatement?'Edit scope':'Define scope','data-audit-profile','button small primary')}</div><div class="audit-score-grid"><div class="audit-score ${scoreClass}"><span>Readiness</span><strong>${a.score}%</strong></div><div class="audit-count major"><strong>${a.major}</strong><span>Major</span></div><div class="audit-count minor"><strong>${a.minor}</strong><span>Minor</span></div><div class="audit-count ready"><strong>${a.ready}</strong><span>Ready</span></div></div><label class="compact-select">Framework<select id="auditFramework"><option value="iatf" ${framework==='iatf'?'selected':''}>IATF 16949</option><option value="iso17025" ${framework==='iso17025'?'selected':''}>ISO/IEC 17025</option></select></label></div><div class="card"><div class="section-title-row"><div><span class="eyebrow">OPEN FINDINGS</span><h2>${open.length?`${open.length} item${open.length===1?'':'s'} to resolve`:'No open automated evidence gaps'}</h2></div></div><div class="audit-guided-list">${open.map(x=>`<div class="audit-guided-row"><div>${auditSeverityPill(x.status)}<strong>${esc(x.area)} · ${esc(x.title)}</strong><small>${esc(x.evidence)}</small></div>${btn('Resolve →',`data-audit-resolve="${esc(x.key)}"`,'button small primary')}</div>`).join('')||'<div class="callout good"><strong>✓ Current evidence checks are ready.</strong></div>'}</div></div><details class="card fold"><summary>✓ Ready controls (${ready.length})</summary><div class="table-wrap"><table class="data-table"><tbody>${ready.map(x=>`<tr><td>${esc(x.clause)}</td><td><strong>${esc(x.title)}</strong></td><td>${esc(x.evidence)}</td></tr>`).join('')}</tbody></table></div></details><details class="card fold"><summary>Laboratory capability scope by equipment category (${scope.length})</summary><div class="table-wrap"><table class="data-table lab-scope-table"><thead><tr><th>Category</th><th>Equipment</th><th>Activity</th><th>Range</th><th>Resolution</th><th>Uncertainty / capability</th><th>Method</th><th></th></tr></thead><tbody>${scope.map(x=>`<tr><td><strong>${esc(x.category)}</strong></td><td>${x.equipmentCount}<small>${esc(x.equipmentTypes.join(', '))}</small></td><td>${esc(x.activity||'MISSING')}</td><td>${esc(x.range||'MISSING')}</td><td>${esc(x.resolution||'—')}</td><td>${esc(x.uncertainty||'—')}</td><td>${esc(x.method||'MISSING')}</td><td>${(currentRole()==='administrator'||can('equipment:manage'))?btn('Edit',`data-edit-equipment-scope="${esc(x.category)}"`,'button tiny secondary'):''}</td></tr>`).join('')}</tbody></table></div></details><details class="card fold"><summary>Exports & audit documents</summary><div class="route-toolbar">${btn('Findings CSV','data-audit-export-findings','button secondary')}${btn('Lab scope CSV','data-audit-export-scope','button secondary')}${btn('Print evidence pack','data-audit-pack','button primary')}</div></details>`}
function renderAdmin(){
 const inv=P.validateInvariants(App.state),open=openActions().length,customers=App.state.customers||[],setup=labSetupChecklist(),ready=setup.filter(x=>x.done).length,complete=ready===setup.length;
 return pageHeader('Configuration & data','Set up the lab, migrate master data and maintain controlled configuration.')+`<div class="card setup-hero ${complete?'complete':''}"><div class="section-title-row"><div><span class="eyebrow">LAB SETUP</span><h2>${complete?'Lab setup ready':`${ready}/${setup.length} setup areas ready`}</h2><div class="subtle">Guided setup from lab identity through people, equipment, evidence and standards.</div></div>${btn(complete?'Review setup':'Start / continue setup',`data-lab-setup`,'button primary')}</div><div class="setup-progress">${setup.map(x=>`<span class="${x.done?'done':''}" title="${esc(x.label)}"></span>`).join('')}</div><div class="route-toolbar">${btn('Import from existing LIMS',`data-lims-import`,'button secondary')}</div></div><details class="card fold"><summary>Customers & requirements (${customers.length})</summary><div class="section-title-row"><div><span class="eyebrow">CUSTOMERS</span><h2>Customer profiles</h2></div>${btn('+ Add customer','data-add-customer','button small primary')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Retention</th><th>Required approvals</th><th></th></tr></thead><tbody>${customers.map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.retention||'—')}</td><td>${esc((c.requiredApprovals||[]).join(', ')||'Standard')}</td><td>${btn('Edit',`data-edit-customer="${c.id}"`,'button tiny secondary')}</td></tr>`).join('')||'<tr><td colspan="4">No customer profiles yet.</td></tr>'}</tbody></table></div></details><details class="card fold"><summary>Data management</summary><div class="route-toolbar">${btn('Import from LIMS','data-lims-import','button primary')}${btn('Export JSON','data-export','button secondary')}${btn('Import validated JSON','data-import','button secondary')}${btn('Reset demo data','data-reset','button danger')}</div></details><details class="card fold"><summary>System status · REV ${esc(P.VERSION.replace('-poc',''))}</summary><div class="score-row"><span>Schema</span><strong>${esc(App.state.schemaVersion)}</strong></div><div class="score-row"><span>Requests / routes / samples</span><strong>${App.state.requests.length} / ${App.state.routes.length} / ${App.state.serials.length}</strong></div><div class="score-row"><span>Open actions</span><strong>${open}</strong></div><div class="score-row"><span>Invariant validation</span><strong class="${inv.length?'bad-text':'good-text'}">${inv.length?`${inv.length} issue(s)`:'✓ Clean'}</strong></div>${inv.length?`<details><summary>Integrity issues</summary>${inv.map(x=>`<div class="callout bad"><p>${esc(x)}</p></div>`).join('')}</details>`:''}</details>`
}

function labSetupChecklist(){
 P.ensureEnterpriseModel(App.state);const a=App.state.settings?.auditProfile||{},ls=App.state.settings?.labSetup||{},completed=new Set(ls.completedSteps||[]),calRequired=(App.state.equipment||[]).filter(e=>e.calibrationRequired!==false),calEvidence=calRequired.filter(e=>(App.state.calibrationCertificates||[]).some(c=>c.equipmentId===e.id)).length;
 const defs=[
  {id:'identity',label:'Lab identity & scope',minimum:!!(String(a.organisation||'').trim()&&String(a.site||'').trim()&&String(a.scopeStatement||'').trim())},
  {id:'customers',label:'Customers / internal use',minimum:(App.state.customers||[]).length>0||ls.internalOnly===true},
  {id:'products',label:'Products & BOM',minimum:(App.state.products||[]).length>0},
  {id:'people',label:'People & competencies',minimum:(App.state.staff||[]).length>0&&(App.state.competencies||[]).length>0},
  {id:'equipment',label:'Equipment & service durations',minimum:(App.state.equipment||[]).length>0&&(App.state.equipment||[]).every(e=>Number(e.calibrationDurationHours||0)>0&&Number(e.maintenanceDurationHours||0)>0)},
  {id:'evidence',label:'Readiness evidence / start mode',minimum:calRequired.length===0||calEvidence===calRequired.length||ls.readinessStartMode==='schedule'},
  {id:'standards',label:'Released processes & methods',minimum:(App.state.processes||[]).some(p=>p.status==='Released'&&p.workInstruction?.steps?.length)},
  {id:'integrity',label:'Go-live validation',minimum:P.validateInvariants(App.state).length===0}
 ];
 return defs.map((x,i)=>({...x,done:x.minimum&&completed.has(x.id),locked:i>0&&!defs.slice(0,i).every(y=>y.minimum&&completed.has(y.id))}))
}
function labSetupWizard(step=0){
 const steps=labSetupChecklist(),max=steps.length-1,firstOpen=Math.max(0,steps.findIndex(x=>!x.done));step=Math.max(0,Math.min(max,Number(step??firstOpen)));if(steps[step]?.locked)step=firstOpen;App.setupWizardStep=step;const item=steps[step],a=App.state.settings?.auditProfile||{},ls=App.state.settings?.labSetup||{},counter=`${step+1}/${steps.length}`;
 const nav=`<div class="setup-stepper">${steps.map((x,i)=>`<button type="button" class="${i===step?'current':x.done?'done':x.locked?'locked':''}" ${x.locked?'disabled aria-disabled="true"':`data-setup-jump="${i}"`}><span>${x.done?'✓':i+1}</span><small>${esc(x.label)}</small></button>`).join('')}</div>`;
 let body='';
 if(item.id==='identity')body=`<div class="form-grid"><div class="field"><label>Organisation</label><input id="setupOrg" value="${esc(a.organisation||'')}"></div><div class="field"><label>Site / laboratory</label><input id="setupSite" value="${esc(a.site||'')}"></div><div class="field full"><label>Lab scope <small>required</small></label><textarea id="setupScope" placeholder="What work does this LabOS instance control?">${esc(a.scopeStatement||'')}</textarea></div><div class="field"><label>Audit / system owner</label><input id="setupOwner" value="${esc(a.auditOwner||App.state.identity.name)}"></div><div class="field"><label>Records-retention reference</label><input id="setupRetention" value="${esc(a.recordsRetentionReference||'')}"></div></div>`;
 if(item.id==='customers')body=`<div class="setup-current"><strong>${(App.state.customers||[]).length} customer profile(s)</strong><label class="plan-switch"><input id="setupInternalOnly" type="checkbox" ${ls.internalOnly?'checked':''}><span>This lab is internal-only; no customer master is required</span></label></div><details class="fold compact" open><summary>Quick add customer</summary><div class="form-grid"><div class="field"><label>Customer name</label><input id="setupCustomerName"></div><div class="field"><label>Retention reference</label><input id="setupCustomerRetention" placeholder="e.g. R4"></div></div></details>`;
 if(item.id==='products')body=`<div class="setup-current"><strong>${(App.state.products||[]).length} product master record(s)</strong><small>Products are required before engineering can create a build request.</small></div><div class="route-toolbar">${btn('Import products','data-setup-import="products"','button primary')}</div><details class="fold compact"><summary>Quick add product</summary><div class="form-grid"><div class="field"><label>Product family</label><input id="setupProductFamily"></div><div class="field"><label>Part number</label><input id="setupProductPart"></div><div class="field"><label>Revision</label><input id="setupProductRev" value="A"></div><div class="field"><label>Hardware revision</label><input id="setupProductHw"></div></div></details>`;
 if(item.id==='people')body=`<div class="setup-current"><strong>${(App.state.staff||[]).length} people · ${(App.state.competencies||[]).length} competencies · ${(App.state.trainingCertificates||[]).length} training certificate(s)</strong></div><div class="route-toolbar">${btn('Import staff','data-setup-import="staff"','button primary')}${btn('Import competencies','data-setup-import="competencies"','button secondary')}${btn('Import training certificates','data-setup-import="training"','button secondary')}</div><details class="fold compact"><summary>Create starter person + competency</summary><div class="form-grid"><div class="field"><label>Person name</label><input id="setupStaffName"></div><div class="field"><label>Role</label><select id="setupStaffRole"><option value="technician">Technician</option><option value="metrology">Metrology</option><option value="process_engineer">Process Engineer</option><option value="lab_planner">Lab Planner</option></select></div><div class="field"><label>Competency</label><input id="setupSkillName" placeholder="e.g. Dimensional metrology"></div><div class="field"><label>Training duration (h)</label><input id="setupSkillHours" type="number" min="0.25" step="0.25" value="4"></div></div></details>`;
 if(item.id==='equipment'){const eqs=App.state.equipment||[],missing=eqs.filter(e=>Number(e.calibrationDurationHours||0)<=0||Number(e.maintenanceDurationHours||0)<=0);body=`<div class="setup-current"><strong>${eqs.length} equipment record(s)</strong><small>Calibration and maintenance duration must be known so the planner can reserve real capacity.</small></div><div class="route-toolbar">${btn('Import equipment','data-setup-import="equipment"','button primary')}</div>${missing.length?`<details class="fold compact" open><summary>Complete missing service durations · ${missing.length}</summary><div class="setup-duration-list">${missing.map(e=>`<div class="setup-duration-row" data-setup-eq-duration="${esc(e.id)}"><div><strong>${esc(e.name)}</strong><small>${esc(e.id)} · ${esc(e.capability||'Equipment')}</small></div><label>Calibration h<input data-setup-cal-hours="${esc(e.id)}" type="number" min="0.25" step="0.25" value="${Number(e.calibrationDurationHours||0)||''}"></label><label>Maintenance h<input data-setup-maint-hours="${esc(e.id)}" type="number" min="0.25" step="0.25" value="${Number(e.maintenanceDurationHours||0)||''}"></label></div>`).join('')}</div></details>`:''}<details class="fold compact"><summary>Quick add equipment</summary><div class="form-grid"><div class="field"><label>Equipment name</label><input id="setupEqName"></div><div class="field"><label>Capability</label><input id="setupEqCapability" placeholder="e.g. Measurement station"></div><div class="field"><label>Calibration duration (h)</label><input id="setupEqCalHours" type="number" min="0.25" step="0.25" value="4"></div><div class="field"><label>Maintenance duration (h)</label><input id="setupEqMaintHours" type="number" min="0.25" step="0.25" value="4"></div></div></details>`}
 if(item.id==='evidence')body=`<div class="setup-current"><strong>${(App.state.calibrationCertificates||[]).length} calibration · ${(App.state.maintenanceRecords||[]).length} maintenance · ${(App.state.trainingCertificates||[]).length} training record(s)</strong><small>Import existing evidence, or choose a clean start. On a clean start LabOS will schedule required calibration/maintenance/training before first governed use.</small></div><div class="route-toolbar">${btn('Import calibration certificates','data-setup-import="calibration"','button primary')}${btn('Import maintenance','data-setup-import="maintenance"','button secondary')}${btn('Import training certificates','data-setup-import="training"','button secondary')}</div><label class="plan-switch"><input id="setupReadinessSchedule" type="checkbox" ${ls.readinessStartMode==='schedule'?'checked':''}><span>No historical evidence to migrate — start fresh and let LabOS schedule readiness work before first use</span></label>`;
 if(item.id==='standards')body=`<div class="setup-current"><strong>${(App.state.processes||[]).filter(p=>p.status==='Released').length} released processes · ${(App.state.standardTests||[]).filter(t=>t.status==='Released').length} released tests</strong><small>At least one released process with an actual work instruction is needed for controlled execution.</small></div>${(App.state.processes||[]).some(p=>p.status==='Released'&&p.workInstruction?.steps?.length)?'<div class="callout good"><strong>✓ Released controlled process available</strong></div>':`<details class="fold compact" open><summary>Create starter released process</summary><div class="form-grid"><div class="field"><label>Process name</label><input id="setupProcessName"></div><div class="field"><label>Equipment capability</label><input id="setupProcessCapability"></div><div class="field"><label>Operator instruction</label><input id="setupProcessInstruction" placeholder="Perform the controlled operation and record evidence"></div></div></details>`}`;
 if(item.id==='integrity'){const inv=P.validateInvariants(App.state),all=steps.filter(x=>x.id!=='integrity'),open=all.filter(x=>!x.done);body=`<div class="setup-current"><strong>${open.length?'Setup still has open areas':'Ready for go-live'}</strong></div>${open.map(x=>`<div class="audit-guided-row"><div><strong>${esc(x.label)}</strong><small>Complete this setup area before go-live.</small></div>${btn('Open',`data-setup-open-step="${steps.findIndex(y=>y.id===x.id)}"`,'button small primary')}</div>`).join('')}${inv.length?`<details class="fold compact"><summary>Data integrity · ${inv.length} issue(s)</summary>${inv.map(x=>`<div class="callout bad">${esc(x)}</div>`).join('')}</details>`:''}${!open.length&&!inv.length?'<div class="callout good"><strong>✓ Master data and system integrity are ready.</strong></div>':''}`}
 openModal(`Lab setup · ${counter} · ${item.label}`,`${nav}<div class="setup-wizard-body">${body}</div>`,`${step?btn('Back','data-setup-back','button secondary'):''}${btn('Close','data-modal-close','button')}${step<max?btn('Save & continue','data-setup-save-next','button primary'):btn('Complete setup','data-setup-complete','button primary')}`,true);
 setTimeout(()=>bindLabSetupWizard(step),0)
}
function bindLabSetupWizard(step){
 $$('[data-setup-jump]').forEach(b=>b.onclick=()=>labSetupWizard(Number(b.dataset.setupJump)));$$('[data-setup-open-step]').forEach(b=>b.onclick=()=>labSetupWizard(Number(b.dataset.setupOpenStep)));const back=$('[data-setup-back]');if(back)back.onclick=()=>labSetupWizard(step-1);$$('[data-setup-import]').forEach(b=>b.onclick=()=>limsImportModal(b.dataset.setupImport,()=>labSetupWizard(step)));
 const save=async(next=true)=>{const item=labSetupChecklist()[step],a=App.state.settings.auditProfile=App.state.settings.auditProfile||{},ls=App.state.settings.labSetup=App.state.settings.labSetup||{};
  if(item.id==='identity'){const org=$('#setupOrg').value.trim(),site=$('#setupSite').value.trim(),scope=$('#setupScope').value.trim();if(!org||!site||!scope){toast('Organisation, site/laboratory and scope are required.',true);return false}Object.assign(a,{organisation:org,site,scopeStatement:scope,auditOwner:$('#setupOwner').value.trim(),recordsRetentionReference:$('#setupRetention').value.trim()})}
  if(item.id==='customers'){ls.internalOnly=!!$('#setupInternalOnly')?.checked;const name=$('#setupCustomerName')?.value.trim();if(name){App.state.customers=App.state.customers||[];App.state.customers.push({id:P.uid('CUST'),name,retention:$('#setupCustomerRetention')?.value.trim()||'R3',requiredApprovals:['Quality'],specialCharacteristicScheme:['SC'],safeLaunch:false,productSafetyGate:false,reportPreset:'Customer'})}if(ls.internalOnly&&!(App.state.customers||[]).length)App.state.customers.push({id:'CUST-INTERNAL',name:'Internal Development',retention:'R3',requiredApprovals:['Quality'],specialCharacteristicScheme:['SC'],safeLaunch:false,productSafetyGate:false,reportPreset:'Internal'});if(!ls.internalOnly&&!(App.state.customers||[]).length){toast('Add a customer or mark the lab as internal-only.',true);return false}}
  if(item.id==='products'&&!(App.state.products||[]).length){const family=$('#setupProductFamily')?.value.trim(),part=$('#setupProductPart')?.value.trim();if(!family||!part){toast('Import products or create the starter product.',true);return false}App.state.products.push({id:P.uid('PRD'),family,partNumber:part,revision:$('#setupProductRev')?.value.trim()||'A',hw:$('#setupProductHw')?.value.trim()||'—',sw:'—',safety:false,bom:[]})}
  if(item.id==='people'&&!(App.state.staff||[]).length){const name=$('#setupStaffName')?.value.trim(),skillName=$('#setupSkillName')?.value.trim();if(!name||!skillName){toast('Import people/competencies or create the starter records.',true);return false}const skillId=P.uid('COMP'),staffId=P.uid('STAFF');App.state.competencies.push({id:skillId,name:skillName,owner:name,description:'Created by Lab Setup',trainingDurationHours:Number($('#setupSkillHours').value||4),validMonths:24});App.state.staff.push({id:staffId,name,role:$('#setupStaffRole').value,available:true,competencies:[skillId],qualification:'Independent'})}
  if(item.id==='equipment'){if(!(App.state.equipment||[]).length){const name=$('#setupEqName')?.value.trim(),cap=$('#setupEqCapability')?.value.trim();if(!name||!cap){toast('Import equipment or create the starter equipment record.',true);return false}App.state.equipment.push({id:P.uid('EQ'),name,capability:cap,status:'Available',location:a.site||'Lab',calibrationRequired:true,calibrationStatus:'Due',calibrationDue:P.todayISO(),maintenanceStatus:'Due',maintenanceDue:P.todayISO(),calibrationDurationHours:Number($('#setupEqCalHours').value||4),maintenanceDurationHours:Number($('#setupEqMaintHours').value||4)})}else{for(const e of App.state.equipment){const cal=$(`[data-setup-cal-hours="${e.id}"]`),maint=$(`[data-setup-maint-hours="${e.id}"]`);if(cal)e.calibrationDurationHours=Number(cal.value||0);if(maint)e.maintenanceDurationHours=Number(maint.value||0)}const still=(App.state.equipment||[]).filter(e=>Number(e.calibrationDurationHours||0)<=0||Number(e.maintenanceDurationHours||0)<=0);if(still.length){toast(`Set calibration and maintenance duration for ${still[0].name} before continuing.`,true);return false}}}
  if(item.id==='evidence'){const fresh=!!$('#setupReadinessSchedule')?.checked;ls.readinessStartMode=fresh?'schedule':'';if(!fresh){const req=(App.state.equipment||[]).filter(e=>e.calibrationRequired!==false),covered=req.filter(e=>(App.state.calibrationCertificates||[]).some(c=>c.equipmentId===e.id)).length;if(req.length&&covered<req.length){toast('Import calibration evidence for the remaining equipment, or select the clean-start scheduling option.',true);return false}}}
  if(item.id==='standards'&&!(App.state.processes||[]).some(p=>p.status==='Released'&&p.workInstruction?.steps?.length)){const name=$('#setupProcessName')?.value.trim(),cap=$('#setupProcessCapability')?.value.trim(),instruction=$('#setupProcessInstruction')?.value.trim();if(!name||!cap||!instruction){toast('Define a starter process or import/configure released standards first.',true);return false}App.state.processes.push({id:P.uid('PROC'),name,family:'Imported / starter',revision:'A',status:'Released',owner:App.state.identity.name,description:'Created by Lab Setup',setupTime:15,cycleTime:10,basis:'Unit',equipmentCapability:cap,competency:(App.state.competencies||[])[0]?.id||null,params:[],requiredEvidence:['Execution record'],workInstruction:{id:P.uid('WI'),revision:'A',title:`Work instruction · ${name}`,status:'Released',steps:[instruction,'Record required evidence']},revisionHistory:[{rev:'A',status:'Released',date:P.todayISO(),note:'Lab Setup release'}],approvals:[{role:'Administrator',person:App.state.identity.name,date:P.todayISO()}]})}
  const refreshed=labSetupChecklist().find(x=>x.id===item.id);if(!refreshed?.minimum){toast(`Add the minimum required information for ${item.label} before continuing.`,true);return false}ls.completedSteps=Array.from(new Set([...(ls.completedSteps||[]),item.id]));ls.updatedAt=P.now();P.audit(App.state,'Lab setup step completed','Settings','labSetup',item.label,'Completed',`Minimum information verified · ${item.label}`);await persist();return true};
 const next=$('[data-setup-save-next]');if(next)next.onclick=async()=>{if(await save())labSetupWizard(step+1)};const complete=$('[data-setup-complete]');if(complete)complete.onclick=async()=>{if(!(await save(false)))return;const checks=labSetupChecklist(),open=checks.filter(x=>!x.done);if(open.length){toast(`Complete ${open[0].label} first.`,true);labSetupWizard(checks.findIndex(x=>!x.done));return}App.state.settings.labSetup.completedAt=P.now();App.state.settings.labSetup.completedBy=App.state.identity.name;P.audit(App.state,'Lab setup completed','Settings','labSetup','In progress','Ready','All setup checks passed');await persist();closeModal();render();toast('Lab setup complete.')}
}
const LIMS_IMPORT_CONFIG={
 equipment:{label:'Equipment',headers:['equipment_id','name','capability','location','status','calibration_required','calibration_status','calibration_due','calibration_duration_hours','maintenance_status','maintenance_due','maintenance_duration_hours'],required:['equipment_id','name','capability']},
 calibration:{label:'Calibration certificates',headers:['equipment_id','certificate_no','issuer','completed_at','next_due','result','reference_standard','evidence_url'],required:['equipment_id','certificate_no','completed_at','next_due']},
 maintenance:{label:'Maintenance records',headers:['equipment_id','work_order','completed_at','next_due','result','evidence_url'],required:['equipment_id','completed_at','next_due']},
 staff:{label:'Staff',headers:['staff_id','name','role','team','available'],required:['staff_id','name','role']},
 competencies:{label:'Competencies',headers:['competency_id','name','owner','training_duration_hours','valid_months'],required:['competency_id','name']},
 training:{label:'Training certificates',headers:['staff_id','competency_id','certificate_no','issuer','issued_at','expires_at','status','evidence_url'],required:['staff_id','competency_id','certificate_no','expires_at']},
 products:{label:'Products',headers:['product_id','family','part_number','revision','hardware_revision','software_revision','product_safety'],required:['product_id','family','part_number']},
 customers:{label:'Customers',headers:['customer_id','name','retention','required_approvals'],required:['customer_id','name']}
};
function importHeaderKey(x){return String(x||'').trim().toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')}
function importValue(row,...keys){for(const k of keys){const v=row[importHeaderKey(k)];if(v!==undefined&&String(v).trim()!=='')return String(v).trim()}return ''}
function boolValue(v,def=true){if(v==='')return def;return /^(1|true|yes|y|valid|available)$/i.test(String(v))}
function limsTemplate(type){const c=LIMS_IMPORT_CONFIG[type];if(!c)return;downloadTextFile(`LabOS_${type}_import_template.csv`,c.headers.join(',')+'\r\n','text/csv')}
function parseLimsRows(text){const rows=parseCsv(text);if(rows.length<2)return [];const heads=rows[0].map(importHeaderKey);return rows.slice(1).map(cells=>Object.fromEntries(heads.map((h,i)=>[h,String(cells[i]??'').trim()]))) }
function upsert(arr,id,payload){const i=arr.findIndex(x=>x.id===id);if(i>=0)arr[i]={...arr[i],...payload,id};else arr.push({id,...payload})}
function applyLimsImport(state,type,rows){
 P.ensureEnterpriseModel(state);state.products=state.products||[];state.customers=state.customers||[];state.staff=state.staff||[];state.competencies=state.competencies||[];state.equipment=state.equipment||[];state.calibrationCertificates=state.calibrationCertificates||[];state.maintenanceRecords=state.maintenanceRecords||[];state.trainingCertificates=state.trainingCertificates||[];
 const cfg=LIMS_IMPORT_CONFIG[type];if(!cfg)throw new Error('Unsupported import type.');const errors=[];rows.forEach((row,i)=>{for(const req of cfg.required)if(!importValue(row,req,req.replace('_id','id'),req.replace(/_/g,'')))errors.push(`Row ${i+2}: ${req} is required.`)});if(errors.length)throw new Error(errors.slice(0,8).join(' '));
 if(type==='equipment')for(const r of rows){const id=importValue(r,'equipment_id','asset_id','id'),due=importValue(r,'calibration_due','cal_due'),mdue=importValue(r,'maintenance_due','maint_due');upsert(state.equipment,id,{name:importValue(r,'name','equipment_name'),capability:importValue(r,'capability','equipment_capability'),location:importValue(r,'location')||'Lab',status:importValue(r,'status')||'Available',calibrationRequired:boolValue(importValue(r,'calibration_required'),true),calibrationStatus:importValue(r,'calibration_status')||(due&&due<P.todayISO()?'Expired':'Valid'),calibrationDue:due||null,calibrationDurationHours:Number(importValue(r,'calibration_duration_hours','calibration_hours')||4),maintenanceStatus:importValue(r,'maintenance_status')||(mdue&&mdue<P.todayISO()?'Overdue':'Valid'),maintenanceDue:mdue||null,maintenanceDurationHours:Number(importValue(r,'maintenance_duration_hours','maintenance_hours')||4)})}
 if(type==='calibration')for(const r of rows){const eq=importValue(r,'equipment_id','asset_id');if(!state.equipment.some(x=>x.id===eq))throw new Error(`Equipment ${eq} is not registered.`);const no=importValue(r,'certificate_no','certificate_number','cert_no'),next=importValue(r,'next_due','due_date');upsert(state.calibrationCertificates,`CAL-${eq}-${no}`,{equipmentId:eq,certificateNo:no,issuer:importValue(r,'issuer','lab'),completedAt:importValue(r,'completed_at','calibration_date'),nextDue:next,result:importValue(r,'result')||'Pass',referenceStandard:importValue(r,'reference_standard'),evidence:importValue(r,'evidence_url','certificate_url')});const e=state.equipment.find(x=>x.id===eq);e.calibrationDue=next;e.calibrationStatus=next&&next<P.todayISO()?'Expired':'Valid'}
 if(type==='maintenance')for(const r of rows){const eq=importValue(r,'equipment_id','asset_id');if(!state.equipment.some(x=>x.id===eq))throw new Error(`Equipment ${eq} is not registered.`);const wo=importValue(r,'work_order','work_order_no')||P.uid('WO'),next=importValue(r,'next_due','due_date');upsert(state.maintenanceRecords,`MNT-${eq}-${wo}`,{equipmentId:eq,type:'Maintenance',workOrder:wo,completedAt:importValue(r,'completed_at','maintenance_date'),nextDue:next,result:importValue(r,'result')||'Complete',evidence:importValue(r,'evidence_url','document_url')});const e=state.equipment.find(x=>x.id===eq);e.maintenanceDue=next;e.maintenanceStatus=next&&next<P.todayISO()?'Overdue':'Valid'}
 if(type==='staff')for(const r of rows){const id=importValue(r,'staff_id','person_id','employee_id','id'),team=importValue(r,'team');upsert(state.staff,id,{name:importValue(r,'name','full_name'),role:importValue(r,'role')||'technician',team,available:boolValue(importValue(r,'available'),true),competencies:(state.staff.find(x=>x.id===id)?.competencies||[])});if(team){state.teams=state.teams||[];if(!state.teams.includes(team))state.teams.push(team)}}
 if(type==='competencies')for(const r of rows){const id=importValue(r,'competency_id','skill_id','id');upsert(state.competencies,id,{name:importValue(r,'name','skill_name'),owner:importValue(r,'owner'),description:'Imported from legacy LIMS',trainingDurationHours:Number(importValue(r,'training_duration_hours','training_hours')||4),validMonths:Number(importValue(r,'valid_months','validity_months')||24)})}
 if(type==='training')for(const r of rows){const st=importValue(r,'staff_id','person_id'),sk=importValue(r,'competency_id','skill_id'),no=importValue(r,'certificate_no','certificate_number');if(!state.staff.some(x=>x.id===st))throw new Error(`Staff ${st} is not registered.`);if(!state.competencies.some(x=>x.id===sk))throw new Error(`Competency ${sk} is not registered.`);upsert(state.trainingCertificates,`TRN-${st}-${sk}-${no}`,{staffId:st,skillId:sk,certificateNo:no,issuer:importValue(r,'issuer'),issuedAt:importValue(r,'issued_at','issue_date')||P.todayISO(),expiresAt:importValue(r,'expires_at','expiry_date'),status:importValue(r,'status')||'Valid',evidence:importValue(r,'evidence_url','certificate_url')});const person=state.staff.find(x=>x.id===st);person.competencies=Array.from(new Set([...(person.competencies||[]),sk]))}
 if(type==='products')for(const r of rows){const id=importValue(r,'product_id','id'),family=importValue(r,'family','product_family'),part=importValue(r,'part_number','part_no');upsert(state.products,id,{family,partNumber:part,revision:importValue(r,'revision')||'A',hw:importValue(r,'hardware_revision','hw_revision')||'—',sw:importValue(r,'software_revision','sw_revision')||'—',safety:boolValue(importValue(r,'product_safety','safety'),false),bom:state.products.find(x=>x.id===id)?.bom||[]})}
 if(type==='customers')for(const r of rows){const id=importValue(r,'customer_id','id');upsert(state.customers,id,{name:importValue(r,'name','customer_name'),retention:importValue(r,'retention')||'R3',requiredApprovals:importValue(r,'required_approvals').split(/[;|]/).map(x=>x.trim()).filter(Boolean),specialCharacteristicScheme:['SC'],safeLaunch:false,productSafetyGate:false,reportPreset:'Customer'})}
 return rows.length
}
function limsImportModal(type='equipment',onDone=null){
 type=LIMS_IMPORT_CONFIG[type]?type:'equipment';App.pendingLimsImport=null;const options=Object.entries(LIMS_IMPORT_CONFIG).map(([k,v])=>`<option value="${k}" ${type===k?'selected':''}>${esc(v.label)}</option>`).join('');openModal('Import from existing LIMS',`<div class="resolution-focus"><span class="eyebrow">CONTROLLED MIGRATION</span><h2>Import master data and evidence</h2><p>Select a dataset, download its template, then export or rename your source columns to the recognised names. LabOS validates the complete import before committing anything.</p></div><div class="form-grid"><div class="field"><label>Dataset</label><select id="limsImportType">${options}</select></div><div class="field"><label>CSV file</label><input id="limsImportFile" type="file" accept=".csv,text/csv"></div></div><div class="route-toolbar">${btn('Download template','data-lims-template','button secondary')}</div><div id="limsImportPreview" class="callout"><strong>No file loaded</strong></div><details class="fold compact"><summary>Recommended migration order & supported data</summary><p><b>1.</b> Customers/products · <b>2.</b> Staff/competencies · <b>3.</b> Equipment · <b>4.</b> Calibration/maintenance/training evidence. Evidence URLs are retained as links. Binary certificate files should remain in the controlled document store and be referenced by URL.</p></details>`,`${btn('Cancel','data-modal-close','button')}${btn('Validate & import','data-lims-commit','button primary')}`,true);
 setTimeout(()=>{const sel=$('#limsImportType'),file=$('#limsImportFile'),preview=$('#limsImportPreview');$('[data-lims-template]').onclick=()=>limsTemplate(sel.value);sel.onchange=()=>{App.pendingLimsImport=null;file.value='';preview.innerHTML='<strong>No file loaded</strong>'};file.onchange=async()=>{const f=file.files?.[0];if(!f)return;try{const rows=parseLimsRows(await f.text()),cfg=LIMS_IMPORT_CONFIG[sel.value];if(!rows.length)throw new Error('No data rows found.');const missing=cfg.required.filter(k=>!Object.prototype.hasOwnProperty.call(rows[0],importHeaderKey(k)));App.pendingLimsImport={type:sel.value,rows};preview.className=`callout ${missing.length?'warn':'good'}`;preview.innerHTML=`<strong>${rows.length} row(s) loaded</strong><p>${missing.length?`Missing expected column(s): ${missing.map(esc).join(', ')}`:'Ready for validation and atomic import.'}</p>`}catch(e){App.pendingLimsImport=null;preview.className='callout bad';preview.textContent=e.message}};$('[data-lims-commit]').onclick=async()=>{const pending=App.pendingLimsImport;if(!pending){toast('Choose a CSV file first.',true);return}const next=P.deepClone(App.state);try{const count=applyLimsImport(next,pending.type,pending.rows),inv=P.validateInvariants(next);if(inv.length)throw new Error(`Import would violate data integrity: ${inv.slice(0,3).join(' ')}`);P.audit(next,'Legacy LIMS import','Configuration',pending.type,'External dataset',`${count} row(s) imported`,LIMS_IMPORT_CONFIG[pending.type].label);replaceStateAtomically(next);await persist();App.pendingLimsImport=null;closeModal();render();toast(`${count} ${LIMS_IMPORT_CONFIG[pending.type].label.toLowerCase()} row(s) imported.`);if(typeof onDone==='function')setTimeout(onDone,0)}catch(e){preview.className='callout bad';preview.textContent=e.message;toast('Import not applied.',true)}}},0)
}
function render(){const p=$('#page');let html='';switch(App.currentView){case'dashboard':html=renderDashboard();break;case'intake':html=renderIntake();break;case'requests':html=renderRequests();break;case'validation':html=renderValidationFuture();break;case'failure-analysis':html=renderFailureAnalysisFuture();break;case'action-centre':html=renderActionCentre();break;case'workspace':html=renderWorkspace();break;case'planning':html=renderPlanning();break;case'products':html=renderProducts();break;case'materials':html=renderMaterialInventoryV1086();break;case'process-library':html=renderProcessLibrary();break;case'equipment-master':html=renderEquipmentMaster();break;case'serials':html=renderSerials();break;case'characterisation':App.filters.qualityTab='msa';html=renderQuality();break;case'quality':html=renderQuality();break;case'reports':html=renderReports();break;case'management':html=renderManagement();break;case'audit-readiness':html=renderAuditReadiness();break;case'admin':html=renderAdmin();break;case'help':html=renderHelp();break;default:html=renderDashboard()}p.innerHTML=html;bindDynamic();if(App.currentView==='workspace')scheduleWorkspaceCockpitLayout();else document.documentElement?.style?.removeProperty('--workspace-cockpit-height')}

function pipelineProjectModal(id=null){const existing=id?(App.state.pipelineProjects||[]).find(x=>x.id===id):null,p=existing||{name:'',productId:App.state.products[0]?.id,quantity:5,probability:.5,startDate:new Date(Date.now()+30*86400000).toISOString().slice(0,10),owner:App.state.identity.name,estimatedCost:0};if(!p.estimatedCost)p.estimatedCost=P.pipelineProjectCost(App.state,p);openModal(existing?'Edit potential project':'Add potential project',`<div class="callout"><h3>Scenario only</h3><p>Potential projects carry both probability-weighted capacity demand and an estimated project cost. The cost may be overridden if commercial knowledge is better than the automatic BOM/process estimate.</p></div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>Project / opportunity name</label><input id="pipeName" value="${esc(p.name)}"></div><div class="field"><label>Product</label><select id="pipeProduct">${App.state.products.map(x=>`<option value="${x.id}" ${p.productId===x.id?'selected':''}>${esc(x.family)}</option>`).join('')}</select></div><div class="field"><label>Quantity</label><input id="pipeQty" type="number" min="1" value="${Number(p.quantity||1)}"></div><div class="field"><label>Probability %</label><input id="pipeProb" type="number" min="1" max="100" value="${Math.round(Number(p.probability||0)*100)}"></div><div class="field"><label>Expected start</label><input id="pipeStart" type="date" value="${esc(p.startDate)}"></div><div class="field"><label>Estimated project cost (€)</label><input id="pipeCost" type="number" min="0" step="1" value="${Number(p.estimatedCost||0).toFixed(0)}"></div><div class="field full"><label>Owner / source</label><input id="pipeOwner" value="${esc(p.owner||'')}"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn(existing?'Save project':'Add project','data-save-pipeline','button primary')}`);setTimeout(()=>{$('[data-save-pipeline]').onclick=async()=>{const name=$('#pipeName').value.trim(),qty=Number($('#pipeQty').value),prob=Math.max(.01,Math.min(1,Number($('#pipeProb').value)/100)),start=$('#pipeStart').value;if(!name||qty<1||!start){toast('Name, quantity and expected start are required.',true);return}const obj=existing||{id:P.uid('PIPE')};Object.assign(obj,{name,productId:$('#pipeProduct').value,quantity:qty,probability:prob,startDate:start,owner:$('#pipeOwner').value.trim()||App.state.identity.name});const entered=Number($('#pipeCost').value||0),auto=P.pipelineProjectCost(App.state,obj);obj.estimatedCost=entered>0?entered:Number(auto.toFixed(2));obj.costSource=entered>0?'manual':'auto';if(!existing)(App.state.pipelineProjects||(App.state.pipelineProjects=[])).push(obj);P.audit(App.state,existing?'Potential project updated':'Potential project added','Pipeline Project',obj.id,existing?'Previous scenario':'—',`${name} · ${Math.round(prob*100)}% · ${P.currency(obj.estimatedCost)}`,start);await persist();closeModal();render();toast('Potential project scenario and cost saved.')}},0)}
function pipelineImpactModal(id){const x=futureProjectImpact(id);if(!x)return;const p=x.project,max=Math.max(1,...x.resources.map(r=>r.hours));openModal(`Scenario impact · ${p.name}`,`<div class="grid cols-4"><div class="mini-kpi"><span>Estimated project cost</span><strong>${P.currency(p.estimatedCost||P.pipelineProjectCost(App.state,p))}</strong></div><div class="mini-kpi"><span>Baseline peak load</span><strong>${x.basePeak.toFixed(0)}%</strong></div><div class="mini-kpi"><span>With probability weighting</span><strong>${x.weightedPeak.toFixed(0)}%</strong><small>${x.weightedDelta>=0?'+':''}${x.weightedDelta.toFixed(0)} pp</small></div><div class="mini-kpi"><span>If project wins (100%)</span><strong>${x.fullPeak.toFixed(0)}%</strong><small>${x.fullDelta>=0?'+':''}${x.fullDelta.toFixed(0)} pp</small></div></div><div class="callout ${x.fullPeak>100?'warn':''}" style="margin-top:12px"><h3>${x.fullPeak>100?'Capacity action would be required if this project wins':'Current lab capacity can absorb this project in the modeled horizon'}</h3><p><strong>${Math.round(p.probability*100)}% probability</strong> · ${p.quantity} units · expected ${P.formatDate(p.startDate)} · probability-weighted equipment demand contribution ${x.weightedHours.toFixed(1)} h.</p></div><div class="card flat" style="margin-top:12px"><div class="section-title-row"><div><span class="eyebrow">INDIVIDUAL RESOURCE IMPACT</span><h3>What this project adds</h3></div></div><div class="ops-load-bars">${x.resources.slice(0,10).map(r=>`<div class="ops-load-row"><div><strong>${esc(r.label)}</strong><small>${esc(r.type)}</small></div><div class="ops-load-track"><span style="width:${100*r.hours/max}%"></span></div><b>${r.hours.toFixed(1)} h</b></div>`).join('')||'<div class="empty compact">No modeled resource demand.</div>'}</div></div>`,`${btn('Close','data-modal-close','button')}${btn('Edit project','data-edit-pipeline-from-impact','button secondary')}`,true);setTimeout(()=>{const e=$('[data-edit-pipeline-from-impact]');if(e)e.onclick=()=>{closeModal();pipelineProjectModal(id)}},0)}

async function removePipelineProject(id){const x=(App.state.pipelineProjects||[]).find(p=>p.id===id);if(!x)return;if(!confirm(`Remove potential project scenario “${x.name}”?`))return;App.state.pipelineProjects=App.state.pipelineProjects.filter(p=>p.id!==id);P.audit(App.state,'Potential project removed','Pipeline Project',id,x.name,'Removed','Scenario only; no committed bookings changed');await persist();render();toast('Potential project removed.')}
