async function releaseRequest(id){try{new P.QualityService(App.state).releaseRequest(id);App.state.serials.filter(s=>s.requestId===id&&!['Hold','Scrapped','Cancelled'].includes(s.status)).forEach(s=>s.releaseState='Released');await persist();render();toast('Build released; eligible serials are ready for delivery.')}catch(e){toast(e.message,true)}}
