 const itemField=mode==='cp'?`<div class="field"><label>Control Plan characteristic</label><select id="mItem">${chars.map(c=>`<option value="${c.id}" ${c.id===chosenChar?.id?'selected':''}>${esc(c.id)} · ${esc(c.characteristic)}</option>`).join('')}</select></div>`:`<div class="field"><label>End-characterisation test</label><select id="mItem">${tests.map(t=>`<option value="${t.id}" ${t.id===chosenTest?.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>`;
