function newSkillWizard(skillId=null){const existing=skillId?App.state.competencies.find(x=>x.id===skillId):null;App.skillWizard={step:0,existingId:existing?.id||null,data:existing?P.deepClone(existing):{owner:App.state.identity.name,validMonths:24,trainingDurationHours:4,status:'Released'}};renderSkillWizard()}
function captureSkillWizard(){const w=App.skillWizard,d=w.data;if(w.step===0){d.name=$('#nsName').value.trim();d.owner=$('#nsOwner').value.trim();d.description=$('#nsDesc').value.trim()}else if(w.step===1){d.requiredCertificate=$('#nsCert').value.trim();d.validMonths=Number($('#nsMonths').value||24);d.trainingDurationHours=Number($('#nsHours').value||4);d.trainingEvidence=$('#nsEvidence').value.trim()}}
function renderSkillWizard(){const w=App.skillWizard,d=w.data,editing=!!w.existingId,labels=['Define skill','Training rule','Review'];let body='';if(w.step===0)body=`<div class="callout"><h3>1 · ${editing?'Edit':'Define'} the competency</h3><p>${editing?'The competency ID is protected because processes, bookings and certificates reference it. Edit the controlled definition without breaking those links.':'Define what the person must be able to do independently and who owns the qualification standard.'}</p></div><div class="form-grid" style="margin-top:12px">${editing?`<div class="field"><label>Competency ID</label><input value="${esc(w.existingId)}" disabled></div>`:''}<div class="field"><label>Skill name</label><input id="nsName" value="${esc(d.name||'')}"></div><div class="field"><label>Owner</label><input id="nsOwner" value="${esc(d.owner||App.state.identity.name)}"></div><div class="field full"><label>Description / scope</label><textarea id="nsDesc">${esc(d.description||'')}</textarea></div></div>`;else if(w.step===1)body=`<div class="callout"><h3>2 · Define how competence is proven</h3><p>${editing?'Changes apply to future training/renewal planning. Existing issued certificates retain their recorded issue date, expiry and evidence.':'The skill cannot be assigned directly to a person. A training certificate with evidence and expiry is required.'}</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Required certificate type</label><input id="nsCert" value="${esc(d.requiredCertificate||'')}" placeholder="e.g. LASER-JOIN-L2"></div><div class="field"><label>Validity (months)</label><input id="nsMonths" type="number" min="1" value="${esc(d.validMonths||24)}"></div><div class="field"><label>Renewal training duration (hours)</label><input id="nsHours" type="number" min="0.5" step="0.5" value="${esc(d.trainingDurationHours||4)}"></div><div class="field full"><label>Training / evidence requirement</label><textarea id="nsEvidence">${esc(d.trainingEvidence||'')}</textarea></div></div>`;else body=`<div class="callout"><h3>3 · Review controlled skill</h3><p>${editing?'Saving updates the competency master and records the change in the audit trail. Existing certificates remain historical records.':'After creation, issue a person-specific certificate before AUTO-PLAN may use that person for the skill.'}</p></div><div class="grid cols-2" style="margin-top:12px"><div class="card"><span class="subtle">Skill</span><strong>${esc(d.name)}</strong></div><div class="card"><span class="subtle">Owner</span><strong>${esc(d.owner)}</strong></div><div class="card"><span class="subtle">Certificate</span><strong>${esc(d.requiredCertificate)}</strong></div><div class="card"><span class="subtle">Validity</span><strong>${esc(d.validMonths)} months</strong></div><div class="card"><span class="subtle">Renewal duration</span><strong>${esc(d.trainingDurationHours||4)} h</strong></div></div><div class="card" style="margin-top:10px"><strong>Training evidence</strong><p>${esc(d.trainingEvidence)}</p></div>`;openModal(`${editing?'Edit competency':'New skill'} · ${labels[w.step]}`,`<div class="wizard-progress">${labels.map((_,i)=>`<div class="wizard-step ${i<w.step?'done':''} ${i===w.step?'active':''}"></div>`).join('')}</div>${body}`,w.step===0?`${btn('Cancel','data-modal-close','button')}${btn('Next →','data-skill-next','button primary')}`:w.step<labels.length-1?`${btn('Back','data-skill-back','button')}${btn('Next →','data-skill-next','button primary')}`:`${btn('Back','data-skill-back','button')}${btn(editing?'Save competency':'Create controlled skill','data-save-new-skill','button primary')}`,true);setTimeout(()=>{const n=$('[data-skill-next]'),b=$('[data-skill-back]'),save=$('[data-save-new-skill]');if(n)n.onclick=()=>{captureSkillWizard();if(w.step===0&&(!d.name||!d.description)){toast('Define the skill name and scope.',true);return}if(w.step===1&&(!d.requiredCertificate||!d.trainingEvidence)){toast('Define the certificate type and training evidence.',true);return}w.step++;renderSkillWizard()};if(b)b.onclick=()=>{captureSkillWizard();w.step--;renderSkillWizard()};if(save)save.onclick=async()=>{if(editing){const target=App.state.competencies.find(x=>x.id===w.existingId);if(!target){toast('Competency no longer exists.',true);return}const before=P.deepClone(target);Object.assign(target,{name:d.name,description:d.description,owner:d.owner,requiredCertificate:d.requiredCertificate,validMonths:Number(d.validMonths||24),trainingDurationHours:Number(d.trainingDurationHours||4),trainingEvidence:d.trainingEvidence,status:target.status||'Released'});P.audit(App.state,'Competency updated','Competency',target.id,`${before.name} · ${before.validMonths} months`,`${target.name} · ${target.validMonths} months`,App.state.identity.name);await persist();closeModal();render();toast('Competency updated. Existing certificates were preserved.')}else{const id=`COMP-${String(App.state.competencies.length+1).padStart(2,'0')}`;App.state.competencies.push({id,name:d.name,description:d.description,owner:d.owner,requiredCertificate:d.requiredCertificate,validMonths:Number(d.validMonths||24),trainingDurationHours:Number(d.trainingDurationHours||4),trainingEvidence:d.trainingEvidence,status:'Released'});P.audit(App.state,'Competency defined','Competency',id,'—','Released',d.name);await persist();closeModal();render();toast('Skill defined. Issue a training certificate before assigning it to staff.')}}},0)}
function newProcessWizard(){App.processWizard={step:0,data:{owner:App.state.identity.name,basis:'Unit',setupTime:30,cycleTime:15,equipmentCapability:App.state.equipment[0]?.capability||'',competency:App.state.competencies[0]?.id||'',fixedCharge:20,consumableCost:5,workInstruction:['Verify inputs','Execute operation using controlled parameters','Record required evidence']}};renderProcessWizard()}
function captureProcessWizard(){const w=App.processWizard,d=w.data;if(w.step===0){d.name=$('#npName').value.trim();d.family=$('#npFamily').value.trim();d.description=$('#npDesc').value.trim()}else if(w.step===1){d.setupTime=Number($('#npSetup').value||0);d.cycleTime=Number($('#npCycle').value||0);d.basis=$('#npBasis').value;d.equipmentCapability=$('#npEq').value;d.competency=$('#npSkill').value;d.fixedCharge=Number($('#npFixed').value||0);d.consumableCost=Number($('#npConsum').value||0)}else if(w.step===2){d.workInstruction=$('#npWI').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);d.requiredEvidence=$('#npEvidence').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);d.params=parseControlledProcessFields($('#npParams')?.value||'')}}
function renderProcessWizard(){const w=App.processWizard,d=w.data,labels=['Need & scope','Planning standard','Work instruction','Review'];let body='';if(w.step===0)body=`<div class="callout"><h3>1 · Need & scope</h3><p>Define what the new process does and why it is needed. It will remain controlled and unavailable to AUTO-PLAN until released.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Process name</label><input id="npName" value="${esc(d.name||'')}"></div><div class="field"><label>Family</label><input id="npFamily" value="${esc(d.family||'Assembly')}"></div><div class="field full"><label>Purpose / operating scope</label><textarea id="npDesc">${esc(d.description||'')}</textarea></div></div>`;else if(w.step===1)body=`<div class="callout"><h3>2 · Define planning & resource standard</h3><p>This becomes the controlled basis for timing and cost until enough same-product actuals exist to refine the estimate.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Setup time (min)</label><input id="npSetup" type="number" min="0" value="${d.setupTime}"></div><div class="field"><label>Cycle time (min)</label><input id="npCycle" type="number" min="0" value="${d.cycleTime}"></div><div class="field"><label>Basis</label><select id="npBasis"><option ${d.basis==='Unit'?'selected':''}>Unit</option><option ${d.basis==='Batch'?'selected':''}>Batch</option></select></div><div class="field"><label>Equipment capability</label><select id="npEq">${[...new Set(App.state.equipment.map(e=>e.capability))].map(x=>`<option ${d.equipmentCapability===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field full"><label>Required certified skill</label><select id="npSkill">${App.state.competencies.map(c=>`<option value="${c.id}" ${d.competency===c.id?'selected':''}>${esc(c.id)} · ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Fixed process charge (€)</label><input id="npFixed" type="number" min="0" value="${d.fixedCharge}"></div><div class="field"><label>Consumables (€ / ${esc(d.basis)})</label><input id="npConsum" type="number" min="0" value="${d.consumableCost}"></div></div>`;else if(w.step===2)body=`<div class="callout"><h3>3 · Controlled work instruction</h3><p>A released process must contain executable work instructions and required objective evidence.</p></div><div class="field" style="margin-top:12px"><label>Work instruction steps — one per line</label><textarea id="npWI">${esc((d.workInstruction||[]).join('\n'))}</textarea></div><div class="field" style="margin-top:12px"><label>Required evidence — one per line</label><textarea id="npEvidence">${esc((d.requiredEvidence||['Guided build completion','Equipment ID','Operator record']).join('\n'))}</textarea></div><div class="field" style="margin-top:12px"><label>Controlled execution data · name | target | unit | batch/sample | type | required/optional</label><textarea id="npParams" placeholder="Recipe | RCP-17 | | batch | recipe | required\nTemperature | 85 | °C | batch | machine | required\nResult | Pass | | sample | observation | required">${esc(controlledProcessFieldsText(d.params||[]))}</textarea></div>`;else body=`<div class="callout"><h3>4 · Review before controlled release</h3><p>Creation sets the process to <b>Under review</b>. A Process Engineer must release it before it can be used as a standard route operation.</p></div><div class="grid cols-2" style="margin-top:12px"><div class="card"><span class="subtle">Process</span><strong>${esc(d.name)}</strong><p>${esc(d.description)}</p></div><div class="card"><span class="subtle">Planning standard</span><strong>${d.setupTime} min setup + ${d.cycleTime} min/${esc(d.basis)}</strong><p>${esc(d.equipmentCapability)} · ${esc(App.state.competencies.find(c=>c.id===d.competency)?.name||d.competency)}</p></div><div class="card"><span class="subtle">Cost basis</span><strong>${P.currency(d.fixedCharge)} fixed + ${P.currency(d.consumableCost)} consumables</strong></div><div class="card"><span class="subtle">Work instruction</span><strong>${(d.workInstruction||[]).length} controlled steps</strong></div></div>`;openModal(`New process · ${labels[w.step]}`,`<div class="wizard-progress">${labels.map((_,i)=>`<div class="wizard-step ${i<w.step?'done':''} ${i===w.step?'active':''}"></div>`).join('')}</div>${body}`,w.step===0?`${btn('Cancel','data-modal-close','button')}${btn('Next →','data-process-next','button primary')}`:w.step<labels.length-1?`${btn('Back','data-process-back','button')}${btn('Next →','data-process-next','button primary')}`:`${btn('Back','data-process-back','button')}${btn('Create for review','data-save-new-process','button primary')}`,true);setTimeout(()=>{const n=$('[data-process-next]'),b=$('[data-process-back]'),save=$('[data-save-new-process]');if(n)n.onclick=()=>{captureProcessWizard();if(w.step===0&&(!d.name||!d.description)){toast('Define process name and scope.',true);return}if(w.step===1&&(!d.equipmentCapability||!d.competency)){toast('Define equipment capability and required certified skill.',true);return}if(w.step===2&&((d.workInstruction||[]).length<2||(d.requiredEvidence||[]).length<1)){toast('At least two work-instruction steps and one evidence item are required.',true);return}w.step++;renderProcessWizard()};if(b)b.onclick=()=>{captureProcessWizard();w.step--;renderProcessWizard()};if(save)save.onclick=async()=>{const id=`PROC-${String(App.state.processes.length+1).padStart(3,'0')}`;App.state.processes.push({id,name:d.name,family:d.family,revision:'A',status:'Under review',owner:App.state.identity.name,description:d.description,setupTime:d.setupTime,cycleTime:d.cycleTime,basis:d.basis,equipmentCapability:d.equipmentCapability,competency:d.competency,fixedCharge:d.fixedCharge,consumableCost:d.consumableCost,params:d.params||[],requiredEvidence:d.requiredEvidence,workInstruction:{id:`WI-${id}`,revision:'A',title:`Work instruction · ${d.name}`,status:'Draft',steps:d.workInstruction},revisionHistory:[{rev:'A',status:'Under review',date:P.todayISO(),note:'Guided process definition'}],approvals:[]});P.audit(App.state,'New process defined','Process',id,'—','Under review','Guided process definition complete');await persist();closeModal();render();toast('Process created Under review. Release only after controlled review.')}} ,0)}
async function releaseLibraryProcess(id){const p=App.state.processes.find(x=>x.id===id);if(!p)return;if(!p.workInstruction?.steps?.length||!p.equipmentCapability||!p.competency||!Number.isFinite(Number(p.setupTime))||!Number.isFinite(Number(p.cycleTime))){toast('Cannot release: work instruction, planning time, equipment capability and certified skill are mandatory.',true);return}p.status='Released';p.workInstruction.status='Released';p.approvals=p.approvals||[];p.approvals.push({role:roleLabel(currentRole()),person:App.state.identity.name,date:P.todayISO()});P.audit(App.state,'Process released','Process',id,'Under review','Released','Controlled definition and work instruction complete');await persist();render();toast('Process released and available for future routes.')}
function editFinanceModal(){const f=App.state.settings.finance;openModal('Finance & costing master data',`<div class="callout"><h3>Controlled costing inputs</h3><p>These rates drive request estimates and management finance KPIs; actual build costs remain separate.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Contingency %</label><input id="finCont" type="number" min="0" value="${f.contingencyPct}"></div>${Object.entries(f.roleRates).map(([r,v])=>`<div class="field"><label>${esc(roleLabel(r))} €/h</label><input data-fin-rate="${r}" type="number" min="0" value="${v}"></div>`).join('')}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save finance rates','data-save-finance','button primary')}`);setTimeout(()=>{$('[data-save-finance]').onclick=async()=>{f.contingencyPct=Number($('#finCont').value||0);$$('[data-fin-rate]').forEach(x=>f.roleRates[x.dataset.finRate]=Number(x.value||0));P.audit(App.state,'Finance master data updated','Settings','finance','Previous rates','Updated',App.state.identity.name);await persist();closeModal();render();toast('Finance rates updated.')}},0)}
function editEquipmentRate(id){const e=App.state.equipment.find(x=>x.id===id);openModal(`Equipment rate · ${e.name}`,`<div class="field"><label>Internal equipment rate €/h</label><input id="eqRate" type="number" min="0" value="${e.hourlyCost}"></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save rate','data-save-eq-rate','button primary')}`);setTimeout(()=>{$('[data-save-eq-rate]').onclick=async()=>{e.hourlyCost=Number($('#eqRate').value||0);P.audit(App.state,'Equipment rate updated','Equipment',id,'Previous rate',e.hourlyCost,'Finance costing');await persist();closeModal();render();toast('Equipment rate updated.')}},0)}
function editMaterialCost(id){const m=App.state.materials.find(x=>x.id===id);openModal(`Material cost · ${m.partNumber} Rev ${m.revision}`,`<div class="field"><label>Standard material cost €/unit</label><input id="matCost" type="number" min="0" step="0.01" value="${m.unitCost||0}"></div><div class="callout" style="margin-top:10px"><p>This standard cost is used for prototype estimates. Issued-lot actual purchase cost can replace it in the later enterprise integration.</p></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save cost','data-save-mat-cost','button primary')}`);setTimeout(()=>{$('[data-save-mat-cost]').onclick=async()=>{const prev=m.unitCost;m.unitCost=Number($('#matCost').value||0);P.audit(App.state,'Material standard cost updated','Material',id,prev,m.unitCost,'Finance costing');await persist();closeModal();render();toast('Material cost updated.')}},0)}
function equipmentServiceModal(id,type){if(type==='calibration'){addCalibrationCertificateModal(id);return}const e=App.state.equipment.find(x=>x.id===id);if(!e)return;openModal(`Maintenance · ${e.name}`,`<div class="form-grid"><div class="field"><label>Completed date</label><input id="svcDate" type="date" value="${P.todayISO()}"></div><div class="field"><label>Next due date</label><input id="svcDue" type="date" value="${new Date(Date.now()+120*86400000).toISOString().slice(0,10)}"></div><div class="field full"><label>Work-order / controlled reference</label><input id="svcEvidence" placeholder="WO-1234 or controlled URL"></div><div class="field full"><label>Maintenance record / certificate file</label><input id="svcFile" type="file" accept=".pdf,.jpg,.jpeg,.png,.txt"></div><div class="field full"><label>Result / comment</label><textarea id="svcComment">Completed satisfactory</textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Record maintenance','data-save-eq-service','button primary')}`);setTimeout(()=>{$('[data-save-eq-service]').onclick=async()=>{const ev=$('#svcEvidence').value.trim(),file=$('#svcFile').files?.[0];if(!ev&&!file){toast('Add a work-order/reference or upload objective maintenance evidence.',true);return}const fileData=file?await readFileDataUrl(file):null,rec={id:P.uid('MNT'),equipmentId:id,type:'Maintenance',completedAt:$('#svcDate').value,nextDue:$('#svcDue').value,evidence:ev||file?.name||'',fileName:file?.name||'',fileType:file?.type||'',fileData,documentUploaded:!!fileData,comment:$('#svcComment').value.trim(),person:App.state.identity.name};App.state.maintenanceRecords.push(rec);e.maintenanceStatus='Valid';e.lastMaintenance=rec.completedAt;e.maintenanceDue=rec.nextDue;for(const b of App.state.resourceCareBookings||[])if(b.status==='Scheduled'&&b.type==='Maintenance'&&b.equipmentId===id)b.status='Completed';App.state.actions=(App.state.actions||[]).filter(a=>!(a.careType==='Maintenance'&&a.objectId===id));P.audit(App.state,'Maintenance recorded','Equipment',id,'Previous due date',rec.nextDue,rec.evidence);await persist();closeModal();render();toast('Maintenance completion recorded and scheduled action closed.')}},0)}
function viewCalibrationCertificates(id){const e=App.state.equipment.find(x=>x.id===id),rows=(App.state.calibrationCertificates||[]).filter(c=>c.equipmentId===id).sort((a,b)=>String(b.completedAt).localeCompare(String(a.completedAt)));const mayAdd=can('calibration:manage')||currentRole()==='administrator';openModal(`Calibration certificates · ${e.name}`,`<div class="table-wrap"><table class="data-table"><thead><tr><th>Certificate</th><th>Issuer</th><th>Completed</th><th>Next due</th><th>Evidence</th><th>Result</th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.certificateNo)}</strong></td><td>${esc(c.issuer||'—')}</td><td>${P.formatDate(c.completedAt)}</td><td>${P.formatDate(c.nextDue)}</td><td>${evidenceDocumentLink(c,'Open certificate')}<small>${esc(c.referenceStandard||'')}</small></td><td>${status(c.result||c.status||'Recorded')}</td></tr>`).join('')||'<tr><td colspan="6">No calibration certificate recorded.</td></tr>'}</tbody></table></div>`,`${btn('Close','data-modal-close','button')}${mayAdd?btn('+ Add certificate',`data-modal-add-cal="${id}"`,'button primary'):''}`,true);setTimeout(()=>{const b=$('[data-modal-add-cal]');if(b)b.onclick=()=>addCalibrationCertificateModal(id)},0)}
function careLocalDateTimeValue(iso){if(!iso)return '';const d=new Date(iso);if(Number.isNaN(d.getTime()))return '';const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function careScheduleModal(ids){
 const svc=new P.ResourceCareService(),forecast=svc.forecast(App.state,Number(App.filters.careWeeks||26)),items=ids.map(id=>forecast.find(x=>x.id===id||x.itemKey===id)).filter(Boolean);if(!items.length){toast('The selected readiness items are no longer available. Refresh the board.',true);return}
 const rows=items.map((x,i)=>`<div class="care-schedule-item" data-care-modal-row="${i}"><div class="section-title-row"><div><span class="pill">${esc(x.type)}</span><h3>${esc(x.targetName)}</h3><div class="subtle">Due ${P.formatDate(x.dueDate)}${x.nextUseStart?` · next planned use ${P.formatDateTime(x.nextUseStart)}`:''}</div></div>${careDueVisual(x)}</div><div class="care-suggestion-box"><div><span>Best current slot</span><strong data-care-suggestion-label="${i}">${P.formatDateTime(x.recommendedStart)}</strong></div>${btn('Use best slot',`data-care-use-suggestion="${i}"`,'button tiny secondary')}</div><div class="form-grid"><div class="field"><label>Scheduled start</label><input type="datetime-local" data-care-start="${i}" value="${careLocalDateTimeValue(x.scheduledStart||x.recommendedStart)}"></div><div class="field"><label>Duration (hours)</label><input type="number" min="0.25" step="0.25" data-care-duration="${i}" value="${Number(x.durationHours||4)}"></div><div class="field full"><label>Scheduling note <small>optional</small></label><input data-care-note="${i}" placeholder="Provider, work order or reason"></div></div><div class="care-preview" data-care-preview="${i}"></div></div>`).join('');
 openModal(`Schedule readiness work · ${items.length} item${items.length===1?'':'s'}`,`<div class="callout"><strong>No manual replanning.</strong><p>If your chosen calibration, maintenance or training slot overlaps build work, LabOS will move the affected build bookings automatically. Fixed lab events/readiness reservations are never silently overridden.</p></div><div class="section-stack care-schedule-list">${rows}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Schedule & resolve', 'data-apply-care-schedule','button primary')}`,true);
 setTimeout(()=>{
  const itemAt=i=>({...items[i],durationHours:Number($(`[data-care-duration="${i}"]`).value||items[i].durationHours||1)});
  const update=i=>{const item=itemAt(i),input=$(`[data-care-start="${i}"]`),box=$(`[data-care-preview="${i}"]`);if(!input||!box)return;try{const pv=svc.previewSlot(App.state,item,input.value);if(pv.careConflicts.length||pv.eventConflicts.length)box.innerHTML='<span class="status bad">✕ Fixed resource/lab collision</span><small>Use the best slot; LabOS will not save an unresolved collision.</small>';else if(pv.affectedRequestIds.length)box.innerHTML=`<span class="status warn">● Auto-resolution required</span><small>${pv.affectedRequestIds.length} build${pv.affectedRequestIds.length===1?'':'s'} will be automatically replanned around this reservation: ${pv.affectedRequestIds.map(esc).join(', ')}.</small>`;else box.innerHTML='<span class="status good">✓ Resolvable</span><small>No manual follow-up will be required.</small>';}catch(e){box.innerHTML=`<span class="status bad">✕ ${esc(e.message)}</span>`}};
  const recalc=i=>{try{const h=Number($(`[data-care-duration="${i}"]`).value),best=svc.recommendForDuration(App.state,items[i],h);items[i]={...items[i],...best,durationHours:h};const lab=$(`[data-care-suggestion-label="${i}"]`);if(lab)lab.textContent=P.formatDateTime(items[i].recommendedStart);update(i)}catch(e){toast(e.message,true)}};
  items.forEach((_,i)=>{const inp=$(`[data-care-start="${i}"]`),dur=$(`[data-care-duration="${i}"]`),use=$(`[data-care-use-suggestion="${i}"]`);if(inp){inp.onchange=()=>update(i);update(i)}if(dur)dur.onchange=()=>recalc(i);if(use)use.onclick=()=>{recalc(i);inp.value=careLocalDateTimeValue(items[i].recommendedStart);update(i)}});
  const apply=$('[data-apply-care-schedule]');if(apply)apply.onclick=async()=>{try{const working=P.deepClone(App.state),svc2=new P.ResourceCareService(),summary=[];for(let i=0;i<items.length;i++){const item={...items[i],durationHours:Number($(`[data-care-duration="${i}"]`).value)},start=$(`[data-care-start="${i}"]`).value,note=$(`[data-care-note="${i}"]`).value.trim(),r=svc2.scheduleResolved(working,item,start,{note,durationHours:item.durationHours});summary.push(r)}for(const k of Object.keys(App.state))delete App.state[k];Object.assign(App.state,working);await persist();closeModal();render();const n=summary.reduce((a,r)=>a+r.replanned.length,0);toast(n?`${items.length} readiness item${items.length===1?'':'s'} scheduled; ${n} affected build plan${n===1?'':'s'} automatically updated.`:`${items.length} readiness item${items.length===1?'':'s'} scheduled. Scheduling reserves the work; completion evidence is still required before readiness clears.`)}catch(e){toast(e.message,true)}};
 },0)
}
async function scheduleCare(id){careScheduleModal([id])}
async function unscheduleCare(itemKey){new P.ResourceCareService().unschedule(App.state,itemKey);await persist();render();toast('Readiness slot removed from the planning calendar.')}

async function runDailyOperationsReview(force=true){const review=new P.ImprovementService().dailyReview(App.state,{force});await persist();render();toast(`Operations check complete · ${review.total} improvement executable proposal(s), ${review.highCount} high priority.`);return review}
function latestImprovementDecision(id){return (App.state.improvementDecisions||[]).filter(d=>d.proposalId===id).sort((a,b)=>String(b.at||'').localeCompare(String(a.at||'')))[0]||null}
function improvementResolveTarget(x){const t=String(x?.type||'').toLowerCase(),title=String(x?.title||'').toLowerCase();if(t==='skills'||/calibration|maintenance/.test(title)||t==='equipment')return 'resource-assurance';if(t==='staffing'||t==='capacity')return 'planning';if(t==='process')return 'process-library';if(t==='quality')return 'quality';return 'action-centre'}
function improvementImplementationModal(actionId){
 const a=(App.state.actions||[]).find(x=>x.id===actionId&&x.improvementProposalId);if(a)App.state.actions=(App.state.actions||[]).filter(x=>x.id!==a.id);
 toast('This legacy improvement action was withdrawn. Run the improvement scan again; REV 1.0.55 only shows proposals LabOS can implement and verify automatically.',true);persist().then(()=>render());
}
function showAppliedImprovementResult(x,apply){
 const rows=(apply.changes||[]).map(c=>`<div class="score-row"><span>${esc(c.requestId||'Plan')} · ${esc(c.task||'Booking')}</span><strong>${esc(c.from)} → ${esc(c.to)}</strong></div>`).join('');
 openModal('Improvement implemented',`<div class="callout good"><span class="status good">✓ Implemented</span><h3>${esc(x.title)}</h3><p>${esc(apply.summary||'LabOS applied and verified the accepted proposal.')}</p></div>${rows?`<div class="card">${rows}</div>`:''}<details class="fold compact"><summary>Implementation evidence</summary><p>The proposal was prevalidated before display. On acceptance LabOS rechecked qualifications/readiness, collisions and affected controlled records before committing the change. No manual replanning is required.</p></details>`,btn('Done','data-modal-close','button primary'));
}
function improvementDecisionModal(id,decision){
 const service=new P.ImprovementService(),x=(App.state.improvementProposals||service.generate(App.state)).find(p=>p.id===id)||latestImprovementDecision(id)?.snapshot;if(!x){toast('This proposal is no longer executable and has been withdrawn.',true);service.generate(App.state);render();return}
 const defaultDate=new Date(Date.now()+(decision==='Deferred'?7:14)*86400000).toISOString().slice(0,10),label=decision==='Accepted'?'Accept & implement now':decision==='Rejected'?'Reject / not applicable':'Defer review',preview=(x.previewChanges||[]).map(c=>`<div class="score-row"><span>${esc(c.requestId||'Plan')} · ${esc(c.task||'Booking')}</span><strong>${esc(c.from)} → ${esc(c.to)}</strong></div>`).join('');
 openModal(`${label} · ${x.type}`,`<div class="callout ${decision==='Rejected'?'bad':'warn'}"><h3>${esc(x.title)}</h3><p>${esc(x.why)}</p></div><div class="score-row"><span>Action</span><strong>${esc(x.proposal)}</strong></div>${decision==='Accepted'?`${preview?`<div class="card"><span class="eyebrow">PREVALIDATED CHANGES</span>${preview}</div>`:''}<div class="callout"><strong>Accept = implement.</strong><p>LabOS will revalidate these changes, update the controlled bookings and route assignments, and verify the result before committing. If anything has changed and the proposal can no longer be completed, nothing is applied and the proposal is withdrawn.</p></div>`:''}<div class="form-grid" style="margin-top:12px">${decision!=='Accepted'?`<div class="field"><label>${decision==='Deferred'?'Review again':'Decision owner'}</label><input id="impOwner" value="${esc(x.owner||App.state.identity.name)}"></div><div class="field"><label>${decision==='Deferred'?'Review date':'Reference date'}</label><input id="impDue" type="date" value="${defaultDate}"></div>`:''}<div class="field full"><label>Decision rationale</label><textarea id="impNote" placeholder="Why are you ${decision==='Accepted'?'accepting':'making'} this decision?"></textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn(label,`data-save-improvement-decision="${esc(id)}|${decision}"`,'button primary')}`,true);
 setTimeout(()=>{$('[data-save-improvement-decision]').onclick=async()=>{const note=$('#impNote').value.trim();if(!note){toast('Record the decision rationale before continuing.',true);return}let apply=null;if(decision==='Accepted'){apply=service.implementAccepted(App.state,x);if(apply.mode!=='automatic'||!apply.verified){service.generate(App.state);await persist();closeModal();render();toast(`Proposal withdrawn: ${apply.reason||'LabOS can no longer implement it end-to-end.'}`,true);return}}
   const owner=decision==='Accepted'?(x.owner||App.state.identity.name):($('#impOwner')?.value.trim()||x.owner||App.state.identity.name),due=decision==='Accepted'?null:($('#impDue')?.value||defaultDate),rec={id:P.uid('IMPD'),proposalId:id,decision,at:P.now(),actor:App.state.identity.name,owner,note,reviewAfter:due||null,snapshot:P.deepClone(x),implementation:apply?{status:'Implemented & verified',summary:apply.summary,changes:P.deepClone(apply.changes||[]),verifiedAt:P.now()}:null};App.state.improvementDecisions=App.state.improvementDecisions||[];App.state.improvementDecisions.push(rec);P.audit(App.state,decision==='Accepted'?'Improvement accepted and implemented':`Improvement proposal ${decision.toLowerCase()}`,'Improvement',id,'Proposed',decision,`${note}${apply?' · '+apply.summary:''}`);service.generate(App.state);await persist();closeModal();render();if(decision==='Accepted')showAppliedImprovementResult(x,apply);else toast(decision==='Rejected'?'Improvement rejected; rationale retained.':'Improvement deferred; review date retained.');}},0)
}
function improvementModal(id){
 const service=new P.ImprovementService(),x=(App.state.improvementProposals||service.generate(App.state)).find(p=>p.id===id)||latestImprovementDecision(id)?.snapshot;if(!x)return;const d=latestImprovementDecision(id),implemented=d?.decision==='Accepted'&&d?.implementation?.status==='Implemented & verified',preview=(x.previewChanges||[]).map(c=>`<div class="score-row"><span>${esc(c.requestId||'Plan')} · ${esc(c.task||'Booking')}</span><strong>${esc(c.from)} → ${esc(c.to)}</strong></div>`).join('');
 openModal(`Improvement proposal · ${x.type}`,`${d?`<div class="callout ${implemented?'good':''}"><strong>${implemented?'✓ Implemented & verified':`Latest decision · ${esc(d.decision)}`}</strong><p>${P.formatDateTime(d.at)} · ${esc(d.actor||'')}${d.note?' · '+esc(d.note):''}</p>${implemented?`<p>${esc(d.implementation.summary||'')}</p>`:''}</div>`:''}<div class="callout warn"><h3>${esc(x.title)}</h3><p>${esc(x.why)}</p></div><div class="score-row"><span>Proposed action</span><strong>${esc(x.proposal)}</strong></div><div class="score-row"><span>Expected impact</span><strong>${esc(x.impact)}</strong></div>${preview&&!d?`<details class="fold compact"><summary>Exact prevalidated changes</summary>${preview}</details>`:''}`,`${btn('Close','data-modal-close','button')}${d?'':`${btn('Reject',`data-improvement-decision="${esc(id)}|Rejected"`,'button danger')}${btn('Defer',`data-improvement-decision="${esc(id)}|Deferred"`,'button secondary')}${btn('Accept & implement now',`data-improvement-decision="${esc(id)}|Accepted"`,'button primary')}`}`);
}
