const _addCalibrationCertificateModal1055=addCalibrationCertificateModal;
addCalibrationCertificateModal=function(id){const e=App.state.equipment.find(x=>x.id===id);if(!e)return;const defaultDue=new Date();defaultDue.setMonth(defaultDue.getMonth()+6);openModal(`Add calibration certificate · ${e.name}`,`<div class="callout"><h3>Certificate receipt ≠ calibration approval</h3><p>Whether calibration is performed in-house, by another internal function or externally, a passing certificate remains <b>Pending approval</b> until an authorised reviewer accepts the evidence.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Source</label><select id="ccSource"><option>External</option><option>Internal service</option><option>In-house</option></select></div><div class="field"><label>Certificate number</label><input id="ccNo"></div><div class="field"><label>Calibration laboratory / issuer</label><input id="ccIssuer"></div><div class="field"><label>Calibration date</label><input id="ccDate" type="date" value="${P.todayISO()}"></div><div class="field"><label>Next due date</label><input id="ccDue" type="date" value="${defaultDue.toISOString().slice(0,10)}"></div><div class="field full"><label>Traceability / reference standard</label><input id="ccTrace"></div><div class="field"><label>Result</label><select id="ccResult"><option>Pass</option><option>Limited use</option><option>Fail</option></select></div><div class="field"><label>Calibration certificate file <small>(required for Pass)</small></label><input id="ccFile" type="file" accept=".pdf,.jpg,.jpeg,.png,.txt"></div><div class="field full"><label>Controlled document reference</label><input id="ccEvidence"></div><div class="field full"><label>Comment</label><textarea id="ccComment">Calibration certificate received; formal review pending.</textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Record certificate for approval','data-save-cal-certificate-v1056','button next-action')}`,true);setTimeout(()=>{$('[data-save-cal-certificate-v1056]').onclick=async()=>{try{const no=$('#ccNo').value.trim(),issuer=$('#ccIssuer').value.trim(),file=$('#ccFile').files?.[0],result=$('#ccResult').value;if(!no||!issuer){toast('Certificate number and issuer are required.',true);return}if(result==='Pass'&&!file){toast('A passing calibration certificate file is required.',true);return}const fileData=file?await readFileDataUrl(file):null,cert={id:P.uid('CALCERT'),equipmentId:id,sourceType:$('#ccSource').value,certificateNo:no,issuer,referenceStandard:$('#ccTrace').value.trim(),completedAt:$('#ccDate').value,nextDue:$('#ccDue').value,result,status:result==='Pass'?'Pending approval':'Attention',approvalStatus:'Pending approval',approvedBy:'',approvedAt:null,approvalRationale:'',evidence:$('#ccEvidence').value.trim()||file?.name||'',fileName:file?.name||'',fileType:file?.type||'',fileSize:file?.size||0,fileData,documentUploaded:!!fileData,comment:$('#ccComment').value.trim(),person:App.state.identity.name};App.state.calibrationCertificates=App.state.calibrationCertificates||[];App.state.calibrationCertificates.push(cert);App.state.maintenanceRecords=App.state.maintenanceRecords||[];App.state.maintenanceRecords.push({id:P.uid('CAL'),equipmentId:id,type:'Calibration',completedAt:cert.completedAt,nextDue:cert.nextDue,evidence:cert.evidence,comment:cert.comment,person:cert.person,certificateId:cert.id,status:'Awaiting certificate approval'});e.calibrationStatus=result==='Pass'?'Pending approval':'Invalid';e.calibrationDue=cert.nextDue;e.calibrationCertificateValid=false;P.audit(App.state,'Calibration certificate received','Equipment',id,'Previous certificate history',`${no} · Pending approval`,`${issuer} · ${result} · ${cert.sourceType}`);await persist();closeModal();render();toast(`Certificate ${no} recorded. Equipment remains unavailable until formal approval.`,true)}catch(err){toast(`Certificate upload failed: ${err.message}`,true)}}},0)};
function approveCalibrationCertificate(id){const c=(App.state.calibrationCertificates||[]).find(x=>x.id===id),e=(App.state.equipment||[]).find(x=>x.id===c?.equipmentId);if(!c||!e)return;if(!['administrator','quality','metrology','lab_manager','approver'].includes(currentRole())){toast('Calibration certificate approval requires an authorised Metrology, Quality, Lab Manager or Approver role.',true);return}if(App.state.settings?.separationOfDuties&&c.person===App.state.identity.name&&currentRole()!=='administrator'){toast('Separation of duties prevents the person who recorded the certificate from formally approving it.',true);return}openModal(`Approve calibration certificate · ${c.certificateNo}`,`<div class="callout"><h3>Formal certificate review</h3><p>Confirm identity, traceability, calibration result, dates, stated limitations and certificate evidence before making the asset calibration-ready.</p></div><div class="score-row"><span>Issuer / source</span><strong>${esc(c.issuer)} · ${esc(c.sourceType||'—')}</strong></div><div class="score-row"><span>Traceability</span><strong>${esc(c.referenceStandard||'—')}</strong></div><div class="score-row"><span>Period</span><strong>${P.formatDate(c.completedAt)} → ${P.formatDate(c.nextDue)}</strong></div><div class="field"><label>Review conclusion <b>required</b></label><textarea id="calApproveNote"></textarea></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Reject certificate','data-cal-cert-decision="Rejected"','button blocker-action')}${btn('Approve certificate','data-cal-cert-decision="Approved"','button next-action')}`);setTimeout(()=>{$$('[data-cal-cert-decision]').forEach(b=>b.onclick=async()=>{const note=$('#calApproveNote').value.trim();if(!note){toast('Record the review conclusion.',true);return}const decision=b.dataset.calCertDecision;c.approvalStatus=decision;c.approvedBy=App.state.identity.name;c.approvedAt=P.now();c.approvalRationale=note;c.status=decision==='Approved'&&c.result==='Pass'?'Valid':'Attention';e.calibrationStatus=decision==='Approved'&&c.result==='Pass'?'Valid':'Invalid';e.calibrationCertificateValid=!!P.validCalibrationCertificate(App.state,e.id,P.todayISO());if(e.calibrationCertificateValid&&e.status==='Commissioning')e.status='Available';if(decision==='Approved')for(const rb of App.state.resourceCareBookings||[])if(rb.type==='Calibration'&&rb.equipmentId===e.id&&['Scheduled','Awaiting certificate approval'].includes(rb.status))rb.status='Completed';P.audit(App.state,`Calibration certificate ${decision.toLowerCase()}`,'Calibration certificate',c.id,'Pending approval',decision,note);await persist();closeModal();render();toast(decision==='Approved'?'Certificate approved; equipment calibration readiness recalculated.':'Certificate rejected; equipment remains unavailable.',decision!=='Approved')})},0)}
viewCalibrationCertificates=function(id){const e=App.state.equipment.find(x=>x.id===id),rows=(App.state.calibrationCertificates||[]).filter(c=>c.equipmentId===id).sort((a,b)=>String(b.completedAt).localeCompare(String(a.completedAt))),mayAdd=can('calibration:manage')||currentRole()==='administrator',mayApprove=['administrator','quality','metrology','lab_manager','approver'].includes(currentRole());openModal(`Calibration certificates · ${e.name}`,`<div class="table-wrap"><table class="data-table"><thead><tr><th>Certificate</th><th>Source / issuer</th><th>Dates</th><th>Evidence</th><th>Result</th><th>Formal approval</th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.certificateNo)}</strong></td><td>${esc(c.sourceType||'—')}<small>${esc(c.issuer||'—')}</small></td><td>${P.formatDate(c.completedAt)}<small>Due ${P.formatDate(c.nextDue)}</small></td><td>${evidenceDocumentLink(c,'Open certificate')}<small>${esc(c.referenceStandard||'')}</small></td><td>${status(c.result||c.status||'Recorded')}</td><td>${c.approvalStatus==='Approved'?`<span class="status good">✓ Approved</span><small>${esc(c.approvedBy||'')} · ${P.formatDateTime(c.approvedAt)}</small>`:c.approvalStatus==='Rejected'?'<span class="status bad">✕ Rejected</span>':`${status('Pending approval')}${mayApprove?btn('Review',`data-cal-cert-approve="${c.id}"`,'button tiny next-action'):''}`}</td></tr>`).join('')||'<tr><td colspan="6">No calibration certificate recorded.</td></tr>'}</tbody></table></div>`,`${btn('Close','data-modal-close','button')}${mayAdd?btn('+ Add certificate',`data-modal-add-cal="${id}"`,'button next-action'):''}`,true);setTimeout(()=>{const add=$('[data-modal-add-cal]');if(add)add.onclick=()=>addCalibrationCertificateModal(id);$$('[data-cal-cert-approve]').forEach(b=>b.onclick=()=>{closeModal();approveCalibrationCertificate(b.dataset.calCertApprove)})},0)};

const _readinessBlockerModal1055=readinessBlockerModal;
readinessBlockerModal=function(requestId,name){_readinessBlockerModal1055(requestId,name);setTimeout(()=>{const modal=$('#modalRoot .modal');if(!modal)return;let footer=modal.querySelector('.modal-footer');if(!footer){footer=document.createElement('div');footer.className='modal-footer';modal.appendChild(footer)}if(currentRole()==='administrator'&&!footer.querySelector('[data-v1056-readiness-exception]')){const b=document.createElement('button');b.className='button admin-exception';b.type='button';b.dataset.v1056ReadinessException='1';b.textContent='Administrator exception…';b.onclick=()=>{closeModal();adminExceptionModal('Build',requestId,'Lifecycle gate')};footer.prepend(b)}if(!footer.querySelector('[data-v1056-readiness-recheck]')){const b=document.createElement('button');b.className='button blocker-action';b.type='button';b.dataset.v1056ReadinessRecheck='1';b.textContent='Recheck blocker';b.onclick=()=>{const rs=new P.ReadinessService(App.state).evaluate(requestId),still=(rs.issues||[]).some(x=>x.name===name);closeModal();render();if(still){toast('Blocker remains open because the underlying evidence is still incomplete.',true);setTimeout(()=>readinessBlockerModal(requestId,name),50)}else toast(rs.ready?'Blocker cleared. Build Readiness is now satisfied.':'This blocker cleared; other readiness items remain.')};footer.appendChild(b)}},0)};
const _auditFindingModal1055=auditFindingModal;
auditFindingModal=function(key){_auditFindingModal1055(key);setTimeout(()=>{const modal=$('#modalRoot .modal'),footer=modal?.querySelector('.modal-footer');if(!footer||footer.querySelector('[data-audit-recheck-v1056]'))return;const b=document.createElement('button');b.className='button blocker-action';b.type='button';b.dataset.auditRecheckV1056=key;b.textContent='Recheck finding';b.onclick=()=>{const a=auditAssessment(App.filters.auditFramework||'iatf'),r=a.rules.find(x=>x.key===key);closeModal();render();if(r&&r.status!=='Pass'){toast(`Finding remains ${r.status}: underlying controlled evidence has not yet satisfied the rule.`,true);setTimeout(()=>auditFindingModal(key),50)}else toast('Finding cleared after evidence recheck.')};footer.appendChild(b)},0)};

