function installSectionNavigator(){const page=$('#page');if(!page||!document.createElement)return;page.querySelector('.section-jump-nav')?.remove();let cards=[];for(const el of Array.from(page.querySelectorAll('.card, details.card'))){if(el.closest('.modal')||el.closest('.card .card'))continue;const h=el.querySelector(':scope > .section-title-row .eyebrow, :scope > .eyebrow, :scope > .section-title-row h2, :scope > h2, :scope > summary strong');if(!h)continue;const text=(h.textContent||'').trim();if(!text||/NEXT ACTION|MANAGEMENT ATTENTION/i.test(text))continue;cards.push({el,text})}const seen=new Set();cards=cards.filter(x=>{const k=x.text.toLowerCase();if(seen.has(k))return false;seen.add(k);return true}).slice(0,14);if(cards.length<3&&App.currentView!=='workspace')return;const nav=document.createElement('nav');nav.className=`section-jump-nav ${App.currentView==='workspace'?'workspace-section-jump':''}`;nav.setAttribute('aria-label','Jump to section');const entries=cards.map((x,i)=>{if(!x.el.id)x.el.id=`section-${App.currentView}-${i+1}`;return `<button type="button" data-section-jump="${esc(x.el.id)}">${esc(x.text.replace(/^\d+\s*·\s*/,''))}</button>`});if(App.currentView==='workspace'&&App.workspaceId)entries.push('<button type="button" data-jump-learning="1">Lessons</button>');nav.innerHTML=entries.join('');const anchor=page.querySelector('.page-header')||page.querySelector('.workspace-cockpit-spacer')||page.firstElementChild;if(anchor&&typeof anchor.after==='function')anchor.after(nav);else if(typeof page.insertBefore==='function')page.insertBefore(nav,page.firstChild||null);else if(typeof page.appendChild==='function')page.appendChild(nav);else return;nav.querySelectorAll('[data-section-jump]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.sectionJump)?.scrollIntoView({behavior:'smooth',block:'start'}));nav.querySelectorAll('[data-jump-learning]').forEach(b=>b.onclick=()=>{App.workspaceTab='closeout';render();setTimeout(()=>document.querySelector('.lesson-capture-shortcut')?.scrollIntoView({behavior:'smooth',block:'start'}),80)})}
