/* REV 1.0.56 final workflow resolution + exception/navigation refinements */
const _auditFindingAffectedV1056Base=auditFindingAffected;
auditFindingAffected=function(rule){
 const area=String(rule?.area||'').toLowerCase(),title=String(rule?.title||'').toLowerCase();
 if(/measurement resources|^equipment$/.test(area)||/measurement resources/.test(title)){
  const today=P.todayISO();return (App.state.equipment||[]).filter(e=>{
   const gov=P.equipmentGovernanceAssessment?P.equipmentGovernanceAssessment(e):{ready:true};
   return !gov.ready || (e.calibrationRequired!==false&&(!P.validCalibrationCertificate(App.state,e.id,today)||e.calibrationStatus!=='Valid'||(e.calibrationDue&&e.calibrationDue<today)));
  }).map(e=>{const gov=P.equipmentGovernanceAssessment?P.equipmentGovernanceAssessment(e):{ready:true,issues:[]},pending=(App.state.calibrationCertificates||[]).find(c=>c.equipmentId===e.id&&c.approvalStatus==='Pending approval');return `${e.id} · ${e.name} · ${!gov.ready?gov.issues.join(', '):pending?'calibration certificate pending formal approval':`calibration ${e.calibrationStatus||'unknown'} / due ${e.calibrationDue||'not set'}`}`});
 }
 if(/standardized work|methods/.test(area)||/standardized work|methods/.test(title)){
  const active=(App.state.requests||[]).filter(r=>r.status!=='CLOSED'),ids=new Set((App.state.routes||[]).filter(rt=>active.some(r=>r.id===rt.requestId)).flatMap(rt=>(rt.steps||[]).map(s=>s.processId).filter(Boolean)));
  return (App.state.processes||[]).filter(p=>ids.has(p.id)&&(p.status!=='Released'||!(P.processGovernanceAssessment?p=>P.processGovernanceAssessment(p).ready:p=>p.workInstruction?.steps?.length)(p))).map(p=>{const gov=P.processGovernanceAssessment?P.processGovernanceAssessment(p):{issues:[]};return `${p.id} · ${p.name}${gov.ready?'':` · ${gov.issues.join(', ')}`}`});
 }
 return _auditFindingAffectedV1056Base(rule);
};

const _auditCareResolutionV1056Base=auditCareResolution;
auditCareResolution=function(type,items){
 if(type==='Calibration'){
  const ids=(items||[]).map(x=>String(x).split(' · ')[0]).filter(Boolean);
  for(const id of ids){const eq=(App.state.equipment||[]).find(e=>e.id===id);if(!eq)continue;const gov=P.equipmentGovernanceAssessment?P.equipmentGovernanceAssessment(eq):{ready:true,issues:[]};if(!gov.ready){toast(`Open the controlled setup dossier: ${gov.issues.join(', ')}.`,true);return governanceDocsModal('equipment',eq.id)}const pending=(App.state.calibrationCertificates||[]).filter(c=>c.equipmentId===eq.id&&c.approvalStatus==='Pending approval').sort((a,b)=>String(b.completedAt||'').localeCompare(String(a.completedAt||'')))[0];if(pending){toast('This blocker clears only after formal certificate review.');return viewCalibrationCertificates(eq.id)}}
 }
 return _auditCareResolutionV1056Base(type,items);
};

function readinessGuidedResolutionV1056(requestId,name){
 const r=requestById(requestId),n=String(name||'').toLowerCase(),route=(App.state.routes||[]).find(x=>x.requestId===requestId);if(!r)return false;
 if(n.includes('process')||n.includes('route')||n.includes('risk')){
  const a=P.processRevisionReleaseAssessment(App.state,requestId,route);if(a.unresolved?.length){const rows=a.unresolved.map((x,i)=>{const proc=x.step?.processId?(App.state.processes||[]).find(p=>p.id===x.step.processId):null;const action=proc?btn('Open exact process dossier',`data-v1056-open-process-dossier="${esc(proc.id)}"`,'button blocker-action'):btn('Open method development',`data-v1056-open-process-dev="${requestId}"`,'button blocker-action');return `<div class="blocker-action-card"><div class="blocker-number">${i+1}</div><div class="blocker-action-main"><strong>${esc(x.step?.order||'')} · ${esc(x.step?.name||x.step?.processId||'Process')}</strong><small>Routed revision ${esc(x.step?.processRevision||'—')}</small><div class="blocker-reason"><span>✕ ${esc(x.detail||'Controlled release evidence is incomplete.')}</span></div><div class="blocker-fix"><b>Fix now</b>${action}</div></div></div>`}).join('');openModal(`Resolve · ${name}`,`<div class="guided-blocker-simple"><span class="eyebrow">GUIDED RESOLUTION</span><h2>Resolve the exact process revision used by this build</h2><p class="subtle">A warning clears only when the routed revision and its controlled evidence are actually released.</p>${rows}</div>`,`${currentRole()==='administrator'?btn('Administrator exception…',`data-v1056-exact-admin="${requestId}"`,'button admin-exception'):''}${btn('Recheck blocker',`data-v1056-exact-recheck="${esc(name)}"`,'button blocker-action')}${btn('Close','data-modal-close','button')}`);setTimeout(()=>{$$('[data-v1056-open-process-dossier]').forEach(b=>b.onclick=()=>{closeModal();governanceDocsModal('process',b.dataset.v1056OpenProcessDossier)});$$('[data-v1056-open-process-dev]').forEach(b=>b.onclick=()=>{closeModal();openRequest(b.dataset.v1056OpenProcessDev,'processrisk')});const ad=$('[data-v1056-exact-admin]');if(ad)ad.onclick=()=>{closeModal();adminExceptionModal('Build',requestId,'Lifecycle gate')};const rc=$('[data-v1056-exact-recheck]');if(rc)rc.onclick=()=>{closeModal();readinessBlockerModal(requestId,name)}},0);return true}
 }
 if(n.includes('equipment')||n.includes('calibrat')||n.includes('measurement resource')){
  const bookings=(App.state.bookings||[]).filter(b=>b.requestId===requestId&&b.equipmentId),ids=[...new Set(bookings.map(b=>b.equipmentId))];for(const id of ids){const eq=(App.state.equipment||[]).find(e=>e.id===id);if(!eq)continue;const gov=P.equipmentGovernanceAssessment?P.equipmentGovernanceAssessment(eq):{ready:true,issues:[]};if(!gov.ready){openModal(`Resolve · ${name}`,`<div class="callout bad"><h3>${esc(eq.name)} · controlled setup dossier incomplete</h3><p>${esc(gov.issues.join(' · '))}</p></div><ol class="guided-mini-steps"><li><strong>1 · Open dossier</strong><span>Complete EHS / commissioning / in-house calibration procedure evidence as applicable.</span></li><li><strong>2 · Approve</strong><span>Authorised review must approve the controlled documents.</span></li><li><strong>3 · Recheck</strong><span>Readiness recalculates from the evidence.</span></li></ol>`,`${currentRole()==='administrator'?btn('Administrator exception…',`data-v1056-exact-admin="${requestId}"`,'button admin-exception'):''}${btn('Open equipment dossier',`data-v1056-open-equipment-dossier="${eq.id}"`,'button blocker-action')}${btn('Recheck blocker',`data-v1056-exact-recheck="${esc(name)}"`,'button blocker-action')}`);setTimeout(()=>{const d=$('[data-v1056-open-equipment-dossier]');if(d)d.onclick=()=>{closeModal();governanceDocsModal('equipment',d.dataset.v1056OpenEquipmentDossier)};const ad=$('[data-v1056-exact-admin]');if(ad)ad.onclick=()=>{closeModal();adminExceptionModal('Build',requestId,'Lifecycle gate')};const rc=$('[data-v1056-exact-recheck]');if(rc)rc.onclick=()=>{closeModal();readinessBlockerModal(requestId,name)}},0);return true}const pending=(App.state.calibrationCertificates||[]).filter(c=>c.equipmentId===eq.id&&c.approvalStatus==='Pending approval').sort((a,b)=>String(b.completedAt||'').localeCompare(String(a.completedAt||'')))[0];if(pending){openModal(`Resolve · ${name}`,`<div class="callout bad"><h3>${esc(eq.name)} · certificate awaiting formal approval</h3><p>${esc(pending.id)} · ${esc(pending.certificateNumber||'certificate')} · source ${esc(pending.source||'not stated')}</p></div><ol class="guided-mini-steps"><li><strong>1 · Review certificate</strong><span>Check result, traceability, dates and evidence.</span></li><li><strong>2 · Approve / reject</strong><span>Approval must be recorded by an authorised reviewer.</span></li><li><strong>3 · Recheck</strong><span>Only an approved Pass certificate can restore calibration readiness.</span></li></ol>`,`${currentRole()==='administrator'?btn('Administrator exception…',`data-v1056-exact-admin="${requestId}"`,'button admin-exception'):''}${btn('Review pending certificate',`data-v1056-review-cal="${eq.id}"`,'button blocker-action')}${btn('Recheck blocker',`data-v1056-exact-recheck="${esc(name)}"`,'button blocker-action')}`);setTimeout(()=>{const c=$('[data-v1056-review-cal]');if(c)c.onclick=()=>{closeModal();viewCalibrationCertificates(c.dataset.v1056ReviewCal)};const ad=$('[data-v1056-exact-admin]');if(ad)ad.onclick=()=>{closeModal();adminExceptionModal('Build',requestId,'Lifecycle gate')};const rc=$('[data-v1056-exact-recheck]');if(rc)rc.onclick=()=>{closeModal();readinessBlockerModal(requestId,name)}},0);return true}}
 }
 return false;
}
