/* ==========================================================================\n   REV 1.0.57 — contextual MSA, daily automation, sticky local navigation\n   ========================================================================== */
function msaStudyDateV1057(s){return s?.studyDate||String(s?.createdAt||'').slice(0,10)||''}
function msaLinkedStudiesV1057(kind,id,{approvedOnly=false}={}){
  return (App.state.gageRRStudies||[]).filter(s=>{
    if(approvedOnly&&s.status!=='Approved')return false;
    if(kind==='process')return s.processId===id;
    if(kind==='test')return s.standardTestId===id;
    if(kind==='equipment')return s.equipmentId===id;
    return false;
  }).sort((a,b)=>String(msaStudyDateV1057(b)).localeCompare(String(msaStudyDateV1057(a))));
}
function msaConclusionClassV1057(s){const c=String(s?.conclusion||'').toLowerCase();return /not acceptable|reject|fail/.test(c)?'bad':/conditional|review/.test(c)?'warn':'good'}
function msaScopeLabelV1057(s){const p=(App.state.processes||[]).find(x=>x.id===s.processId),t=(App.state.standardTests||[]).find(x=>x.id===s.standardTestId),e=(App.state.equipment||[]).find(x=>x.id===s.equipmentId),prod=(App.state.products||[]).find(x=>x.id===s.productId);return [prod?.family||s.productId,s.configuration,s.characteristic,p?`${p.name} (${p.id})`:null,t?`${t.name} (${t.id})`:null,e?`${e.name} (${e.id})`:null].filter(Boolean).join(' · ')}
function msaContextActionsV1057(kind,id){const studies=msaLinkedStudiesV1057(kind,id),approved=studies.filter(x=>grrDecisionReadyV1059(x)),latest=studies[0];return `<div class="msa-context-strip ${approved.length?'has-msa':'no-msa'}"><div><strong>${approved.length?`✓ ${approved.length} approved MSA / Gage R&R ${approved.length===1?'study':'studies'}`:'No approved MSA / Gage R&R linked'}</strong><small>${latest?`Latest ${P.formatDate(msaStudyDateV1057(latest))} · ${esc(latest.characteristic||latest.title||'measurement system')}`:'Link the measurement system to this controlled process/test/equipment before relying on it.'}</small></div><div class="route-toolbar">${btn('Run guided Gage R&R',`data-v1057-run-grr="${kind}|${id}"`,'button tiny next-action')}${btn('Upload existing MSA',`data-v1057-upload-msa="${kind}|${id}"`,'button tiny secondary')}</div></div>`}

const _renderQuality1056=renderQuality;
renderQuality=function(){
  const open=(App.state.deviations||[]).filter(d=>d.status!=='CLOSED').map(P.ensureQualityCase),holds=open.filter(d=>d.releaseHold),pendingCp=(App.state.controlPlans||[]).filter(c=>!['Approved','Superseded'].includes(c.status));
  if(App.filters.qualityTab==='capability')App.filters.qualityTab='msa';
  const tab=['actions','controlplans','msa','trends','history'].includes(App.filters.qualityTab)?App.filters.qualityTab:'actions';
  const tabs=[['actions','Action board',open.length],['controlplans','Control Plans',pendingCp.length],['msa','MSA / Gage R&R',(App.state.gageRRStudies||[]).filter(x=>['Draft','Review requested'].includes(x.status)).length],['trends','Trends & improvement',''],['history','Case history',(App.state.deviations||[]).filter(d=>d.status==='CLOSED').length]];
  const body=tab==='controlplans'?renderQualityControlPlans():tab==='msa'?renderQualityMsa():tab==='trends'?renderQualityTrends():tab==='history'?renderQualityHistory():renderQualityActionBoard();
  return pageHeader('Quality','Control Plans, measurement-system assurance, nonconformance and verified quality learning on one shared layer.',can('quality:disposition')?btn('+ New quality case','data-quality-new','button primary'):'')+`<div class="quality-command-strip"><div class="quality-command red"><span>✕</span><div><strong>${holds.length}</strong><small>Release holds</small></div></div><div class="quality-command yellow"><span>●</span><div><strong>${open.length}</strong><small>Open quality cases</small></div></div><div class="quality-command yellow"><span>●</span><div><strong>${pendingCp.length}</strong><small>Control Plans awaiting decision</small></div></div></div><div class="quality-tabs">${tabs.map(([id,label,count])=>`<button class="${tab===id?'active':''}" data-quality-tab="${id}">${esc(label)}${count!==''?` <b>${count}</b>`:''}</button>`).join('')}</div>${body}`;
};

nav=function(view){closeModal();document.body.classList.remove('modal-open');if(view==='characterisation'){App.filters.qualityTab='msa';view='quality'}App.currentView=view;App.workspaceId=null;App.workspaceTab='overview';renderNav();render();if(innerWidth<1121)$('#sidebar')?.classList.remove('open');window.scrollTo(0,0)};

renderQualityMsa=function(){
  P.ensureEnterpriseModel(App.state);
  const rows=(App.state.gageRRStudies||[]).slice().sort((a,b)=>String(msaStudyDateV1057(b)||b.updatedAt||'').localeCompare(String(msaStudyDateV1057(a)||a.updatedAt||'')));
  const approved=rows.filter(x=>x.status==='Approved'),pending=rows.filter(x=>x.status!=='Approved');
  const missingGuidance=!approved.length?`<div class="card msa-empty-guide"><span class="eyebrow">NO APPROVED MEASUREMENT STUDY YET</span><h2>Establish measurement-system evidence</h2><p>Use an existing controlled MSA/Gage R&R study, or run a guided crossed Gage R&R in LabOS. The saved study date, data, scope, linked process/test and gage remain available for future builds.</p><div class="resolution-steps compact"><div class="resolution-step current"><span class="resolution-index">1</span><div><strong>Define the measurement use</strong><small>Process or standard test + characteristic + equipment/gage.</small></div></div><div class="resolution-step pending"><span class="resolution-index">2</span><div><strong>Upload or collect study evidence</strong><small>Existing document, or balanced part/operator/trial observations.</small></div></div><div class="resolution-step pending"><span class="resolution-index">3</span><div><strong>Review & approve</strong><small>Formal MSA approval retains the technical conclusion and date.</small></div></div></div><div class="route-toolbar">${btn('Run guided Gage R&R','data-new-gage-rr','button next-action')}${btn('Upload existing MSA / Gage R&R','data-v1057-upload-msa','button secondary')}</div></div>`:'';
  const cards=rows.map(s=>{const r=s.result||{},proc=(App.state.processes||[]).find(x=>x.id===s.processId),test=(App.state.standardTests||[]).find(x=>x.id===s.standardTestId),eq=(App.state.equipment||[]).find(x=>x.id===s.equipmentId),source=s.sourceType||'LabOS calculated';return `<div class="card msa-study-card"><div class="section-title-row"><div><span class="eyebrow">${esc(s.id)} · ${esc(source)}</span><h3>${esc(s.title||s.characteristic||'MSA / Gage R&R')}</h3><div class="subtle">Study date ${P.formatDate(msaStudyDateV1057(s))} · ${esc(s.characteristic||'—')} · ${esc(s.method||'—')}</div></div>${gageRRStudyStatus(s)}</div><div class="msa-link-grid">${proc?`<button class="msa-object-link" data-process="${esc(proc.id)}"><span>Process</span><strong>${esc(proc.name)}</strong><small>${esc(proc.id)} · Rev ${esc(proc.revision)}</small></button>`:''}${test?`<button class="msa-object-link" data-v1057-standard-test="${esc(test.id)}"><span>Standard test</span><strong>${esc(test.name)}</strong><small>${esc(test.id)} · Rev ${esc(test.revision)}</small></button>`:''}${eq?`<button class="msa-object-link" data-v1057-equipment="${esc(eq.id)}"><span>Gage / equipment</span><strong>${esc(eq.name)}</strong><small>${esc(eq.id)}</small></button>`:''}</div><div class="msa-study-summary"><span class="status ${msaConclusionClassV1057(s)}">${esc(s.conclusion||'Review required')}</span><span class="subtle">${esc(msaScopeLabelV1057(s)||'Scope not fully defined')}</span></div>${r.valid&&!r.uploaded?`<div class="quality-cp-kpis"><div><strong>${Number(r.studyPct||0).toFixed(1)}%</strong><span>GR&R · study variation</span></div><div><strong>${r.tolerancePct==null?'—':Number(r.tolerancePct).toFixed(1)+'%'}</strong><span>GR&R · tolerance</span></div><div><strong>${r.ndc??'—'}</strong><span>ndc</span></div></div>`:''}${r.uploaded?`<div class="quality-cp-kpis"><div><strong>${r.studyPct==null?'—':Number(r.studyPct).toFixed(1)+'%'}</strong><span>GR&R · study variation</span></div><div><strong>${r.tolerancePct==null?'—':Number(r.tolerancePct).toFixed(1)+'%'}</strong><span>GR&R · tolerance</span></div><div><strong>${r.ndc??'—'}</strong><span>ndc</span></div></div><div class="score-row"><span>Uploaded evidence</span><strong>${evidenceDocumentLink(s,'Open MSA document')}</strong></div>`:''}<div class="route-toolbar" style="margin-top:10px">${s.status==='Draft'?btn('Submit for review',`data-gage-review="${s.id}"`,'button small next-action'):''}${s.status==='Review requested'?btn('Review / approve MSA',`data-gage-approve="${s.id}"`,'button small next-action'):''}${btn('Run follow-up Gage R&R',`data-v1057-run-grr="study|${s.id}"`,'button small secondary')}</div></div>`}).join('');
  return `<div class="quality-subhead"><div><span class="eyebrow">MEASUREMENT SYSTEM ANALYSIS</span><h2>MSA / Gage R&R evidence</h2><p>Studies are explicitly linked to the process and/or Standard Test that uses the measurement, plus the equipment/gage, characteristic, product/configuration and study date.</p></div><div class="route-toolbar">${btn('+ Run Gage R&R','data-new-gage-rr','button next-action')}${btn('Upload MSA / Gage R&R','data-v1057-upload-msa','button secondary')}</div></div><div class="grid cols-3"><div class="mini-kpi"><span>Approved</span><strong>${approved.length}</strong></div><div class="mini-kpi"><span>Awaiting decision</span><strong>${pending.length}</strong></div><div class="mini-kpi"><span>Linked objects</span><strong>${new Set(rows.flatMap(x=>[x.processId&&`p:${x.processId}`,x.standardTestId&&`t:${x.standardTestId}`,x.equipmentId&&`e:${x.equipmentId}`]).filter(Boolean)).size}</strong></div></div><div style="height:12px"></div>${missingGuidance}<div class="section-stack">${cards||'<div class="card"><div class="empty">No MSA / Gage R&R evidence has been recorded yet.</div></div>'}</div>`;
};

function gageRRSeedV1057(seed={}){if(seed.studyId){const s=(App.state.gageRRStudies||[]).find(x=>x.id===seed.studyId);if(s)return {productId:s.productId,configuration:s.configuration,characteristic:s.characteristic,method:s.method,processId:s.processId,standardTestId:s.standardTestId,equipmentId:s.equipmentId,lsl:s.lsl,usl:s.usl}}return seed}
gageRRModal=function(seed={}){
  seed=gageRRSeedV1057(seed);const products=App.state.products||[],equipment=App.state.equipment||[],processes=App.state.processes||[],tests=App.state.standardTests||[];
  openModal('Run guided Gage R&R',`<div class="callout"><h3>Guided crossed, balanced Gage R&R</h3><p>LabOS keeps the raw observations, study date and exact measurement context. Link at least a process or a Standard Test so the study is discoverable where it is used.</p></div><div class="resolution-steps compact" style="margin-top:12px"><div class="resolution-step current"><span class="resolution-index">1</span><div><strong>Scope</strong><small>What is measured, with which method and gage?</small></div></div><div class="resolution-step current"><span class="resolution-index">2</span><div><strong>Collect</strong><small>Balanced parts × operators × repeated trials.</small></div></div><div class="resolution-step pending"><span class="resolution-index">3</span><div><strong>Save & review</strong><small>Calculation and raw data become controlled future evidence.</small></div></div></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Study date</label><input id="grrStudyDate" type="date" value="${esc(seed.studyDate||P.todayISO())}"></div><div class="field"><label>Product</label><select id="grrProduct"><option value="">Generic / not product-specific</option>${products.map(p=>`<option value="${p.id}" ${seed.productId===p.id?'selected':''}>${esc(p.family)} · ${esc(p.partNumber)}</option>`).join('')}</select></div><div class="field"><label>Configuration / revision</label><input id="grrConfig" value="${esc(seed.configuration||'')}" placeholder="Applicable configuration"></div><div class="field"><label>Characteristic</label><input id="grrChar" value="${esc(seed.characteristic||'')}" placeholder="e.g. Calibration offset"></div><div class="field"><label>Measurement method</label><input id="grrMethod" value="${esc(seed.method||'')}" placeholder="Controlled method / gage method"></div><div class="field"><label>Process link</label><select id="grrProcess"><option value="">Not process-specific</option>${processes.map(p=>`<option value="${p.id}" ${seed.processId===p.id?'selected':''}>${esc(p.name)} · ${esc(p.id)}</option>`).join('')}</select></div><div class="field"><label>Standard Test link</label><select id="grrTest"><option value="">Not test-specific</option>${tests.map(t=>`<option value="${t.id}" ${seed.standardTestId===t.id?'selected':''}>${esc(t.name)} · ${esc(t.id)}</option>`).join('')}</select></div><div class="field"><label>Gage / equipment</label><select id="grrEquipment"><option value="">Select gage</option>${equipment.map(e=>`<option value="${e.id}" ${seed.equipmentId===e.id?'selected':''}>${esc(e.name)} · ${esc(e.id)}</option>`).join('')}</select></div><div class="field"><label>LSL (optional)</label><input id="grrLsl" type="number" step="any" value="${seed.lsl??''}"></div><div class="field"><label>USL (optional)</label><input id="grrUsl" type="number" step="any" value="${seed.usl??''}"></div><div class="field full"><label>Observations · part,operator,trial,value</label><textarea id="grrRows" rows="12" placeholder="P01,Operator A,1,0.012\nP01,Operator A,2,0.011\nP01,Operator B,1,0.013\n..."></textarea><small>Minimum valid design: at least 2 parts, 2 operators and 2 repeated trials, with every combination present.</small></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save Gage R&R study','data-v1057-save-grr','button next-action')}`,true);
  setTimeout(()=>{$('[data-v1057-save-grr]').onclick=async()=>{const lines=$('#grrRows').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),rows=lines.map(line=>{const q=line.split(/[,;\t]/).map(x=>x.trim());return {part:q[0],operator:q[1],trial:q[2],value:q[3]}}),lsl=$('#grrLsl').value===''?null:Number($('#grrLsl').value),usl=$('#grrUsl').value===''?null:Number($('#grrUsl').value),result=gageRRCalculate(rows,lsl,usl);if(!result.valid){toast(result.reason,true);return}const processId=$('#grrProcess').value,standardTestId=$('#grrTest').value,equipmentId=$('#grrEquipment').value,characteristic=$('#grrChar').value.trim(),method=$('#grrMethod').value.trim(),studyDate=$('#grrStudyDate').value;if(!studyDate||!characteristic||!method||!equipmentId||(!processId&&!standardTestId)){toast('Study date, characteristic, method, gage/equipment and at least one process or Standard Test link are required.',true);return}const conclusion=result.studyPct<=10?'Acceptable':result.studyPct<=30?'Conditionally acceptable':'Not acceptable',rec={id:P.uid('GRR'),title:`${characteristic} · Gage R&R`,productId:$('#grrProduct').value,configuration:$('#grrConfig').value.trim(),characteristic,method,processId,standardTestId,equipmentId,lsl,usl,rows,result,status:'Draft',sourceType:'LabOS calculated',conclusion,studyDate,createdBy:App.state.identity.name,createdAt:P.now(),updatedAt:P.now(),fileData:null,documentUploaded:false};App.state.gageRRStudies.push(rec);P.audit(App.state,'Gage R&R study created','MSA',rec.id,'—','Draft',`${rec.characteristic} · ${result.parts} parts × ${result.operators} operators × ${result.trials} trials · linked ${processId||'—'} / ${standardTestId||'—'} / ${equipmentId}`);await persist();closeModal();App.currentView='quality';App.filters.qualityTab='msa';render();toast('Gage R&R saved with raw data and study date. Submit it for formal review.')};},0)
};

function uploadMsaModalV1057(seed={}){
  const products=App.state.products||[],equipment=App.state.equipment||[],processes=App.state.processes||[],tests=App.state.standardTests||[];
  openModal('Upload existing MSA / Gage R&R',`<div class="callout"><h3>Retain existing measurement-system evidence</h3><p>Uploading a report does not silently approve it. Link it to the exact process/test and gage, retain the original study date and summary, then send it through formal review.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Study date</label><input id="msaUploadDate" type="date" value="${P.todayISO()}"></div><div class="field"><label>Study type</label><select id="msaUploadType"><option>Gage R&R</option><option>Attribute agreement analysis</option><option>Bias / linearity / stability</option><option>Other MSA</option></select></div><div class="field"><label>Product</label><select id="msaUploadProduct"><option value="">Generic / not product-specific</option>${products.map(p=>`<option value="${p.id}" ${seed.productId===p.id?'selected':''}>${esc(p.family)} · ${esc(p.partNumber)}</option>`).join('')}</select></div><div class="field"><label>Configuration / revision</label><input id="msaUploadConfig" value="${esc(seed.configuration||'')}"></div><div class="field"><label>Characteristic</label><input id="msaUploadChar" value="${esc(seed.characteristic||'')}"></div><div class="field"><label>Measurement method</label><input id="msaUploadMethod" value="${esc(seed.method||'')}"></div><div class="field"><label>Process link</label><select id="msaUploadProcess"><option value="">Not process-specific</option>${processes.map(p=>`<option value="${p.id}" ${seed.processId===p.id?'selected':''}>${esc(p.name)} · ${esc(p.id)}</option>`).join('')}</select></div><div class="field"><label>Standard Test link</label><select id="msaUploadTest"><option value="">Not test-specific</option>${tests.map(t=>`<option value="${t.id}" ${seed.standardTestId===t.id?'selected':''}>${esc(t.name)} · ${esc(t.id)}</option>`).join('')}</select></div><div class="field"><label>Gage / equipment</label><select id="msaUploadEquipment"><option value="">Select equipment</option>${equipment.map(e=>`<option value="${e.id}" ${seed.equipmentId===e.id?'selected':''}>${esc(e.name)} · ${esc(e.id)}</option>`).join('')}</select></div><div class="field"><label>Technical conclusion</label><select id="msaUploadConclusion"><option>Acceptable</option><option>Conditionally acceptable</option><option>Not acceptable</option><option>Review required</option></select></div><div class="field"><label>GR&R % study variation <small>optional</small></label><input id="msaUploadStudyPct" type="number" min="0" step="0.1"></div><div class="field"><label>GR&R % tolerance <small>optional</small></label><input id="msaUploadTolerancePct" type="number" min="0" step="0.1"></div><div class="field"><label>ndc <small>optional</small></label><input id="msaUploadNdc" type="number" min="0" step="1"></div><div class="field full"><label>MSA / Gage R&R document <b>required</b></label><input id="msaUploadFile" type="file" accept=".pdf,.xlsx,.xls,.csv,.doc,.docx,.jpg,.jpeg,.png,.txt"></div><div class="field full"><label>Controlled reference / note</label><input id="msaUploadRef" placeholder="QMS / SharePoint / report reference"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Upload for formal review','data-v1057-save-msa-upload','button next-action')}`,true);
  setTimeout(()=>{$('[data-v1057-save-msa-upload]').onclick=async()=>{try{const file=$('#msaUploadFile').files?.[0],studyDate=$('#msaUploadDate').value,characteristic=$('#msaUploadChar').value.trim(),method=$('#msaUploadMethod').value.trim(),processId=$('#msaUploadProcess').value,standardTestId=$('#msaUploadTest').value,equipmentId=$('#msaUploadEquipment').value;if(!file||!studyDate||!characteristic||!method||!equipmentId||(!processId&&!standardTestId)){toast('Document, study date, characteristic, method, equipment and at least one process or Standard Test link are required.',true);return}const data=await readFileDataUrl(file),num=id=>{const v=$(id).value;return v===''?null:Number(v)},studyType=$('#msaUploadType').value,rec={id:P.uid('MSA'),title:`${characteristic} · ${studyType}`,productId:$('#msaUploadProduct').value,configuration:$('#msaUploadConfig').value.trim(),characteristic,method,processId,standardTestId,equipmentId,studyDate,sourceType:'Uploaded existing study',studyType,conclusion:$('#msaUploadConclusion').value,status:'Review requested',reviewRequestedBy:App.state.identity.name,reviewRequestedAt:P.now(),createdBy:App.state.identity.name,createdAt:P.now(),updatedAt:P.now(),fileName:file.name,fileType:file.type,fileSize:file.size,fileData:data,documentUploaded:true,evidence:$('#msaUploadRef').value.trim()||file.name,result:{valid:true,uploaded:true,studyPct:num('#msaUploadStudyPct'),tolerancePct:num('#msaUploadTolerancePct'),ndc:num('#msaUploadNdc')}};App.state.gageRRStudies.push(rec);P.audit(App.state,'Existing MSA uploaded for review','MSA',rec.id,'—','Review requested',`${studyType} · study ${studyDate} · linked ${processId||'—'} / ${standardTestId||'—'} / ${equipmentId} · ${file.name}`);await persist();closeModal();App.currentView='quality';App.filters.qualityTab='msa';render();toast('MSA evidence uploaded and sent for formal review.') }catch(e){toast(`MSA upload failed: ${e.message}`,true)}}},0)
}

const _approveGageRR1056=approveGageRR;
approveGageRR=function(id){const s=(App.state.gageRRStudies||[]).find(x=>x.id===id);if(!s)return;if(s.status!=='Review requested'){toast('Submit the study for review first.',true);return}const self=App.state.settings?.separationOfDuties&&s.createdBy===App.state.identity.name&&currentRole()!=='administrator';if(self){toast('Separation of duties prevents the study author from approving the same MSA study.',true);return}if(!['administrator','quality','metrology','approver','lab_manager'].includes(currentRole())){toast('Switch to Quality, Metrology, Lab Manager or Approver / Reviewer.',true);return}openModal(`Review MSA · ${s.id}`,`<div class="callout"><h3>Formal measurement-system review</h3><p>Confirm the study scope, date, linked process/test/equipment, study design or uploaded evidence, and the technical conclusion. Approval means the evidence has been reviewed; it does not change a technically unacceptable conclusion.</p></div><div class="score-row"><span>Study date</span><strong>${P.formatDate(msaStudyDateV1057(s))}</strong></div><div class="score-row"><span>Linked use</span><strong>${esc(msaScopeLabelV1057(s))}</strong></div><div class="field"><label>Technical conclusion</label><select id="grrReviewConclusion">${['Acceptable','Conditionally acceptable','Not acceptable','Review required'].map(x=>`<option ${s.conclusion===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Review conclusion / evidence <b>required</b></label><textarea id="grrApproveNote"></textarea></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Approve MSA record','data-v1057-confirm-grr-approve','button next-action')}`);setTimeout(()=>{$('[data-v1057-confirm-grr-approve]').onclick=async()=>{const note=$('#grrApproveNote').value.trim();if(!note){toast('Record the review conclusion.',true);return}s.status='Approved';s.conclusion=$('#grrReviewConclusion').value;s.approvedBy=App.state.identity.name;s.approvedAt=P.now();s.approvalRationale=note;s.updatedAt=P.now();P.audit(App.state,'MSA approved','MSA',id,'Review requested','Approved',`${s.conclusion} · ${note}`);await persist();closeModal();render();toast('MSA record formally approved and retained against its linked process/test/equipment.')}},0)};

const _showProcess1056=showProcess;
showProcess=function(id){const p=App.state.processes.find(x=>x.id===id);if(!p)return;const studies=msaLinkedStudiesV1057('process',id);openModal(`${p.id} · ${p.name}`,`<div class="grid cols-2"><div class="card"><h3>Released definition</h3>${[['Revision',p.revision],['Status',p.status],['Owner',p.owner],['Family',p.family],['Setup time',p.setupTime+' min'],['Cycle time',p.cycleTime+' min / '+p.basis],['Equipment',p.equipmentCapability],['Competency',p.competency]].map(([a,b])=>`<div class="score-row"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}</div><div class="card"><h3>Controlled content</h3><p>${esc(p.description)}</p><h3>Work instruction</h3><p><strong>${esc(p.workInstruction?.id||'Missing')}</strong> · ${esc(p.workInstruction?.status||'Missing')}</p><ol>${(p.workInstruction?.steps||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="route-toolbar">${btn('Open EHS / commissioning dossier',`data-governance-docs="process|${p.id}"`,'button small secondary')}</div></div></div><div class="card msa-linked-panel"><div class="section-title-row"><div><span class="eyebrow">MEASUREMENT ASSURANCE</span><h3>Linked MSA / Gage R&R</h3></div><span class="pill">${studies.length} study${studies.length===1?'':'ies'}</span></div>${studies.slice(0,6).map(s=>`<button class="msa-linked-row" data-v1057-open-msa="${s.id}"><strong>${esc(s.characteristic||s.title)}</strong><span>${P.formatDate(msaStudyDateV1057(s))} · ${esc(s.conclusion||s.status)}</span></button>`).join('')||'<div class="callout warn"><strong>No linked MSA / Gage R&R.</strong><p>If this process relies on a measurement decision, link existing evidence or run a study.</p></div>'}<div class="route-toolbar">${btn('Run guided Gage R&R',`data-v1057-run-grr="process|${p.id}"`,'button next-action')}${btn('Upload existing MSA',`data-v1057-upload-msa="process|${p.id}"`,'button secondary')}</div></div>`,btn('Close','data-modal-close','button'),true);setTimeout(()=>bindMsaContextActionsV1057($('#modalRoot')),0)};
function showStandardTestV1057(id){const t=(App.state.standardTests||[]).find(x=>x.id===id);if(!t)return;const studies=msaLinkedStudiesV1057('test',id);openModal(`${t.id} · ${t.name}`,`<div class="grid cols-2"><div class="card"><h3>Standard Test</h3>${[['Revision',t.revision],['Status',t.status],['Family',testFamilyName(t.familyId)],['Output',t.output],['Equipment capability',t.equipmentCapability],['Competency',t.competency]].map(([a,b])=>`<div class="score-row"><span>${esc(a)}</span><strong>${esc(b||'—')}</strong></div>`).join('')}</div><div class="card"><h3>Controlled test setup</h3><div class="score-row"><span>Work instruction</span><strong>${esc(t.workInstruction?.id||'Not defined')} · ${esc(t.workInstruction?.status||'Missing')}</strong></div><div class="route-toolbar">${btn('Open EHS / commissioning dossier',`data-governance-docs="test|${t.id}"`,'button small secondary')}</div></div></div><div class="card msa-linked-panel"><div class="section-title-row"><div><span class="eyebrow">MEASUREMENT ASSURANCE</span><h3>Linked MSA / Gage R&R</h3></div><span class="pill">${studies.length} study${studies.length===1?'':'ies'}</span></div>${studies.slice(0,6).map(s=>`<button class="msa-linked-row" data-v1057-open-msa="${s.id}"><strong>${esc(s.characteristic||s.title)}</strong><span>${P.formatDate(msaStudyDateV1057(s))} · ${esc(s.conclusion||s.status)}</span></button>`).join('')||'<div class="callout warn"><strong>No linked MSA / Gage R&R.</strong><p>Run or upload measurement-system evidence when this test makes a measurement-based acceptance decision.</p></div>'}<div class="route-toolbar">${btn('Run guided Gage R&R',`data-v1057-run-grr="test|${t.id}"`,'button next-action')}${btn('Upload existing MSA',`data-v1057-upload-msa="test|${t.id}"`,'button secondary')}</div></div>`,btn('Close','data-modal-close','button'),true);setTimeout(()=>bindMsaContextActionsV1057($('#modalRoot')),0)}
function showEquipmentGovernanceV1057(id){const e=(App.state.equipment||[]).find(x=>x.id===id);if(!e)return;const studies=msaLinkedStudiesV1057('equipment',id),cert=P.validCalibrationCertificate(App.state,id,P.todayISO());openModal(`${e.id} · ${e.name}`,`<div class="grid cols-2"><div class="card"><h3>Equipment</h3>${[['Capability',e.capability],['Status',e.status],['Calibration route',e.calibrationMode||'External'],['Calibration status',e.calibrationStatus],['Calibration due',P.formatDate(e.calibrationDue)]].map(([a,b])=>`<div class="score-row"><span>${esc(a)}</span><strong>${esc(b||'—')}</strong></div>`).join('')}</div><div class="card"><h3>Controlled readiness</h3><div class="score-row"><span>Current approved certificate</span><strong>${esc(cert?.certificateNo||'None valid')}</strong></div><div class="route-toolbar">${btn('Open equipment dossier',`data-governance-docs="equipment|${e.id}"`,'button small secondary')}${btn('Calibration certificates',`data-v1057-cal-certs="${e.id}"`,'button small secondary')}</div></div></div><div class="card msa-linked-panel"><div class="section-title-row"><div><span class="eyebrow">MEASUREMENT ASSURANCE</span><h3>Linked MSA / Gage R&R</h3></div><span class="pill">${studies.length} study${studies.length===1?'':'ies'}</span></div>${studies.slice(0,8).map(s=>`<button class="msa-linked-row" data-v1057-open-msa="${s.id}"><strong>${esc(s.characteristic||s.title)}</strong><span>${P.formatDate(msaStudyDateV1057(s))} · ${esc(s.conclusion||s.status)}</span></button>`).join('')||'<div class="callout warn"><strong>No linked MSA / Gage R&R.</strong></div>'}<div class="route-toolbar">${btn('Run guided Gage R&R',`data-v1057-run-grr="equipment|${e.id}"`,'button next-action')}${btn('Upload existing MSA',`data-v1057-upload-msa="equipment|${e.id}"`,'button secondary')}</div></div>`,btn('Close','data-modal-close','button'),true);setTimeout(()=>bindMsaContextActionsV1057($('#modalRoot')),0)}
function openMsaRecordV1057(id){closeModal();App.currentView='quality';App.filters.qualityTab='msa';render();setTimeout(()=>{const card=Array.from(document.querySelectorAll('.msa-study-card')).find(x=>(x.textContent||'').includes(id));card?.scrollIntoView({behavior:'smooth',block:'center'});card?.classList.add('attention-flash')},80)}
function seedFromMsaContextV1057(raw){const [kind,id]=String(raw||'').split('|');if(kind==='process')return {processId:id};if(kind==='test')return {standardTestId:id};if(kind==='equipment')return {equipmentId:id};if(kind==='study')return {studyId:id};return {}}
function bindMsaContextActionsV1057(root=document){root.querySelectorAll?.('[data-governance-docs]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();const [k,id]=b.dataset.governanceDocs.split('|');closeModal();governanceDocsModal(k,id)});root.querySelectorAll?.('[data-v1057-run-grr]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();const seed=seedFromMsaContextV1057(b.dataset.v1057RunGrr);closeModal();gageRRModal(seed)});root.querySelectorAll?.('[data-v1057-upload-msa]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();const seed=seedFromMsaContextV1057(b.dataset.v1057UploadMsa);closeModal();uploadMsaModalV1057(seed)});root.querySelectorAll?.('[data-v1057-standard-test]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();showStandardTestV1057(b.dataset.v1057StandardTest)});root.querySelectorAll?.('[data-v1057-equipment]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();showEquipmentGovernanceV1057(b.dataset.v1057Equipment)});root.querySelectorAll?.('[data-v1057-open-msa]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();openMsaRecordV1057(b.dataset.v1057OpenMsa)});root.querySelectorAll?.('[data-v1057-cal-certs]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();closeModal();viewCalibrationCertificates(b.dataset.v1057CalCerts)})}

governanceRegister=function(kind){const items=kind==='equipment'?(App.state.equipment||[]):[...(App.state.processes||[]).map(x=>({...x,_kind:'process'})),...(App.state.standardTests||[]).map(x=>({...x,_kind:'test'}))];if(!items.length)return '';const cards=items.map(x=>{const k=kind==='equipment'?'equipment':x._kind,source=governanceObject(k,x.id)||x,assess=k==='equipment'?P.equipmentGovernanceAssessment(source):P.processGovernanceAssessment(source),studies=msaLinkedStudiesV1057(k,source.id),approved=studies.filter(s=>s.status==='Approved').length,identityAttr=k==='process'?`data-process="${esc(source.id)}"`:k==='test'?`data-v1057-standard-test="${esc(source.id)}"`:`data-v1057-equipment="${esc(source.id)}"`;return `<div class="governance-item-card"><button class="governance-identity-link" ${identityAttr}><span>${k==='equipment'?'Equipment':k==='test'?'Standard Test':'Process'}</span><strong>${esc(source.name)}</strong><small>${esc(source.id)}${k==='equipment'?` · ${esc(source.calibrationMode||'External')} calibration`:` · WI ${esc(source.workInstruction?.status||'Missing')}`}</small></button><div class="governance-status-grid"><div><span>EHS</span>${controlledDocStatus(source.ehsRiskAssessment)}</div><div><span>Commissioning</span>${controlledDocStatus(source.commissioningDocument)}</div>${k==='equipment'&&source.calibrationMode==='In-house'?`<div><span>Cal procedure</span>${controlledDocStatus(source.calibrationProcedure)}</div>`:''}<div><span>MSA / GRR</span><strong class="${approved?'good-text':'warn-text'}">${approved?`${approved} approved`:'None linked'}</strong></div><div><span>Readiness</span>${assess.ready?'<span class="status good">✓ Ready</span>':'<span class="status bad">✕ Incomplete</span>'}</div></div><div class="route-toolbar">${btn('Open controlled dossier',`data-governance-docs="${k}|${source.id}"`,'button tiny secondary')}${btn(approved?'Add / update MSA':'Set up MSA / Gage R&R',`data-v1057-run-grr="${k}|${source.id}"`,'button tiny next-action')}</div></div>`}).join('');return `<div class="card governance-register"><div class="section-title-row"><div><span class="eyebrow">CONTROLLED SETUP DOSSIERS</span><h2>${kind==='equipment'?'Equipment EHS, commissioning, calibration & MSA':'Process / test EHS, commissioning, work-instruction & MSA governance'}</h2><div class="subtle">Tap an item to open the exact equipment, process or Standard Test. Measurement assurance is shown alongside the controlled setup evidence so its relationship is explicit.</div></div></div><div class="governance-card-list">${cards}</div></div>`};

function enhanceProcessTestCardsV1057(){if(App.currentView!=='process-library')return;document.querySelectorAll('[data-process].card.clickable').forEach(card=>{if(card.querySelector('.msa-context-strip'))return;const id=card.dataset.process;card.insertAdjacentHTML('beforeend',msaContextActionsV1057('process',id));bindMsaContextActionsV1057(card)});const processLibCards=Array.from(document.querySelectorAll('#page > .card'));const testSection=processLibCards.find(c=>/STANDARD TEST LIBRARY/i.test(c.textContent||''));if(testSection){const testCards=Array.from(testSection.querySelectorAll('.grid > .card'));(App.state.standardTests||[]).forEach((t,i)=>{const card=testCards[i];if(!card||card.querySelector('.msa-context-strip'))return;card.classList.add('clickable');card.dataset.v1057StandardTest=t.id;card.insertAdjacentHTML('beforeend',msaContextActionsV1057('test',t.id));card.onclick=e=>{if(e.target.closest('button'))return;showStandardTestV1057(t.id)};bindMsaContextActionsV1057(card)})}}

installWorkspaceLearningShortcut=function(){if(App.currentView!=='workspace'||!App.workspaceId||currentRole()!=='administrator')return;const slot=document.querySelector('.workspace-edit-slot,.workflow-edit-slot');if(!slot||slot.querySelector('[data-admin-workspace-override]'))return;const b=document.createElement('button');b.type='button';b.className='button small admin-exception workflow-dock-button';b.dataset.adminWorkspaceOverride='1';b.textContent='Override…';b.onclick=()=>adminExceptionModal('Build',App.workspaceId,'Lifecycle gate');slot.appendChild(b)};
installSectionNavigator=function(){const page=$('#page');if(!page||!document.createElement||App.currentView==='workspace')return;page.querySelector('.section-jump-nav')?.remove();let cards=[];for(const el of Array.from(page.querySelectorAll(':scope > .card, :scope > details.card, :scope > .section-stack > .card'))){if(el.closest('.modal'))continue;const h=el.querySelector(':scope > .section-title-row .eyebrow, :scope > .eyebrow, :scope > .section-title-row h2, :scope > h2, :scope > summary strong');if(!h)continue;const text=(h.textContent||'').trim();if(!text||/NEXT ACTION|MANAGEMENT ATTENTION/i.test(text))continue;cards.push({el,text})}const seen=new Set();cards=cards.filter(x=>{const k=x.text.toLowerCase();if(seen.has(k))return false;seen.add(k);return true}).slice(0,14);if(cards.length<3)return;const nav=document.createElement('nav');nav.className='section-jump-nav';nav.setAttribute('aria-label','Jump to section');nav.innerHTML=cards.map((x,i)=>{if(!x.el.id)x.el.id=`section-${App.currentView}-${i+1}`;x.el.classList.add('section-jump-target');return `<button type="button" data-section-jump="${esc(x.el.id)}">${esc(x.text.replace(/^\d+\s*·\s*/,''))}</button>`}).join('');const anchor=page.querySelector('.page-header')||page.firstElementChild;anchor?.after(nav);nav.querySelectorAll('[data-section-jump]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.sectionJump)?.scrollIntoView({behavior:'smooth',block:'start'}))};

function inferReplanContextV1057(r,forecast,current){const ctx={...(r.pendingReplanContext||{})},events=(App.state.planningEvents||[]),linked=events.find(x=>x.id===ctx.eventId);if(linked){ctx.reasonCategory=ctx.reasonCategory||planningSituationReasonCategory(linked);ctx.reason=ctx.reason||`${linked.type}: ${linked.reason}`;return ctx}const candidates=events.filter(x=>x.active!==false&&new Date(x.end||x.start)>=new Date()).sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')));const booking=(App.state.bookings||[]).find(b=>b.requestId===r.id),direct=candidates.find(ev=>(ev.scope==='staff'&&booking?.staffId===ev.staffId)||(ev.scope==='equipment'&&booking?.equipmentId===ev.equipmentId)||ev.scope==='lab'),categoryMatch=candidates.find(ev=>ctx.reasonCategory&&planningSituationReasonCategory(ev)===ctx.reasonCategory),related=direct||categoryMatch;if(related){ctx.eventId=related.id;ctx.reasonCategory=planningSituationReasonCategory(related);ctx.reason=`${related.type}: ${related.reason}. AUTO-PLAN moved ${r.id} from ${P.formatDate(current)} to ${P.formatDate(forecast)}.`;return ctx}const clues=[...(r.changeHistory||[]).filter(x=>x.status==='Open').slice(0,2).map(x=>`${x.type}: ${(x.changes||[]).map(c=>c.label||c.field).join(', ')}`),r.triage?.riskNotes].filter(Boolean);ctx.reasonCategory=ctx.reasonCategory||(clues.some(x=>/material/i.test(x))?'Material delay':clues.some(x=>/process|test|method/i.test(x))?'Process / test development':clues.some(x=>/quantity|scope/i.test(x))?'Scope / quantity change':'Capacity / congestion');ctx.reason=ctx.reason||`${clues[0]||'AUTO-PLAN found a later best-feasible schedule under the current laboratory constraints.'} Proposed commitment moved from ${P.formatDate(current)} to ${P.formatDate(forecast)}.`;return ctx}
commitTriage=async function(id){const r=requestById(id),mat=P.materialPlanningAssessment(App.state,r),proc=P.processPlanningAssessment(App.state,r);if(!can('triage')&&currentRole()!=='administrator'){toast('Lab Planner role is required to commit timing.',true);return}if(!mat.planningReady||!proc.ready){toast('Cannot commit timing until material feasibility and process/test definition are complete.',true);return}if(!r.triage?.forecastDate){toast('Run AUTO-PLAN before committing the timing forecast.',true);return}const forecast=r.triage.forecastDate,current=r.currentCommitmentDate||r.originalCommitmentDate;if(r.originalCommitmentDate&&current&&forecast!==current){const ctx=inferReplanContextV1057(r,forecast,current),events=(App.state.planningEvents||[]).filter(x=>x.active!==false||x.id===ctx.eventId);openModal(`Commit replan · ${r.id}`,`<div class="callout warn"><h3>Committed date movement requires a reason</h3><p>Original commitment <strong>${P.formatDate(r.originalCommitmentDate)}</strong> · current commitment <strong>${P.formatDate(current)}</strong> · proposed commitment <strong>${P.formatDate(forecast)}</strong>. The explanation below is pre-populated from the event/change that triggered the replanning decision; edit it if additional context is needed.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Reason category</label><select id="replanCategory">${['Vacation / staff absence','Equipment outage','Lab closure / capacity loss','Calibration / maintenance','Material delay','Process / test development','Scope / quantity change','Engineering change','Priority change','Quality / rework','Capacity / congestion','Other'].map(x=>`<option ${ctx.reasonCategory===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Linked planning situation</label><select id="replanEvent"><option value="">None / not applicable</option>${events.map(x=>`<option value="${x.id}" ${ctx.eventId===x.id?'selected':''}>${esc(planningSituationLabel(x))}</option>`).join('')}</select></div><div class="field full"><label>Reason / explanation <small>required · pre-populated from source</small></label><textarea id="replanReason">${esc(ctx.reason||'')}</textarea></div></div>`,`${btn('Keep current commitment','data-modal-close','button')}${btn('Accept new commitment','data-v1057-accept-replan','button next-action')}`,true);setTimeout(()=>{const ev=$('#replanEvent'),reason=$('#replanReason'),category=$('#replanCategory');ev.onchange=()=>{const x=(App.state.planningEvents||[]).find(y=>y.id===ev.value);if(x){category.value=planningSituationReasonCategory(x);reason.value=`${x.type}: ${x.reason}. AUTO-PLAN moved ${r.id} from ${P.formatDate(current)} to ${P.formatDate(forecast)}.`}};$('[data-v1057-accept-replan]').onclick=async()=>{const why=reason.value.trim(),cat=category.value,eventId=ev.value||null;if(!why){toast('Every replan requires an explanation.',true);return}try{P.recordCommitment(App.state,r,forecast,{reasonCategory:cat,reason:why,eventId})}catch(e){toast(e.message,true);return}r.triage.status='Committed';r.status=r.currentGate='LAB TRIAGE';r.pendingReplanContext=null;App.state.actions=App.state.actions.filter(a=>!(a.requestId===id&&/triage|timing|feasibility/i.test(a.title)));P.audit(App.state,'Lab timing replanned & committed','Request',id,current,forecast,`${cat} · ${why}`);await persist();closeModal();render();toast(`Replan committed. New commitment ${P.formatDate(forecast)}; original ${P.formatDate(r.originalCommitmentDate)} retained.`)}},0);return}const rec=P.recordCommitment(App.state,r,forecast);r.triage.status='Committed';r.status=r.currentGate='LAB TRIAGE';r.pendingReplanContext=null;App.state.actions=App.state.actions.filter(a=>!(a.requestId===id&&/triage|timing|feasibility/i.test(a.title)));P.audit(App.state,rec.type==='initial'?'Lab timing committed':'Lab timing recommitted','Request',id,'Timing proposal','LAB TRIAGE',`Forecast ${forecast}; original commitment ${r.originalCommitmentDate}; margin ${r.triage.slackDays} days`);await persist();render();toast(rec.type==='initial'?`Initial lab commitment recorded: ${P.formatDate(forecast)}.`:'Timing commitment confirmed with no date movement.')};

async function autoDailyOperationsCheckV1057(){if(!App.state)return;const last=App.state.settings?.lastOperationsReviewDate;if(last===P.todayISO())return;new P.ImprovementService().dailyReview(App.state,{force:false});await persist();if(App.currentView==='dashboard')render()}
function installDailyOpsStatusV1057(){const card=document.querySelector('.daily-ops-card');if(!card)return;const sub=card.querySelector('.section-title-row .subtle');if(sub&&!card.querySelector('.daily-auto-note'))sub.insertAdjacentHTML('afterend','<small class="daily-auto-note">Runs automatically once per calendar day while LabOS is opened/active. You can rerun it on demand at any time.</small>');const b=card.querySelector('[data-run-daily-review]');if(b)b.textContent=(App.state.dailyOperationsReviews||[])[0]?.date===P.todayISO()?'Run again now':'Run now'}
window.addEventListener('focus',()=>{autoDailyOperationsCheckV1057().catch(e=>console.warn('Daily operations auto-check skipped',e))});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')autoDailyOperationsCheckV1057().catch(e=>console.warn('Daily operations auto-check skipped',e))});if(typeof setInterval==='function')setInterval(()=>{autoDailyOperationsCheckV1057().catch(()=>{})},15*60*1000);

const _bindDynamicV1057=bindDynamic;
bindDynamic=function(){_bindDynamicV1057();bindMsaContextActionsV1057(document)};
const _renderV1057=render;
render=function(){_renderV1057();enhanceProcessTestCardsV1057();installDailyOpsStatusV1057();bindMsaContextActionsV1057(document)};

/* ==========================================================================\n   REV 1.0.58 — approval packages + universal next-action ownership\n   ========================================================================== */
function approvalRecordVisibleV1058(a){return !!a&&a.status!=='Superseded'&&a.type!=='Build Readiness'}
function approvalPackageKindV1058(a){if(!a)return'other';if(a.stage==='build-change')return'definition';if(a.stage==='release')return'release';if(a.stage==='report'||a.type==='Build Report Approval')return'report';if(a.stage==='readiness'||a.type==='Product Safety')return'readiness';return a.stage||'other'}
function approvalPackageMetaV1058(kind){return ({definition:{label:'Build-specific change sign-off',eyebrow:'CONSOLIDATED DEFINITION SIGN-OFF',description:'One sign-off per required role covers all currently open build-specific route / Work Instruction / Control Plan deltas in this package.'},readiness:{label:'Readiness / safety sign-off',eyebrow:'READINESS SIGN-OFF',description:'Only explicit independent readiness or product-safety decisions appear here. Ordinary readiness checks are evidence gates, not extra approvals.'},release:{label:'Release sign-off',eyebrow:'CONSOLIDATED RELEASE SIGN-OFF',description:'All configured release roles are shown together. Each required person signs once for their release scope.'},report:{label:'Report approval',eyebrow:'CONTROLLED REPORT APPROVAL',description:'The controlled report is approved once by the configured report reviewer after its evidence is complete.'},other:{label:'Approval package',eyebrow:'APPROVAL PACKAGE',description:'Required decisions are grouped by signer and decision point.'}})[kind]||({label:'Approval package',eyebrow:'APPROVAL PACKAGE',description:'Required decisions are grouped by signer and decision point.'})}
function approvalPackageRecordsV1058(r,kind){P.ensureApprovalRecords(App.state,r);return (App.state.approvals||[]).filter(a=>a.requestId===r.id&&approvalRecordVisibleV1058(a)&&approvalPackageKindV1058(a)===kind)}
function approvalSignerGroupsV1058(records){const map=new Map();for(const a of records){const roleId=a.roleId||roleIdForLabel(a.role)||'',person=a.person||a.role||'Unassigned',key=`${roleId||a.role||'role'}::${person}`;if(!map.has(key))map.set(key,{key,roleId,role:a.role||roleLabel(roleId)||'Approver',person,records:[]});map.get(key).records.push(a)}return [...map.values()].map(g=>{const pending=g.records.filter(a=>a.status==='Pending'),approved=g.records.filter(a=>a.status==='Approved'),scopes=[...new Set(g.records.map(a=>a.changeArea||a.type).filter(Boolean))];return {...g,pending,approved,done:pending.length===0&&approved.length>0,scopes}})}
function approvalPackageSummaryV1058(r,kind){const records=approvalPackageRecordsV1058(r,kind),signers=approvalSignerGroupsV1058(records),done=signers.filter(s=>s.done).length;return {kind,records,signers,done,total:signers.length,pending:signers.filter(s=>!s.done),meta:approvalPackageMetaV1058(kind)}}
function approvalSignerStatusV1058(g){if(g.done){const at=g.records.filter(a=>a.status==='Approved'&&a.timestamp).map(a=>a.timestamp).sort().pop();return `<span class="approval-signer-status good">✓ Signed${at?` · ${P.formatDateTime(at)}`:''}</span>`}return `<span class="approval-signer-status warn">● Awaiting sign-off</span>`}
function approvalPackageCardV1058(r,kind,{embedded=false}={}){const p=approvalPackageSummaryV1058(r,kind),m=p.meta;if(!p.records.length)return `<div class="callout reuse-good"><strong>✓ No ${esc(m.label.toLowerCase())} required</strong><p>No additional signer has been configured for this decision point.</p></div>`;const multi=p.total>1,scopes=[...new Set(p.records.map(a=>a.changeArea||a.type).filter(Boolean))];return `<div class="approval-package ${p.pending.length?'pending':'complete'} ${embedded?'embedded':''}"><div class="approval-package-head"><div><span class="eyebrow">${esc(m.eyebrow)}</span><h3>${esc(m.label)}</h3><p>${esc(m.description)}</p></div><div class="approval-package-progress ${p.pending.length?'warn':'good'}"><strong>${p.done}/${p.total}</strong><span>${p.total===1?'signer':'signers'} complete</span></div></div>${multi?`<div class="approval-multi-note"><strong>${p.total} people / roles must sign off.</strong><span>LabOS will not hide multiple required signers behind a generic “approval pending” state.</span></div>`:`<div class="approval-multi-note single"><strong>1 signer required.</strong><span>${p.records.length>1?`${p.records.length} related approval items are consolidated into that one role sign-off.`:'One controlled decision.'}</span></div>`}<div class="approval-scope-chips">${scopes.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="approval-signer-list">${p.signers.map(g=>{const canSign=g.pending.length&&g.pending.every(canApproveRecord);return `<div class="approval-signer-row ${g.done?'done':'pending'}"><div class="approval-signer-copy"><strong>${esc(g.person)}</strong><span>${esc(g.role)}</span><small>Covers: ${g.scopes.map(esc).join(' · ')||'configured decision scope'}</small></div><div class="approval-signer-action">${approvalSignerStatusV1058(g)}${canSign?btn(`Sign off${g.pending.length>1?` ${g.pending.length} covered items`:''}`,`data-approve-package-signer="${esc(r.id)}|${esc(kind)}|${encodeURIComponent(g.key)}"`,'button small next-action'):!g.done&&g.roleId&&currentRole()!=='administrator'?btn(`Switch to ${esc(g.role)} →`,`data-switch-role="${esc(g.roleId)}"`,'button tiny secondary'):''}</div></div>`}).join('')}</div></div>`}
async function approvePackageSignerV1058(requestId,kind,encodedKey){const r=requestById(requestId);if(!r)return;const p=approvalPackageSummaryV1058(r,kind),key=decodeURIComponent(encodedKey||''),g=p.signers.find(x=>x.key===key);if(!g){toast('Signer package is no longer available. Refresh the page.',true);return}const rows=g.pending.filter(canApproveRecord);if(!rows.length){toast(`This sign-off is owned by ${g.role}.`,true);return}const now=P.now();for(const a of rows){const prev=a.status;a.status='Approved';a.person=App.state.identity.name;a.timestamp=now;a.comment=a.comment&&a.comment!=='Pending'?a.comment:`Approved as part of consolidated ${p.meta.label.toLowerCase()}`;P.audit(App.state,'Approval package sign-off completed','Approval',a.id,prev,'Approved',`${p.meta.label} · ${a.type} · ${App.state.identity.name}`)}if(kind==='definition'){const areas=[...new Set(rows.map(a=>a.changeArea).filter(Boolean))];for(const area of areas){if(P.buildChangeApprovalsComplete(App.state,r,area)){const pack=P.ensureReusePackage(r);(pack.deltas||[]).filter(d=>d.area===area&&d.status==='Open').forEach(d=>{d.status='Reviewed';d.reviewedAt=now})}}}await persist();render();toast(`${p.meta.label}: ${g.role} sign-off recorded${rows.length>1?` for ${rows.length} covered items`:''}.`)}
function openApprovalPackageV1058(requestId,kind){const r=requestById(requestId);if(!r)return;const p=approvalPackageSummaryV1058(r,kind);openModal(`${p.meta.label} · ${r.id}`,`${approvalPackageCardV1058(r,kind,{embedded:true})}<div class="callout"><strong>Approval rule</strong><p>Repeated clicks are not required for the same person at the same decision point. One signer action covers that signer’s related records. Distinct independent roles remain distinct signatures.</p></div>`,btn('Close','data-modal-close','button'),true);setTimeout(()=>bindApprovalPackageActionsV1058($('#modalRoot')),0)}
function bindApprovalPackageActionsV1058(root=document){$$('[data-approve-package-signer]',root).forEach(el=>el.onclick=()=>{const [rid,kind,key]=el.dataset.approvePackageSigner.split('|');approvePackageSignerV1058(rid,kind,key)});$$('[data-open-approval-package]',root).forEach(el=>el.onclick=()=>{const [rid,kind]=el.dataset.openApprovalPackage.split('|');openApprovalPackageV1058(rid,kind)})}

const _buildChangeReviewPanelV1058=buildChangeReviewPanel;
buildChangeReviewPanel=function(r,area=null){const p=approvalPackageSummaryV1058(r,'definition');if(!p.records.length)return'';return approvalPackageCardV1058(r,'definition')};

const _workspaceApprovalsV1058=workspaceApprovals;
workspaceApprovals=function(r,controlOnly=false){const kind=controlOnly?'readiness':'release',pkg=approvalPackageSummaryV1058(r,kind),releaseAction=!controlOnly&&(can('release:review')||can('release:approve'))&&['QUALITY REVIEW','ENGINEERING REVIEW','RELEASE APPROVAL','BUILD READINESS REVIEW','READY TO BUILD'].includes(r.status)?btn('Run final release check',`data-release-request="${r.id}"`,'button next-action'):'';return `<div class="card approval-workbench"><div class="section-title-row"><div><span class="eyebrow">${controlOnly?'READINESS / SAFETY DECISION':'RELEASE DECISION'}</span><h2>${controlOnly?'Only genuine independent sign-offs':'One release package, all required signers'}</h2><p class="subtle">${controlOnly?'Ordinary readiness evidence no longer appears as a separate approval. Product-safety or other explicitly configured independent decisions remain visible here.':'Repeated approval records are consolidated by signer. If several roles are required, every signer is shown explicitly with progress.'}</p></div><div>${releaseAction}</div></div>${approvalPackageCardV1058(r,kind)}</div>`};

const _guidedApprovalDockV1058=guidedApprovalDock;
guidedApprovalDock=function(r,step){P.ensureApprovalRecords(App.state,r);const cp=App.state.controlPlans.find(x=>x.id===r.controlPlanId);if(step?.id==='controls'&&cp&&cp.status!=='Approved'){const ap=controlPlanApprovalState(cp);const definition=approvalPackageSummaryV1058(r,'definition'),readiness=approvalPackageSummaryV1058(r,'readiness');if(definition.pending.length)return btn(`${definition.done}/${definition.total} change signers`, `data-open-approval-package="${r.id}|definition"`,'button small next-action workflow-dock-button');if(ap.stage==='definition'){if(can('controlplan:edit')||currentRole()==='administrator')return btn('Complete Control Plan definition',`data-cp-definition-resolver="${cp.id}"`,'button small next-action workflow-dock-button');return btn('Switch to Quality Engineer →','data-switch-role="quality"','button small secondary workflow-dock-button')}if(ap.stage==='submit-review')return (can('controlplan:edit')||currentRole()==='administrator')?btn('Submit Control Plan for review',`data-request-cp-review="${cp.id}"`,'button small next-action workflow-dock-button'):btn('Awaiting review request','data-workspace-tab="controls"','button small secondary workflow-dock-button');if(ap.canApprove)return btn('Approve Control Plan',`data-approve-cp="${cp.id}"`,'button small next-action workflow-dock-button');if(ap.switchRole)return btn(`Switch to ${roleLabel(ap.switchRole)} →`,`data-switch-role="${ap.switchRole}"`,'button small secondary workflow-dock-button');if(readiness.pending.length)return btn(`${readiness.done}/${readiness.total} safety signers`,`data-open-approval-package="${r.id}|readiness"`,'button small next-action workflow-dock-button')}if(step?.id==='controls'){const p=approvalPackageSummaryV1058(r,'readiness');if(p.pending.length)return btn(`${p.done}/${p.total} safety signers`,`data-open-approval-package="${r.id}|readiness"`,'button small next-action workflow-dock-button')}if(step?.id==='approvals'){const p=approvalPackageSummaryV1058(r,'release');if(p.records.length){return btn(p.pending.length?`${p.done}/${p.total} release signers`:'All release signers complete',`data-open-approval-package="${r.id}|release"`,`button small ${p.pending.length?'next-action':'secondary'} workflow-dock-button`)}}const pending=(App.state.approvals||[]).filter(a=>a.requestId===r.id&&approvalRecordVisibleV1058(a)&&a.status==='Pending'&&a.type!=='Build Report Approval');if(pending.length){const a=pending[0],kind=approvalPackageKindV1058(a),p=approvalPackageSummaryV1058(r,kind);return btn(`${p.done}/${p.total} ${p.meta.label.toLowerCase()}`,`data-open-approval-package="${r.id}|${kind}"`,'button small next-action workflow-dock-button')}return `<span class="workflow-dock-clear"><span>✓</span><b>Sign-offs clear</b></span>`};

const _buildGuidedStepsV1058=buildGuidedSteps;
buildGuidedSteps=function(r){const steps=_buildGuidedStepsV1058(r);const controls=steps.find(s=>s.id==='controls'),release=steps.find(s=>s.id==='approvals');if(controls){const groups=[...approvalPackageSummaryV1058(r,'definition').pending,...approvalPackageSummaryV1058(r,'readiness').pending];if(groups.length){controls.owner=groups.map(g=>`${g.person} · ${g.role}`).join(' + ');controls.next=`${groups.length} required signer${groups.length===1?'':'s'} remain: ${groups.map(g=>g.role).join(', ')}`}}if(release){const p=approvalPackageSummaryV1058(r,'release');if(p.pending.length){release.owner=p.pending.map(g=>`${g.person} · ${g.role}`).join(' + ');release.next=`Release sign-off ${p.done}/${p.total} complete · waiting on ${p.pending.map(g=>g.role).join(', ')}`}}return steps};

const _workspaceFixedCockpitV1058=workspaceFixedCockpit;
workspaceFixedCockpit=function(r,steps){const step=selectedGuidedStep(steps),edit=canEditRequest(r)?btn('Edit build info',`data-edit-request="${r.id}"`,'button small secondary workflow-dock-button'):`<button class="button small workflow-dock-button" type="button" disabled>View build info</button>`,commit=P.commitmentMetrics(r),approval=guidedApprovalDock(r,step),nextAction=guidedNextDock(r,steps,step),idx=steps.findIndex(s=>s.id===step?.id),nextStep=steps.slice(Math.max(0,idx+1)).find(s=>!s.done)||steps.find(s=>!s.done);return `<div class="workspace-fixed-cockpit"><div class="workspace-context-strip"><div class="workspace-context-primary"><span>BUILD</span><strong>${esc(r.id)} · ${esc(r.title)}</strong></div><div><span>PRODUCT / QTY</span><strong>${esc(r.productFamily)} · ${r.quantity}</strong></div><div><span>COMMITMENT</span><strong>${P.formatDate(commit.current)}</strong></div><div><span>FORECAST</span><strong>${r.forecastDate?P.formatDate(r.forecastDate):'Not planned'}</strong></div><div><span>OWNER</span><strong>${esc(r.owner)}</strong></div></div>${renderGuidedMobileRail(steps)}<div class="workflow-command-bar"><div class="workflow-command-slot workflow-edit-slot"><span class="workflow-slot-label">EDIT</span>${edit}</div><div class="workflow-command-current"><span class="workflow-step-icon ${step?.state||'pending'}">${step?guidedStatusIcon(step):'●'}</span><div><span class="workflow-slot-label">STEP ${step?.index||'—'} · ${esc(step?.phase||'WORKFLOW')}</span><strong>${esc(step?.title||'Workflow')}</strong><small><b>Owner:</b> ${esc(step?.owner||r.owner)} · ${esc(step?.next||'')}</small></div></div><div class="workflow-command-slot workflow-approval-slot"><span class="workflow-slot-label">SIGN-OFF</span>${approval}</div><div class="workflow-command-slot workflow-next-slot"><span class="workflow-slot-label">NEXT STEP</span>${nextAction}${nextStep?`<small class="workflow-next-owner"><b>Owner:</b> ${esc(nextStep.owner||r.owner)}</small>`:''}</div></div>${workspaceExecutionRouteRail(r)}</div>`};

const _reusePackagePanelV1058=reusePackagePanel;
reusePackagePanel=function(r){let html=_reusePackagePanelV1058(r),p=approvalPackageSummaryV1058(r,'definition');if(p.records.length){html=html.replace(/<span class="status [^"]+">[^<]*change review[^<]*<\/span>/i,`<span class="status ${p.pending.length?'warn':'good'}">${p.done}/${p.total} change signers</span>`)}return html};

const _renderQualityActionBoardV1058=renderQualityActionBoard;
renderQualityActionBoard=function(){let html=_renderQualityActionBoardV1058();const packages=[];for(const r of App.state.requests||[]){for(const kind of ['definition','readiness','release']){const p=approvalPackageSummaryV1058(r,kind);const qualityRelevant=p.pending.some(g=>g.roleId==='quality'||/quality/i.test(g.role));if(p.pending.length&&qualityRelevant)packages.push({r,p,kind})}}if(!packages.length)return html;const block=`<div class="card quality-approval-queue consolidated"><div class="section-title-row"><div><span class="eyebrow">CONSOLIDATED SIGN-OFF QUEUE</span><h2>${packages.length} decision package${packages.length===1?'':'s'} waiting</h2><p class="subtle">One row per build decision point, not one row per underlying approval record.</p></div></div>${packages.slice(0,6).map(({r,p,kind})=>`<button type="button" class="quality-approval-package-row" data-open-approval-package="${r.id}|${kind}"><div><strong>${esc(r.id)} · ${esc(p.meta.label)}</strong><span>${p.done}/${p.total} signers complete · next: ${esc(p.pending.map(g=>g.person).join(', '))}</span></div><b>${p.pending.length} waiting ›</b></button>`).join('')}</div>`;html=html.replace(/<div class="card quality-approval-queue">[\s\S]*?<\/div><div class="section-stack quality-case-list">/,block+'<div class="section-stack quality-case-list">');return html};

function approvalPendingForCurrentRoleV1058(){for(const r of App.state.requests||[]){for(const kind of ['definition','readiness','release','report']){const p=approvalPackageSummaryV1058(r,kind);for(const g of p.pending){if(g.pending.some(canApproveRecord))return {r,kind,p,g}}}}return null}
function globalNextGuidanceV1058(){if(App.currentView==='workspace')return null;const approval=approvalPendingForCurrentRoleV1058();if(approval)return {state:'warn',eyebrow:'MY NEXT SIGN-OFF',title:`${approval.r.id} · ${approval.p.meta.label}`,owner:`${approval.g.person} · ${approval.g.role}`,context:`${approval.p.done}/${approval.p.total} signers complete`,attrs:`data-open-approval-package="${approval.r.id}|${approval.kind}"`,button:'Open sign-off'};const mine=openActions().slice().sort((a,b)=>(a.severity==='bad'?0:1)-(b.severity==='bad'?0:1)||String(a.due||'').localeCompare(String(b.due||'')))[0];if(mine)return {state:mine.severity==='bad'?'bad':'warn',eyebrow:'MY NEXT ACTION',title:mine.title,owner:mine.owner||'Unassigned',context:`${mine.requestId||mine.category||'LabOS'}${mine.due?` · due ${P.formatDate(mine.due)}`:''}`,attrs:mine.id?`data-resolve-action="${esc(mine.id)}"`:`data-nav="${esc(mine.resolve||'action-centre')}"`,button:mine.careItemKey?'Complete':'Open'};if(['lab_planner','administrator'].includes(currentRole())){const move=(App.state.requests||[]).find(r=>r.currentCommitmentDate&&r.forecastDate&&r.currentCommitmentDate!==r.forecastDate&&!['CLOSED','DELIVERED'].includes(r.status));if(move){const owner=(App.state.users||[]).find(u=>u.role==='lab_planner')?.name||'Prototype Lab Planner';return {state:'warn',eyebrow:'NEXT PLANNING DECISION',title:`${move.id} · commitment movement`,owner:`${owner} · Prototype Lab Planner`,context:`${P.formatDate(move.currentCommitmentDate)} → ${P.formatDate(move.forecastDate)}`,attrs:'data-review-commitments',button:'Review'}}}const team=allOpenActions().slice().sort((a,b)=>(a.severity==='bad'?0:1)-(b.severity==='bad'?0:1)||String(a.due||'').localeCompare(String(b.due||'')))[0];if(team)return {state:team.severity==='bad'?'bad':'warn',eyebrow:'TEAM NEXT ACTION',title:team.title,owner:team.owner||'Unassigned',context:`${team.requestId||team.category||'LabOS'}${team.due?` · due ${P.formatDate(team.due)}`:''}`,attrs:team.id?`data-resolve-action="${esc(team.id)}"`:`data-nav="${esc(team.resolve||'action-centre')}"`,button:'Open'};return {state:'good',eyebrow:'NEXT ACTION',title:'No outstanding action is currently assigned',owner:'—',context:'Continue normal planned work; new blockers and sign-offs will appear here.',attrs:'data-nav="dashboard"',button:'Dashboard'}}
function installGlobalNextGuidanceV1058(){if(App.currentView==='workspace')return;const page=$('#page'),head=page?.querySelector('.page-header');if(!page||!head||page.querySelector('.global-next-guide'))return;const g=globalNextGuidanceV1058();if(!g)return;const el=document.createElement('div');el.className=`global-next-guide ${g.state}`;el.innerHTML=`<div class="global-next-icon">${g.state==='bad'?'✕':g.state==='good'?'✓':'●'}</div><div class="global-next-copy"><span>${esc(g.eyebrow)}</span><strong>${esc(g.title)}</strong><small><b>Owner:</b> ${esc(g.owner)} · ${esc(g.context)}</small></div>${btn(g.button,g.attrs,`button small ${g.state==='bad'?'blocker-action':'next-action'}`)}`;head.insertAdjacentElement('afterend',el);bindApprovalPackageActionsV1058(el)}

const _bindDynamicV1058=bindDynamic;
