approvalPackageCardV1058=function(r,kind,{embedded=false}={}){const p=approvalPackageSummaryV1058(r,kind),m=p.meta;if(!p.records.length)return `<div class="callout reuse-good"><strong>✓ No ${esc(m.label.toLowerCase())} required</strong><p>No additional signer has been configured for this decision point.</p></div>`;const multi=p.total>1,scopes=[...new Set(p.records.map(a=>a.changeArea||a.type).filter(Boolean))];return `<div class="approval-package ${p.pending.length?'pending':'complete'} ${embedded?'embedded':''}"><div class="approval-package-head"><div><span class="eyebrow">${esc(m.eyebrow)}</span><h3>${esc(m.label)}</h3><p>${esc(m.description)}</p></div><div class="approval-package-progress ${p.pending.length?'warn':'good'}"><strong>${p.done}/${p.total}</strong><span>${p.total===1?'signer':'signers'} complete</span></div></div>${multi?`<div class="approval-multi-note"><strong>${p.total} people / roles must sign off.</strong><span>Each distinct independent signer remains visible. Related records for one signer are completed in one action.</span></div>`:`<div class="approval-multi-note single"><strong>1 signer required.</strong><span>${p.records.length>1?`${p.records.length} related approval items are consolidated into that one role sign-off.`:'One controlled decision.'}</span></div>`}<div class="approval-scope-chips">${scopes.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="approval-signer-list">${p.signers.map(g=>{const canSign=g.pending.length&&g.pending.every(canApproveRecord),token=encodeURIComponent(JSON.stringify(g.pending.map(a=>a.id)));return `<div class="approval-signer-row ${g.done?'done':'pending'}"><div class="approval-signer-copy"><strong>${esc(g.person)}</strong><span>${esc(g.role)}</span><small>Covers: ${g.scopes.map(esc).join(' · ')||'configured decision scope'}</small></div><div class="approval-signer-action">${approvalSignerStatusV1058(g)}${canSign?btn(`Sign off${g.pending.length>1?` ${g.pending.length} covered items`:''}`,`data-approve-package-records="${esc(r.id)}|${esc(kind)}|${esc(token)}"`,'button small next-action'):!g.done&&g.roleId&&currentRole()!=='administrator'?btn(`Switch to ${esc(g.role)} →`,`data-switch-role="${esc(g.roleId)}"`,'button tiny secondary'):''}</div></div>`}).join('')}</div></div>`};
async function approvePackageRecordsV1059(requestId,kind,token){const r=requestById(requestId);if(!r)return;let ids=[];try{ids=JSON.parse(decodeURIComponent(token||''))}catch(_){toast('The sign-off payload is invalid. Reopen the decision package.',true);return}const p=approvalPackageSummaryV1058(r,kind),rows=(App.state.approvals||[]).filter(a=>ids.includes(a.id)&&a.requestId===requestId&&a.status==='Pending');if(!rows.length){toast('This sign-off has already moved or was completed. The package has been refreshed.');openApprovalPackageV1058(requestId,kind);return}if(rows.some(a=>!canApproveRecord(a))){toast(`This sign-off is owned by ${rows[0]?.role||'another authorised role'}.`,true);return}const now=P.now(),role=rows[0]?.role||'Required signer';for(const a of rows){const prev=a.status;a.status='Approved';a.signedBy=App.state.identity.name;a.timestamp=now;a.comment=a.comment&&a.comment!=='Pending'?a.comment:`Approved as part of consolidated ${p.meta.label.toLowerCase()}`;P.audit(App.state,'Approval package sign-off completed','Approval',a.id,prev,'Approved',`${p.meta.label} · ${a.type} · signed by ${App.state.identity.name}`)}if(kind==='definition'){const areas=[...new Set(rows.map(a=>a.changeArea).filter(Boolean))];for(const area of areas){if(P.buildChangeApprovalsComplete(App.state,r,area)){const pack=P.ensureReusePackage(r);(pack.deltas||[]).filter(d=>d.area===area&&d.status==='Open').forEach(d=>{d.status='Reviewed';d.reviewedAt=now})}}}await persist();render();openApprovalPackageV1058(requestId,kind);toast(`${p.meta.label}: ${role} sign-off recorded${rows.length>1?` for ${rows.length} covered items`:''}.`)}
bindApprovalPackageActionsV1058=function(root=document){root.querySelectorAll?.('[data-approve-package-records]').forEach(el=>el.onclick=()=>{const [rid,kind,token]=el.dataset.approvePackageRecords.split('|');approvePackageRecordsV1059(rid,kind,token)});root.querySelectorAll?.('[data-open-approval-package]').forEach(el=>el.onclick=()=>{const [rid,kind]=el.dataset.openApprovalPackage.split('|');openApprovalPackageV1058(rid,kind)});root.querySelectorAll?.('[data-switch-role]').forEach(el=>{if(el.dataset.v1059RoleBound)return;el.dataset.v1059RoleBound='1';el.addEventListener('click',async e=>{if(!el.dataset.switchRole)return;e.preventDefault();e.stopPropagation();App.identity.switchRole(el.dataset.switchRole);populateRoles();await persist();closeModal();render();toast(`Switched to ${roleLabel(el.dataset.switchRole)}.`)})})};

