/* REV 1.0.60 — zero-guess blocker resolution for engineering clarifications */
function clarificationRequirementV1060(a,r){
 const text=`${a?.title||''} ${a?.why||''} ${a?.impact||''}`.toLowerCase(),objective=String(r?.objective||'').trim(),config=String(r?.configuration||'').trim(),iface=String(r?.interfaceDefinition||'').trim();
 if(!objective)return {key:'objective',label:'Engineering objective',value:objective,placeholder:'State the engineering decision, learning or validation this build must enable.',help:'Describe the intended outcome clearly enough for the lab to choose the right process route, tests and evidence level.'};
 if(/interface|programming|flashing|calibration interface/.test(text))return {key:'interfaceDefinition',label:'Programming / calibration interface definition',value:iface||(config.length>30&&/interface|program|flash|calibr|protocol|connector|tool/i.test(config)?config:''),placeholder:'e.g. IF-PSC-003 Rev A · HW P3 / SW 0.9.8 · CAN UDS · fixture J4 · Tool CalSuite 2.1 · 0–5 V range',help:'Enter enough for Process Engineering to act: released interface/procedure reference if one exists; HW/SW revision; connector/protocol; programming or calibration tool/method; and applicable limits/constraints.'};
 return {key:'configuration',label:'Build configuration',value:config,placeholder:'Define the exact product/build configuration required.',help:'Identify the configuration/revision and any build-specific interfaces, variants or constraints that affect the lab route.'};
}
function clarificationOwnerV1060(role){const u=(App.state.users||[]).find(x=>x.role===role)||(App.state.staff||[]).find(x=>x.role===role);return {role,name:u?.name||roleLabel(role)}}
const _actionResolutionModelV1060=actionResolutionModel;
actionResolutionModel=function(a){
 const m=_actionResolutionModelV1060(a);if(m.kind!=='clarification'||!m.r)return m;const r=m.r,req=clarificationRequirementV1060(a,r),eng=(App.state.users||[]).find(x=>x.name===a.owner)||clarificationOwnerV1060('engineering_requester'),planner=clarificationOwnerV1060('lab_planner');
 const objective=String(r.objective||'').trim(),config=String(r.configuration||'').trim(),iface=String(r.interfaceDefinition||'').trim(),interfaceSpecific=req.key==='interfaceDefinition',technicalDone=interfaceSpecific?!!(iface||(config.length>30&&/interface|program|flash|calibr|protocol|connector|tool/i.test(config))):req.key==='configuration'?!!config:true,reassessed=!!r.clarificationReassessedAt;
 m.stages=[{key:'objective',label:'Engineering objective clear',done:!!objective,ownerName:eng.name,ownerRole:'engineering_requester'},{key:interfaceSpecific?'interfaceDefinition':'configuration',label:interfaceSpecific?'Programming / calibration interface defined':'Configuration defined',done:technicalDone,ownerName:eng.name,ownerRole:'engineering_requester'},{key:'reassess',label:'Lab feasibility reassessed',done:reassessed,ownerName:planner.name,ownerRole:'lab_planner'}];
 m.current=m.stages.find(x=>!x.done)||m.stages[m.stages.length-1];m.currentOwnerRole=m.current.ownerRole;m.currentOwnerName=m.current.ownerName;m.ownerRole=m.current.ownerRole;m.guidance=req;m.primaryLabel=m.current.key==='reassess'?'Reassess feasibility now':m.current.key==='objective'?'Save objective & continue':interfaceSpecific?'Save interface definition & continue':'Save configuration & continue';m.clears=interfaceSpecific?'This clarification clears after the programming/calibration interface is defined and Lab Planning has rechecked feasibility. If that recheck exposes a process-development or material blocker, LabOS opens that exact next workflow.':'This clarification clears after the missing engineering input is saved and Lab Planning has rechecked feasibility.';m.context=`Objective: ${objective||'missing'} · Configuration: ${config||'missing'}${interfaceSpecific?` · Interface: ${iface||'missing'}`:''}`;return m;
};
function clarificationStageRowsV1060(m){return m.stages.map((x,i)=>`<div class="resolution-step ${x.done?'complete':m.current?.key===x.key?'current':'pending'}"><span class="resolution-index">${x.done?'✓':i+1}</span><div><strong>${esc(x.label)}</strong><small>${x.done?'Complete':m.current?.key===x.key?'Current action':'Waiting'} · Owner: ${esc(x.ownerName||roleLabel(x.ownerRole))}</small></div></div>`).join('')}
function clarificationEditorV1060(m,a){if(m.current?.key==='reassess')return `<div class="guided-resolution-editor"><span class="eyebrow">WHAT HAPPENS NEXT</span><h3>Recheck lab feasibility</h3><p>The engineering clarification is now complete. LabOS will reassess material and process/method feasibility, close this clarification action, and route you to the exact remaining blocker or planning step. It will <b>not</b> silently commit a delivery date.</p><div class="resolution-owner-line"><strong>Current owner</strong><span>${esc(m.currentOwnerName)} · ${esc(roleLabel(m.currentOwnerRole))}</span></div></div>`;const g=m.guidance||clarificationRequirementV1060(a,m.r);return `<div class="guided-resolution-editor"><span class="eyebrow">DO THIS NOW</span><h3>${esc(g.label)}</h3><p>${esc(g.help)}</p><div class="field"><label>${esc(g.label)} <b>· required</b></label><textarea id="resolutionClarificationInput" rows="5" placeholder="${esc(g.placeholder||'Enter the missing controlled definition')}">${esc(g.value||'')}</textarea></div><div class="resolution-owner-line"><strong>Owner</strong><span>${esc(m.currentOwnerName)} · ${esc(roleLabel(m.currentOwnerRole))}</span></div></div>`}
const _resolveActionModalV1060=resolveActionModal;
resolveActionModal=function(actionId){
 const a=(App.state.actions||[]).find(x=>x.id===actionId);if(!a)return _resolveActionModalV1060(actionId);const m=actionResolutionModel(a);if(m.kind!=='clarification'||!m.r)return _resolveActionModalV1060(actionId);App.activeActionId=actionId;const roleName=roleLabel(m.currentOwnerRole),sameRole=currentRole()===m.currentOwnerRole||currentRole()==='administrator',next=m.stages[m.stages.findIndex(x=>x.key===m.current?.key)+1];
 const why=`<div class="guided-resolution-why"><span class="eyebrow">BLOCKED BECAUSE</span><strong>${esc(a.why||a.title)}</strong><p>${esc(a.impact||'The lab cannot complete the next controlled decision with the current evidence.')}</p><small><b>Closure:</b> ${esc(m.clears)}</small></div>`;
 const nextOwner=next?`<div class="resolution-next-owner"><strong>After this</strong><span>${esc(next.label)} · ${esc(next.ownerName||roleLabel(next.ownerRole))}</span></div>`:'';
 openModal(`Resolve · ${a.title}`,`${why}<div class="resolution-steps compact">${clarificationStageRowsV1060(m)}</div>${clarificationEditorV1060(m,a)}${nextOwner}`,`${btn('Close','data-modal-close','button')}${btn('Open build','data-resolution-context','button secondary')}${!sameRole?btn(`Switch to ${roleName}`,'data-resolution-switch-role','button secondary'):''}${btn(m.primaryLabel,'data-resolution-primary','button next-action')}`,true);
 setTimeout(()=>{const context=$('[data-resolution-context]'),sw=$('[data-resolution-switch-role]'),primary=$('[data-resolution-primary]');if(context)context.onclick=()=>{closeModal();openRequest(a.requestId,'overview')};if(sw)sw.onclick=async()=>{App.identity.switchRole(m.currentOwnerRole);populateRoles();await persist();closeModal();resolveActionModal(actionId);toast(`Switched to ${roleName}.`)};if(primary)primary.onclick=()=>continueActionResolution(actionId)},0);
};
async function saveClarificationInputV1060(actionId,m){const a=(App.state.actions||[]).find(x=>x.id===actionId),r=m.r;if(!a||!r)return;const input=$('#resolutionClarificationInput'),value=String(input?.value||'').trim();if(value.length<5){toast(`Enter the required ${m.guidance?.label||'definition'} before continuing.`,true);input?.focus();return}const before=P.deepClone(r),key=m.current.key;if(key==='objective')r.objective=value;else if(key==='interfaceDefinition')r.interfaceDefinition=value;else r.configuration=value;r.clarificationReassessedAt=null;r.triage=null;r.forecastDate=null;App.state.bookings=(App.state.bookings||[]).filter(b=>b.requestId!==r.id);r.changeHistory=r.changeHistory||[];r.changeHistory.unshift({id:P.uid('CHG'),date:P.now(),type:'Guided clarification',from:key==='interfaceDefinition'?(before.interfaceDefinition||''):(before[key]||''),to:value,impact:['Lab feasibility must be reassessed'],status:'Open'});P.audit(App.state,'Guided clarification recorded','Request',r.id,key==='interfaceDefinition'?(before.interfaceDefinition||''):(before[key]||''),value,`${m.guidance?.label||key} supplied from Action Centre resolution`);await persist();closeModal();render();setTimeout(()=>resolveActionModal(actionId),30);toast(`${m.guidance?.label||'Clarification'} saved. Continue with the next guided step.`)}
async function reassessClarificationV1060(actionId,m){const a=(App.state.actions||[]).find(x=>x.id===actionId),r=m.r;if(!a||!r)return;P.ensurePlanningModel(App.state);const mat=P.materialPlanningAssessment(App.state,r),proc=P.processPlanningAssessment(App.state,r);r.clarificationReassessedAt=P.now();App.state.actions=(App.state.actions||[]).filter(x=>x.id!==actionId);P.audit(App.state,'Engineering clarification resolved and feasibility reassessed','Action',actionId,'Open','Resolved',`Material: ${mat?.planningReady?'ready':'not ready'} · Process/method: ${proc?.ready?'ready':'not ready'}`);await persist();closeModal();render();if(!mat?.planningReady){openRequest(r.id,'materials');toast(`Clarification resolved. Next: ${mat?.summary||'resolve material feasibility'}. Owner: ${clarificationOwnerV1060('lab_planner').name}.`,true);return}if(!proc?.ready){openRequest(r.id,'processrisk');toast(`Clarification resolved. Next process/method blocker: ${proc?.issues?.[0]||'route or method feasibility'}. Owner: ${clarificationOwnerV1060('process_engineer').name}.`,true);return}openRequest(r.id,'planning');toast(`Clarification resolved. Feasibility is ready. Next: calculate/review the feasible plan. Owner: ${clarificationOwnerV1060('lab_planner').name}.`)}
const _continueActionResolutionV1060=continueActionResolution;
continueActionResolution=async function(actionId){const a=(App.state.actions||[]).find(x=>x.id===actionId);if(!a)return;const m=actionResolutionModel(a);if(m.kind==='clarification'&&m.r){const allowed=currentRole()===m.currentOwnerRole||currentRole()==='administrator';if(!allowed){toast(`Current step is owned by ${m.currentOwnerName||roleLabel(m.currentOwnerRole)}. Switch role first.`,true);return}if(m.current?.key==='reassess')return reassessClarificationV1060(actionId,m);return saveClarificationInputV1060(actionId,m)}return _continueActionResolutionV1060(actionId)};


/* ============================================================
   LabOS REV 1.0.61 — guided UX + resource assurance patch
   Static/GitHub Pages build. No backend dependency.
   ============================================================ */
function isArchivedV1061(r){return !!(r&&(r.archived||r.status==='CLOSED'||r.status==='ARCHIVED'))}
const _canEditRequestV1061=canEditRequest;
canEditRequest=function(r){return !isArchivedV1061(r)&&_canEditRequestV1061(r)};

function workflowMissingInputsV1061(r){
 const missing=[];
 if(!String(r.productId||r.productFamily||'').trim())missing.push({key:'product',label:'Product / device',help:'Select the requested product or device family.'});
 if(!String(r.configuration||'').trim()||String(r.configuration||'').trim()==='—')missing.push({key:'configuration',label:'Build configuration',help:'Enter the build configuration, variant or controlled configuration reference.'});
 if(!(Number(r.quantity)>0))missing.push({key:'quantity',label:'Quantity',help:'Enter the required prototype quantity.'});
 if(!String(r.requiredDate||'').trim())missing.push({key:'requiredDate',label:'Required date',help:'Enter the date Engineering needs the prototypes.'});
 if(!String(r.objective||'').trim())missing.push({key:'objective',label:'Engineering objective',help:'State what Engineering needs to learn, prove or receive from this build.'});
 return missing;
}
function installWorkspaceGuidanceV1061(){
 if(App.currentView!=='workspace')return;const r=requestById(App.workspaceId);if(!r)return;
 const page=$('#page');if(!page)return;
 if(isArchivedV1061(r)){
   const h=page.querySelector('.page-header,.workspace-cockpit');if(h&&!page.querySelector('.archive-readonly-banner'))h.insertAdjacentHTML('afterend',`<div class="callout archive-readonly-banner"><strong>Archived build · read-only</strong><p>${esc(r.archiveReason||'This build was archived and is retained as controlled history.')} ${r.archivedAt?`Archived ${P.formatDateTime(r.archivedAt)}.`:''}</p></div>`);
   page.querySelectorAll('button,input,select,textarea').forEach(el=>{if(!el.matches('[data-workspace-tab],[data-report],[data-route-sheet],[data-build-files],[data-admin-build-action],[data-nav],[data-modal-close]'))el.disabled=true});
 }
 const missing=workflowMissingInputsV1061(r);
 if(missing.length){
   const target=page.querySelector('.workspace-body,.workspace-main,.workspace-content')||page.querySelector('.page-header')||page.firstElementChild;
   if(target&&!page.querySelector('.required-input-guidance-v1061')){
     const first=missing[0];target.insertAdjacentHTML(target.classList.contains('page-header')?'afterend':'afterbegin',`<div class="callout warn required-input-guidance-v1061"><div class="section-title-row"><div><span class="eyebrow">REQUESTER ACTION REQUIRED</span><h3>${missing.length} required input${missing.length===1?'':'s'} missing</h3><p><b>${esc(first.label)}</b> is incomplete. ${esc(first.help)}</p><small>Owner: ${esc(r.requester||App.state.identity.name)} · Engineering Requester. Once completed, LabOS will require the Lab Planner to reassess feasibility before timing is committed.</small></div><div>${btn(`Complete ${esc(first.label)} →`,`data-v1061-complete-request="${esc(first.key)}"`,'button next-action')}</div></div></div>`);
   }
 }
 if(currentRole()==='administrator'&&!isArchivedV1061(r)){
   const actions=page.querySelector('.header-actions,.workspace-cockpit .route-toolbar');
   if(actions&&!actions.querySelector('[data-admin-build-action]'))actions.insertAdjacentHTML('beforeend',btn('Admin actions ▾',`data-admin-build-action="${esc(r.id)}"`,'button small secondary'));
 }
}
function completeRequesterInputV1061(key){const r=requestById(App.workspaceId);if(!r)return;editRequestModal(r.id);setTimeout(()=>{const candidates={configuration:['#erqConfig'],objective:['#erqObjective'],quantity:['#erqQty'],requiredDate:['#erqDate'],product:['#reqProduct','#productId','[name="productId"]']};for(const q of candidates[key]||[]){const el=$(q);if(el){el.focus();el.scrollIntoView({block:'center'});break}}},80)}

function adminBuildActionModalV1061(id){const r=requestById(id);if(!r)return;const inactiveDays=Math.max(0,Math.floor((Date.now()-new Date(r.updatedAt||r.submittedAt||Date.now()))/86400000));openModal(`Administrator · ${r.id}`,`<div class="callout"><strong>${esc(r.title)}</strong><p>Status: ${esc(r.status)} · last recorded activity about ${inactiveDays} day${inactiveDays===1?'':'s'} ago.</p></div><div class="admin-action-list"><button class="admin-action-row danger" data-v1061-abort-archive="${esc(id)}"><span>Abort and archive build</span><small>Stops future work, removes live bookings and preserves the record read-only.</small></button><button class="admin-action-row" data-v1061-archive-manager><span>Archive manager</span><small>Review archived builds and permanently delete only records older than a date you choose.</small></button></div>`,btn('Close','data-modal-close','button'))}
function abortArchiveBuildV1061(id){const r=requestById(id);if(!r)return;openModal(`Abort & archive · ${r.id}`,`<div class="callout bad"><strong>This stops the build.</strong><p>Execution history and evidence are retained, but future bookings are removed and the build becomes read-only.</p></div><div class="field"><label>Reason <b>required</b></label><textarea id="v1061ArchiveReason" placeholder="Why is this build being aborted and archived?"></textarea></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Abort & archive','data-v1061-confirm-archive','button danger')}`);setTimeout(()=>{$('[data-v1061-confirm-archive]').onclick=async()=>{const reason=$('#v1061ArchiveReason').value.trim();if(reason.length<5){toast('Record a clear archive reason.',true);return}const before=r.status;r.archivePreviousStatus=before;r.archived=true;r.archiveDisposition='Aborted';r.status='CLOSED';r.archivedAt=P.now();r.archiveReason=reason;r.archivedBy=App.state.identity.name;const removed=(App.state.bookings||[]).filter(b=>b.requestId===r.id).length;App.state.bookings=(App.state.bookings||[]).filter(b=>b.requestId!==r.id);(App.state.actions||[]).filter(a=>a.requestId===r.id&&actionStillOpen(a)).forEach(a=>{a.status='Closed';a.closedAt=P.now();a.closureReason='Build aborted and archived'});P.audit(App.state,'Build aborted and archived','Request',r.id,before,'CLOSED / ABORTED',`${reason} · ${removed} future booking(s) removed`);await persist();closeModal();render();toast(`${r.id} archived read-only.`)}},0)}
function archiveManagerV1061(){const rows=(App.state.requests||[]).filter(isArchivedV1061).sort((a,b)=>String(a.archivedAt||'').localeCompare(String(b.archivedAt||'')));const def=new Date();def.setFullYear(def.getFullYear()-2);openModal('Archive manager',`<div class="callout"><strong>Permanent deletion is separate from archiving.</strong><p>Choose a cutoff date. Only builds archived before that date become eligible. Review the list before deleting.</p></div><div class="form-grid"><div class="field"><label>Eligible if archived before</label><input id="v1061ArchiveCutoff" type="date" value="${def.toISOString().slice(0,10)}"></div></div><div id="v1061ArchiveEligibility" class="archive-eligibility"></div>`,`${btn('Close','data-modal-close','button')}${btn('Delete eligible archives…','data-v1061-delete-eligible','button danger')}`,true);const redraw=()=>{const cut=$('#v1061ArchiveCutoff')?.value||'';const eligible=rows.filter(r=>String(r.archivedAt||r.closedAt||'').slice(0,10)<cut);$('#v1061ArchiveEligibility').innerHTML=`<div class="score-row"><span>Archived builds</span><strong>${rows.length}</strong></div><div class="score-row"><span>Eligible before ${P.formatDate(cut)}</span><strong>${eligible.length}</strong></div><div class="table-wrap"><table class="data-table compact"><thead><tr><th>Build</th><th>Archived</th><th>Reason</th><th>Eligible</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.id)}</strong><small>${esc(r.title)}</small></td><td>${P.formatDateTime(r.archivedAt||r.closedAt)}</td><td>${esc(r.archiveReason||'Completed / historic')}</td><td>${String(r.archivedAt||r.closedAt||'').slice(0,10)<cut?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div>`};redraw();$('#v1061ArchiveCutoff').onchange=redraw;$('[data-v1061-delete-eligible]').onclick=()=>deleteEligibleArchivesV1061($('#v1061ArchiveCutoff').value)}
function deleteEligibleArchivesV1061(cutoff){const eligible=(App.state.requests||[]).filter(r=>isArchivedV1061(r)&&String(r.archivedAt||r.closedAt||'').slice(0,10)<cutoff);if(!eligible.length){toast('No archived builds are older than that cutoff.',true);return}openModal('Confirm permanent deletion',`<div class="callout bad"><strong>${eligible.length} archived build${eligible.length===1?'':'s'} will be permanently deleted.</strong><p>This cannot be undone from LabOS. Export a backup first if retention is required.</p></div><div class="field"><label>Type DELETE to confirm</label><input id="v1061DeleteConfirm" autocomplete="off"></div>`,`${btn('Cancel','data-modal-close','button')}${btn(`Delete ${eligible.length} archive${eligible.length===1?'':'s'}`,'data-v1061-confirm-delete','button danger')}`);setTimeout(()=>{$('[data-v1061-confirm-delete]').onclick=async()=>{if($('#v1061DeleteConfirm').value!=='DELETE'){toast('Type DELETE exactly to confirm.',true);return}const ids=new Set(eligible.map(r=>r.id));const linkedKeys=['routes','bookings','serials','measurements','deviations','approvals','documents','allocations','actions'];for(const k of linkedKeys)App.state[k]=(App.state[k]||[]).filter(x=>!ids.has(x.requestId));App.state.resourceCareBookings=(App.state.resourceCareBookings||[]).filter(x=>!ids.has(x.sourceRequestId));App.state.requests=(App.state.requests||[]).filter(r=>!ids.has(r.id));P.audit(App.state,'Archived builds permanently deleted','Archive','Batch',`${eligible.length} retained build(s)`,'Deleted',`Cutoff ${cutoff} · IDs ${[...ids].join(', ')}`);await persist();closeModal();App.workspaceId=null;App.currentView='requests';render();toast(`${eligible.length} archived build${eligible.length===1?'':'s'} permanently deleted.`)}},0)}

function ehsAssuranceItemsV1061(){const today=new Date(`${P.todayISO()}T12:00:00`),out=[];const add=(kind,obj)=>{const d=obj?.ehsRiskAssessment;if(!d)return;let due;if(d.nextReviewDate)due=d.nextReviewDate;else if(d.approvedAt){const x=new Date(d.approvedAt);x.setFullYear(x.getFullYear()+1);due=x.toISOString().slice(0,10)}else due=P.todayISO();const days=Math.ceil((new Date(`${due}T12:00:00`)-today)/86400000);out.push({id:`EHS-${kind}-${obj.id}`,itemKey:`EHS-${kind}-${obj.id}`,type:'EHS',targetName:`${obj.name||obj.id}`,targetId:obj.id,dueDate:due,daysToDue:days,status:d.status==='Approved'?(days<0?'Overdue':'Due'):'Action required',capability:kind==='Equipment'?obj.capability:kind,sourceKind:kind,sourceObject:obj});};(App.state.equipment||[]).forEach(x=>add('Equipment',x));(App.state.processes||[]).forEach(x=>add('Process',x));(App.state.standardTests||[]).forEach(x=>add('Test',x));return out}
function allAssuranceItemsV1061(){return [...new P.ResourceCareService().forecast(App.state,52),...ehsAssuranceItemsV1061()]}
function assuranceRiskV1061(x){return x.daysToDue<0||x.status==='Action required'||/Invalid|Overdue|Expired/i.test(x.status||'')}
function renderEquipmentMasterV1061(){P.ensureEnterpriseModel(App.state);App.state.settings=App.state.settings||{};const cfg=App.state.settings.resourceAssuranceNotifications||(App.state.settings.resourceAssuranceNotifications={enabled:false,amount:6,unit:'weeks'}),items=allAssuranceItemsV1061(),type=App.filters.careTypeV1061||'All',statusFilter=App.filters.careStatusV1061||'All',scope=App.filters.careScopeV1061||'All',q=String(App.filters.careSearchV1061||'').toLowerCase(),horizon=Number(App.filters.careHorizonV1061||90);let shown=items.filter(x=>(type==='All'||(type==='Risks / Actions'?assuranceRiskV1061(x):x.type===type))&&(statusFilter==='All'||(statusFilter==='Overdue'?x.daysToDue<0:statusFilter==='Due30'?x.daysToDue>=0&&x.daysToDue<=30:statusFilter==='Due60'?x.daysToDue>=0&&x.daysToDue<=60:statusFilter==='Due90'?x.daysToDue>=0&&x.daysToDue<=90:statusFilter==='Scheduled'?!!x.scheduledStart:true))&&(scope==='All'||x.targetId===scope||x.equipmentId===scope)&&(!q||`${x.targetName} ${x.type} ${x.targetId||''} ${x.capability||''}`.toLowerCase().includes(q))&&(x.daysToDue<=horizon||x.daysToDue<0));const tile=(label,count)=>`<button type="button" class="card metric assurance-filter-tile ${type===label?'active':''}" data-v1061-care-type="${esc(label)}"><div class="label">${esc(label)}</div><div class="value">${count}</div><div class="trend">${label==='All'?'All assurance records':'Filter this view'}</div></button>`;const counts={All:items.length,Calibration:items.filter(x=>x.type==='Calibration').length,Maintenance:items.filter(x=>x.type==='Maintenance').length,Training:items.filter(x=>x.type==='Training').length,EHS:items.filter(x=>x.type==='EHS').length,'Risks / Actions':items.filter(assuranceRiskV1061).length};const equipmentOpts=(App.state.equipment||[]).slice().sort((a,b)=>a.name.localeCompare(b.name)).map(e=>`<option value="${esc(e.id)}" ${scope===e.id?'selected':''}>${esc(e.id)} · ${esc(e.name)} · ${esc(e.capability||'')}</option>`).join('');const rows=shown.sort((a,b)=>a.daysToDue-b.daysToDue).map(x=>`<tr><td><strong>${esc(x.targetName)}</strong><small>${esc(x.targetId||x.itemKey||x.id)}</small></td><td>${esc(x.type)}</td><td>${P.formatDate(x.dueDate)}</td><td><strong>${Number(x.daysToDue)}</strong></td><td>${status(x.daysToDue<0?'Overdue':x.status||'Due')}</td><td>${x.type==='EHS'?btn('Open dossier',`data-v1061-open-ehs="${esc(x.sourceKind)}|${esc(x.targetId)}"`,'button tiny secondary'):btn(x.scheduledStart?'Change':'Review & schedule',`data-schedule-care="${esc(x.id)}"`,'button tiny primary')}</td></tr>`).join('');return pageHeader('Resource Assurance','One readiness workspace for calibration, maintenance, training and EHS — with forward-looking expiry control.',`${btn('Create assurance report','data-v1061-assurance-report','button primary')}`)+`<div class="grid cols-6 assurance-tiles">${tile('All',counts.All)}${tile('Calibration',counts.Calibration)}${tile('Maintenance',counts.Maintenance)}${tile('Training',counts.Training)}${tile('EHS',counts.EHS)}${tile('Risks / Actions',counts['Risks / Actions'])}</div><div style="height:14px"></div><div class="card resource-assurance-controls"><div class="care-filter-grid"><label>Search<input id="v1061CareSearch" type="search" value="${esc(App.filters.careSearchV1061||'')}" placeholder="Equipment, person, process, test…"></label><label>Upcoming horizon<select id="v1061CareHorizon">${[30,60,90,180,365].map(n=>`<option value="${n}" ${horizon===n?'selected':''}>${n} days</option>`).join('')}</select></label><label>Status<select id="v1061CareStatus"><option>All</option><option value="Overdue" ${statusFilter==='Overdue'?'selected':''}>Overdue</option><option value="Due30" ${statusFilter==='Due30'?'selected':''}>Due ≤30 d</option><option value="Due60" ${statusFilter==='Due60'?'selected':''}>Due ≤60 d</option><option value="Due90" ${statusFilter==='Due90'?'selected':''}>Due ≤90 d</option><option value="Scheduled" ${statusFilter==='Scheduled'?'selected':''}>Scheduled</option></select></label><label>Lab scope<select id="v1061CareScope"><option value="All">All resources</option>${equipmentOpts}</select></label></div><div class="notification-rule"><div><strong>Expiry notification rule</strong><small>Notify in LabOS when any calibration, maintenance, training or EHS item is due within your chosen lead time.</small></div><label><input id="v1061NotifyEnabled" type="checkbox" ${cfg.enabled?'checked':''}> Enabled</label><input id="v1061NotifyAmount" type="number" min="1" max="52" value="${Number(cfg.amount||6)}"><select id="v1061NotifyUnit"><option value="weeks" ${cfg.unit==='weeks'?'selected':''}>weeks</option><option value="months" ${cfg.unit==='months'?'selected':''}>months</option></select>${btn('Save','data-v1061-save-notify','button small secondary')}</div></div><div style="height:14px"></div><div class="card"><div class="section-title-row"><div><span class="eyebrow">ASSURANCE REGISTER</span><h2>${esc(type)} · ${shown.length} item${shown.length===1?'':'s'}</h2></div><div class="route-toolbar">${btn('30 d','data-v1061-horizon="30"','button tiny secondary')}${btn('60 d','data-v1061-horizon="60"','button tiny secondary')}${btn('90 d','data-v1061-horizon="90"','button tiny secondary')}</div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Resource / scope</th><th>Assurance</th><th>Due / review</th><th>Days</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows||'<tr><td colspan="6">No assurance items match these filters.</td></tr>'}</tbody></table></div></div><div style="height:14px"></div><details class="card fold"><summary>Lab scope · individual equipment</summary><div class="scope-equipment-grid">${(App.state.equipment||[]).map(e=>`<button type="button" class="scope-equipment-item" data-v1061-scope-equipment="${esc(e.id)}"><strong>${esc(e.id)} · ${esc(e.name)}</strong><small>${esc(e.capability||'No capability')} · Cal ${P.formatDate(e.calibrationDue)} · Maint ${P.formatDate(e.maintenanceDue||e.nextMaintenance)}</small></button>`).join('')}</div></details>`}
renderEquipmentMaster=renderEquipmentMasterV1061;

function assuranceReportModalV1061(){const items=allAssuranceItemsV1061();openModal('Resource Assurance report',`<div class="callout"><strong>Build the report you need.</strong><p>Select any assurance domains and a forward horizon. The report includes overdue plus upcoming 30/60/90-day deviations.</p></div><div class="assurance-report-options">${['Calibration','Maintenance','Training','EHS'].map(x=>`<label><input type="checkbox" data-v1061-report-type="${x}" checked> ${x}</label>`).join('')}</div><div class="field"><label>Forward horizon</label><select id="v1061ReportHorizon"><option value="30">30 days</option><option value="60">60 days</option><option value="90" selected>90 days</option><option value="180">180 days</option><option value="365">365 days</option></select></div><div id="v1061ReportPreview"></div>`,`${btn('Close','data-modal-close','button')}${btn('Refresh preview','data-v1061-report-refresh','button secondary')}${btn('Print / save PDF','data-v1061-report-print','button primary')}`,true);const draw=()=>{const types=new Set($$('[data-v1061-report-type]:checked').map(x=>x.dataset.v1061ReportType)),h=Number($('#v1061ReportHorizon').value),rows=items.filter(x=>types.has(x.type)&&(x.daysToDue<=h||x.daysToDue<0)).sort((a,b)=>a.daysToDue-b.daysToDue);const band=n=>n<0?'OVERDUE':n<=30?'0–30 d':n<=60?'31–60 d':n<=90?'61–90 d':'>90 d';$('#v1061ReportPreview').innerHTML=`<div class="grid cols-4">${metric('Overdue',rows.filter(x=>x.daysToDue<0).length)+metric('≤30 d',rows.filter(x=>x.daysToDue>=0&&x.daysToDue<=30).length)+metric('31–60 d',rows.filter(x=>x.daysToDue>30&&x.daysToDue<=60).length)+metric('61–90 d',rows.filter(x=>x.daysToDue>60&&x.daysToDue<=90).length)}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Band</th><th>Type</th><th>Item</th><th>Due</th><th>Days</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${band(x.daysToDue)}</td><td>${esc(x.type)}</td><td>${esc(x.targetName)}</td><td>${P.formatDate(x.dueDate)}</td><td>${x.daysToDue}</td><td>${esc(x.status||'Due')}</td></tr>`).join('')||'<tr><td colspan="6">No items in scope.</td></tr>'}</tbody></table></div>`};draw();$('[data-v1061-report-refresh]').onclick=draw;$('[data-v1061-report-print]').onclick=()=>window.print()}

function defaultRationaleV1061(kind,obj){if(kind==='lesson')return `System proposal based on observed evidence: ${obj?.observation||obj?.recommendation||'recorded build evidence'}. Review confirms whether this learning should be retained for future work.`;if(kind==='grr')return `Decision based on the calculated Gage R&R result, study design and linked measurement use. ${obj?.systemRecommendation?`System recommendation: ${obj.systemRecommendation}.`:''}`;if(kind==='replan')return `Review triggered because the proposed change affects the current constrained plan. Accept only if the shown delivery and resource impacts are acceptable.`;return 'Review triggered by the evidence and constraint that opened this proposal. Confirm the decision and retain any necessary qualification.'}
const _lessonDecisionModalV1061=lessonDecisionModal;
lessonDecisionModal=function(requestId,proposalId,decision){_lessonDecisionModalV1061(requestId,proposalId,decision);setTimeout(()=>{const p=autoLessonProposals(requestById(requestId)).find(x=>x.proposalId===proposalId),el=$('#lessonRationale');if(el&&!el.value)el.value=defaultRationaleV1061('lesson',p)},20)};
const _approveGageRRV1061=approveGageRR;
approveGageRR=function(id){_approveGageRRV1061(id);setTimeout(()=>{const s=(App.state.gageRRStudies||[]).find(x=>x.id===id),el=$('#grrApproveNote')||$('#grrDecisionNote');if(el&&!el.value)el.value=defaultRationaleV1061('grr',s)},20)};

const _fiveSAuditModalV1061=fiveSAuditModal;
fiveSAuditModal=function(zoneId){_fiveSAuditModalV1061(zoneId);setTimeout(()=>{const modal=$('#modalRoot .modal'),callout=modal?.querySelector('.callout');if(!modal||!callout||modal.querySelector('.five-s-examples-v1061'))return;callout.insertAdjacentHTML('afterend',`<div class="five-s-examples-v1061"><div class="five-s-example good"><div class="five-s-example-art" aria-label="Good 5S example"><svg viewBox="0 0 260 110" role="img"><rect x="6" y="8" width="248" height="94" rx="8" fill="#eef9f5" stroke="#8ccbb7"/><rect x="24" y="24" width="58" height="24" rx="4" fill="#fff" stroke="#4a8"/><rect x="101" y="24" width="58" height="24" rx="4" fill="#fff" stroke="#4a8"/><rect x="178" y="24" width="58" height="24" rx="4" fill="#fff" stroke="#4a8"/><path d="M26 70h208" stroke="#4a8" stroke-width="3" stroke-dasharray="8 6"/><circle cx="54" cy="70" r="9" fill="#fff" stroke="#4a8"/><circle cx="130" cy="70" r="9" fill="#fff" stroke="#4a8"/><circle cx="206" cy="70" r="9" fill="#fff" stroke="#4a8"/></svg></div><strong>GOOD · visual standard met</strong><small>Defined locations, labels visible, access clear, no unidentified material, clean work surface and abnormalities obvious.</small></div><div class="five-s-example bad"><div class="five-s-example-art" aria-label="Bad 5S example"><svg viewBox="0 0 260 110" role="img"><rect x="6" y="8" width="248" height="94" rx="8" fill="#fff4f3" stroke="#e1a09a"/><rect x="31" y="27" width="76" height="22" transform="rotate(-8 31 27)" fill="#fff" stroke="#c66"/><rect x="132" y="21" width="54" height="27" transform="rotate(11 132 21)" fill="#fff" stroke="#c66"/><circle cx="82" cy="76" r="12" fill="#fff" stroke="#c66"/><rect x="151" y="65" width="75" height="20" transform="rotate(-10 151 65)" fill="#fff" stroke="#c66"/><path d="M26 91L232 58" stroke="#c66" stroke-width="2"/></svg></div><strong>BAD · action required</strong><small>Mixed/unidentified items, poor location control, clutter or obstruction, cleaning gaps, missing visual controls or abnormal condition not contained.</small></div></div><div class="callout compact"><strong>What is expected</strong><p>Score what is physically present now. A 4 means the defined workplace standard is met without explanation; a 5 means it is consistently sustained and abnormal conditions are immediately visible. Any score below 4 must describe the observed gap so the owner can close it.</p></div>`)},20)};

function installStandardsNavV1061(){if(App.currentView!=='process-library')return;const page=$('#page');if(!page||page.querySelector('.standards-tools-v1061'))return;const cards=[...page.querySelectorAll(':scope > .card, :scope > .grid > .card')];const names=[['process','Processes'],['test','Tests'],['skill','Skills'],['staff','People'],['5s','5S'],['finance','Finance']];cards.forEach(c=>{const t=(c.querySelector('h2')?.textContent||'').toLowerCase();for(const [id,key] of names)if(t.includes(key.toLowerCase())||(id==='process'&&t.includes('standard process'))||(id==='test'&&t.includes('standard test'))||(id==='staff'&&t.includes('people'))){c.dataset.stdSection=id;c.id=`std-${id}`;break}});const head=page.querySelector('.page-header');if(head)head.insertAdjacentHTML('afterend',`<div class="standards-tools-v1061"><input id="v1061StandardsSearch" type="search" placeholder="Search processes, tests, equipment, skills, people, EHS, 5S…"><div class="standards-chip-row">${names.map(([id,l])=>`<button type="button" class="filter-chip" data-v1061-std-jump="${id}">${l}</button>`).join('')}</div></div>`);const input=$('#v1061StandardsSearch');if(input)input.oninput=()=>{const q=input.value.trim().toLowerCase();page.querySelectorAll('.data-table tbody tr,.process-card,.card.compact').forEach(el=>{el.hidden=!!q&&!el.textContent.toLowerCase().includes(q)})}}

function installRequestsAdminV1061(){if(App.currentView!=='requests'||currentRole()!=='administrator')return;const a=$('#page .page-header .header-actions');if(a&&!a.querySelector('[data-v1061-archive-manager]'))a.insertAdjacentHTML('beforeend',btn('Archive manager', 'data-v1061-archive-manager','button secondary'));}

function installManagementActionLabelsV1061(){if(App.currentView!=='management')return;$$('.kpi-signal').forEach(x=>{if(x.querySelector('[data-resolve-action],[data-resolve-five-s-action],[data-care-item-key]'))return;const nodes=[...x.querySelectorAll('b,strong,span')].filter(n=>/Resolve\s*→?/i.test(n.textContent||''));nodes.forEach(n=>n.textContent='Open affected items →')})}

function planningVacationPreviewNoteV1061(){const modal=$('#modalRoot .modal');if(!modal)return;const txt=modal.textContent||'';if(!/Vacation|Staff absence/i.test(txt)||modal.querySelector('.vacation-explain-v1061'))return;const body=modal.querySelector('.resolution-focus,.callout');if(body)body.insertAdjacentHTML('afterend',`<div class="callout info vacation-explain-v1061"><strong>This is an impact preview — the vacation is not saved yet.</strong><p>LabOS is showing what must move because this person is unavailable. Nothing changes until you accept the proposal. Accepting it records the vacation as a capacity constraint, replans affected future work, and retains any commitment movement for review.</p></div>`);const accept=[...modal.querySelectorAll('button')].find(b=>/Accept|Apply|Commit/i.test(b.textContent||''));if(accept)accept.textContent='Add vacation & apply shown replan'}
const _showPlanProposalV1061=showPlanProposal;
showPlanProposal=function(args){_showPlanProposalV1061(args);setTimeout(()=>{const el=$('#planProposalNote');if(el&&!el.value){const ctx=args?.contextEvent;el.value=ctx?`Proposal review triggered by ${ctx.type}: ${ctx.reason}. Review the shown resource and delivery impacts before accepting.`:defaultRationaleV1061('replan',args)}} ,20)};

const _previewPlanningSituationChangeV1061=previewPlanningSituationChange;
previewPlanningSituationChange=function(draft,opts={}){_previewPlanningSituationChangeV1061(draft,opts);if(/Vacation|Staff absence/.test(draft?.type||''))setTimeout(planningVacationPreviewNoteV1061,30)};

function overlapV1061(a,b,c,d){return new Date(a)<new Date(d)&&new Date(c)<new Date(b)}
function bookingSlotFeasibleV1061(booking,start,ignoreIds=new Set()){const st=new Date(start),en=new Date(st.getTime()+Number(booking.durationHours||1)*3600000);if([0,6].includes(st.getDay())||st.getHours()<8||en.getHours()>17||(en.getHours()===17&&en.getMinutes()>0))return false;for(const b of App.state.bookings||[]){if(ignoreIds.has(b.id)||b.id===booking.id)continue;if((booking.equipmentId&&b.equipmentId===booking.equipmentId)||(booking.staffId&&b.staffId===booking.staffId)){if(overlapV1061(st,en,b.start,b.end))return false}}for(const c of App.state.resourceCareBookings||[]){if(c.status!=='Scheduled')continue;if((booking.equipmentId&&c.equipmentId===booking.equipmentId)||(booking.staffId&&c.staffId===booking.staffId)){if(overlapV1061(st,en,c.start,c.end))return false}}for(const ev of App.state.planningEvents||[]){if(ev.active===false)continue;const affects=ev.scope==='lab'||(ev.scope==='staff'&&ev.staffId===booking.staffId)||(ev.scope==='equipment'&&ev.equipmentId===booking.equipmentId);if(affects&&overlapV1061(st,en,ev.start,ev.end))return false}return true}
function feasibleSlotsV1061(booking,limit=24,fromDate=null,ignoreIds=new Set()){const out=[],base=fromDate?new Date(fromDate):new Date();base.setMinutes(0,0,0);if(base.getHours()<8)base.setHours(8);for(let i=0;i<24*100&&out.length<limit;i++){const d=new Date(base.getTime()+i*3600000);if(d.getHours()<8||d.getHours()>16)continue;if(bookingSlotFeasibleV1061(booking,d,ignoreIds))out.push(d.toISOString())}return out}
