  const builds=[...new Set(changes.map(x=>x.requestId).filter(Boolean))],equipMoves=changes.filter(x=>/equipment/i.test(String(x.type||''))).length,timeMoves=changes.filter(x=>/start|end|time|timing|slot|forecast/i.test(String(x.type||''))).length;
  const body=modal.querySelector('.resolution-focus,.callout');
