 const stateFor=r=>{const m=P.commitmentMetrics(r),forecast=r.forecastDate,base=m.current||m.original||r.requiredDate;if(!forecast)return 'neutral';const vsRequired=r.requiredDate?P.daysBetween(r.requiredDate,forecast):0,vsCommit=base?P.daysBetween(base,forecast):0;if(vsRequired>0||vsCommit>2)return 'bad';if(vsCommit>0||vsRequired===0)return 'warn';return 'good'};
