    dev.resolutionEvidence=dev.resolutionEvidence||{};for(const [k,label] of PROCESS_DEV_GATES){if(k==='release'||k==='approval')continue;dev.gates[k]=true;dev.resolutionEvidence[k]={evidence:`Completed in consolidated method sheet · ${label}`,completedBy:App.state.identity.name,completedAt:P.now()}};
