// A 5S action must resolve inside the 5S control itself, never through a generic build section.
resolve5SActionModal=function(actionId){
  const a=(App.state.actions||[]).find(x=>x.id===actionId),z=(App.state.fiveSZones||[]).find(x=>x.id===a?.fiveSAction?.zoneId),src=(App.state.fiveSAudits||[]).find(x=>x.id===a?.fiveSAction?.auditId);if(!a||!z)return;
  const pillar=a.fiveSAction.pillar,score=Number(src?.scores?.[pillar]||0),obs=src?.evidence||a.why||'';
  openModal(`Resolve 5S · ${z.name} · ${a.fiveSAction.pillarLabel}`,`<div class="resolution-focus"><span class="eyebrow">EXACT 5S GAP</span><h2>${esc(a.fiveSAction.pillarLabel)} · ${score||'—'}/5</h2><p>${esc(obs)}</p><div class="score-row"><span>Zone</span><strong>${esc(z.name)} · ${esc(z.area)}</strong></div><div class="score-row"><span>Accountable owner</span><strong>${esc(z.owner)}</strong></div></div><div class="resolution-steps compact"><div class="resolution-step complete"><span class="resolution-index">✓</span><div><strong>Gap identified</strong><small>The original 5S check remains in history.</small></div></div><div class="resolution-step current"><span class="resolution-index">2</span><div><strong>Correct the physical condition</strong><small>Restore the actual workplace standard for this criterion.</small></div></div><div class="resolution-step pending"><span class="resolution-index">3</span><div><strong>Recheck this criterion</strong><small>A score of 4 or 5 closes this action; 1–3 keeps it open.</small></div></div></div><div class="form-grid"><div class="field full"><label>Correction performed <b>required</b></label><textarea id="v1075FiveSCorrection" placeholder="What was physically corrected in this zone?"></textarea></div><div class="field"><label>Recheck score</label><select id="v1075FiveSScore">${[5,4,3,2,1].map(n=>`<option value="${n}" ${n===4?'selected':''}>${n} · ${n>=4?'Meets standard':n===3?'Improvement still required':'Gap remains'}</option>`).join('')}</select></div><div class="field"><label>Verification evidence <b>required</b></label><input id="v1075FiveSEvidence" placeholder="Observation / photo / record reference"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Record correction & recheck','data-v1075-close-5s','button next-action')}`,true);
  setTimeout(()=>{const b=$('[data-v1075-close-5s]');if(!b)return;b.onclick=async()=>{const restoreScrollY=window.scrollY,correction=$('#v1075FiveSCorrection')?.value.trim()||'',evidence=$('#v1075FiveSEvidence')?.value.trim()||'',newScore=Number($('#v1075FiveSScore')?.value||0);if(!correction||!evidence){toast('Correction and verification evidence are required.',true);return}const scores={...(src?.scores||{})};scores[pillar]=newScore;const values=Object.values(scores).map(Number).filter(Number.isFinite),audit={id:P.uid('5S-AUDIT'),zoneId:z.id,date:P.now(),auditor:App.state.identity.name,scores,evidence:`Correction: ${correction}. Verification: ${evidence}`,average:values.length?values.reduce((n,x)=>n+x,0)/values.length:newScore,resolutionOfActionId:a.id};App.state.fiveSAudits.push(audit);if(newScore>=4){a.status='Resolved';a.resolvedAt=P.now();a.resolutionEvidence=audit.evidence;P.audit(App.state,'5S action corrected, rechecked and closed','Action',a.id,`${score}/5`,`${newScore}/5`,audit.evidence);}else{a.status='Open';a.severity=newScore<=2?'bad':'warn';a.why=`Recheck remains below standard at ${newScore}/5. ${audit.evidence}`;P.audit(App.state,'5S action rechecked; gap remains','Action',a.id,`${score}/5`,`${newScore}/5`,audit.evidence);}await persist();closeModal();render();requestAnimationFrame(()=>window.scrollTo({top:restoreScrollY,left:0,behavior:'instant'}));toast(newScore>=4?'5S action closed after successful recheck.':'5S action remains open because the recheck is below 4/5.',newScore<4);};},0);
};
const _resolveActionModalV1075Base=resolveActionModal;
resolveActionModal=function(actionId){const a=(App.state.actions||[]).find(x=>x.id===actionId);if(a?.fiveSAction)return resolve5SActionModal(actionId);return _resolveActionModalV1075Base(actionId)};

function v1075CareForecast(){return new P.ResourceCareService().forecast(App.state,52).filter(x=>['Calibration','Maintenance','Training'].includes(x.type))}
function v1075DueIds(days){return v1075CareForecast().filter(x=>!x.scheduledStart&&Number(x.daysToDue)<=Number(days)).map(x=>x.id).filter(Boolean)}
function v1075AssuranceSection(){
  const rows=resourceAssuranceSetupRowsV1064(),type=App.filters.labAssuranceTypeV1075||'All',horizon=Number(App.filters.labAssuranceHorizonV1075||90),q=String(App.filters.labAssuranceSearchV1075||'').trim().toLowerCase(),visible=rows.filter(x=>(type==='All'||x.type===type)&&(!q||`${x.resourceId} ${x.resource} ${x.type} ${x.skillName||''}`.toLowerCase().includes(q))&&(x.active||x.planned||Number(x.daysToDue)<=horizon));
  const due=n=>rows.filter(x=>!x.planned&&Number(x.daysToDue)<=n).length,overdue=rows.filter(x=>!x.planned&&Number(x.daysToDue)<0).length,planned=rows.filter(x=>x.planned).length,active=rows.filter(x=>x.active).length;
  const body=visible.slice(0,60).map(x=>{const impacts=[...(x.affectedRequestIds||[]),x.nextUseRequestId].filter(Boolean),itemId=x.id||x.itemKey;return `<tr data-v1075-searchable><td>${!x.planned&&itemId?`<input type="checkbox" data-care-select="${esc(itemId)}" aria-label="Select ${esc(x.resource)} ${esc(x.type)}">`:''}</td><td><strong>${esc(x.resourceId)} · ${esc(x.resource)}</strong><small>${esc((App.state.equipment||[]).find(e=>e.id===x.equipmentId)?.capability||x.skillName||'')}</small></td><td><strong>${esc(x.type)}</strong><small>${x.daysToDue<0?`${Math.abs(Number(x.daysToDue))} d overdue`:`Due in ${Number(x.daysToDue)} d`}</small></td><td>${P.formatDate(x.dueDate)}</td><td>${x.start?`${P.formatDateTime(x.start)} → ${P.formatDateTime(x.end)}`:'Not yet reserved'}</td><td>${impacts.length?`<strong>${esc([...new Set(impacts)].join(', '))}</strong><small>Affected / next planned build</small>`:'<span class="subtle">No current build impact</span>'}</td><td>${x.active?'<span class="status bad">Pulled now</span>':x.planned?'<span class="status info">Scheduled</span>':x.daysToDue<0?'<span class="status bad">Overdue</span>':x.daysToDue<=30?'<span class="status warn">Due soon</span>':'<span class="status neutral">Upcoming</span>'}</td><td>${itemId?btn(x.planned?'Review':'Schedule',`data-schedule-care="${esc(itemId)}"`,'button tiny secondary'):''}</td></tr>`}).join('');
  return `<section id="std-assurance" class="card lab-master-section-v1075" data-std-section="assurance"><div class="section-title-row"><div><span class="eyebrow">RESOURCE ASSURANCE & AVAILABILITY</span><h2>Keep equipment and people ready without surprising the build plan</h2><p class="subtle">One place for calibration, maintenance and training. Scheduled work shows exactly when a resource is pulled from service and which build is affected next.</p></div><span class="pill">${rows.length} assurance items</span></div><div class="assurance-summary-v1075"><div class="bad"><span>Overdue</span><strong>${overdue}</strong></div><div class="warn"><span>Due ≤30 d</span><strong>${due(30)}</strong></div><div><span>Scheduled pulls</span><strong>${planned}</strong></div><div><span>Pulled now</span><strong>${active}</strong></div></div><div class="assurance-command-v1075"><div><strong>Plan upcoming assurance work</strong><small>Review all currently unscheduled calibration, maintenance and training due within the selected window.</small></div><div class="route-toolbar">${btn(`Plan all due ≤30 d (${due(30)})`,'data-v1075-bulk-care="30"','button small next-action')}${btn(`≤60 d (${due(60)})`,'data-v1075-bulk-care="60"','button small secondary')}${btn(`≤90 d (${due(90)})`,'data-v1075-bulk-care="90"','button small secondary')}</div></div><div class="care-filter-grid lab-master-filters-v1075"><label>Search resources<input id="v1075AssuranceSearch" type="search" value="${esc(App.filters.labAssuranceSearchV1075||'')}" placeholder="Equipment, person, capability…"></label><label>Activity<select id="v1075AssuranceType">${['All','Calibration','Maintenance','Training'].map(v=>`<option value="${v}" ${type===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Show upcoming<select id="v1075AssuranceHorizon">${[30,60,90,180,365].map(n=>`<option value="${n}" ${horizon===n?'selected':''}>${n} days</option>`).join('')}</select></label><div class="route-toolbar align-end-v1075">${btn('Select visible','data-care-select-visible','button small secondary')}${btn('Clear','data-care-clear-selection','button small secondary')}${btn('Review & schedule selected','data-care-schedule-selected','button small primary')}</div></div><div class="table-wrap"><table class="data-table assurance-table-v1075"><thead><tr><th></th><th>Resource</th><th>Work</th><th>Due</th><th>Reserved out / return</th><th>Build impact / next use</th><th>Status</th><th>Action</th></tr></thead><tbody>${body||'<tr><td colspan="8">No assurance work matches these filters.</td></tr>'}</tbody></table></div></section>`;
}
