function v1078ManualTaskDefinitions(r){
  return P.planningTasksForRequest(App.state,r).map(t=>({id:t.id,name:t.name,order:t.order,kind:t.kind,subkind:t.subkind||null,definitionKey:t.definitionKey,step:t.sourceStep||null,testRequirement:t.sourceTest||null,processDevelopmentId:t.processDevelopmentId||null}));
}

function v1078ManualTaskRequirement(r,def,b=null){
  if(def.kind==='process'){const p=(App.state.processes||[]).find(x=>x.id===def.step?.processId);return {capability:p?(P.planningCapabilityForProcess?P.planningCapabilityForProcess(App.state,r,p):p.equipmentCapability):(def.step?.equipmentCapability||''),skillId:p?(P.planningSkillForProcess?P.planningSkillForProcess(p):p.competency):(def.step?.competency||def.step?.skillId||null)}}
  if(def.kind==='test'){const tr=def.testRequirement,t=(App.state.standardTests||[]).find(x=>x.id===tr?.standardTestId);return {capability:t?(P.planningCapabilityForTest?P.planningCapabilityForTest(t):t.equipmentCapability):(tr?.equipmentCapability||''),skillId:t?(P.planningSkillForTest?P.planningSkillForTest(t):t.competency):(tr?.competency||tr?.skillId||null)}}
  if(def.kind==='development'){if(def.subkind==='test-development')return {capability:'',skillId:def.testRequirement?.developmentCompetency||'COMP-03'};const dev=(App.state.processDevelopments||[]).find(x=>x.id===def.processDevelopmentId);return {capability:'',skillId:dev?.competency||'COMP-02'}}
  return {capability:'',skillId:null};
}
function v1078ManualTaskDuration(r,def,b=null){if(b?.durationHours)return Number(b.durationHours);if(def.kind==='process')return routeStepEstimateHours(r,def.step);if(def.kind==='test'){const t=(App.state.standardTests||[]).find(x=>x.id===def.testRequirement?.standardTestId);return Math.max(.25,(Number(t?.setupTime||0)+Number(t?.cycleTime||0)*(t?.basis==='Batch'?1:Number(r.quantity||1)))/60||Number(def.testRequirement?.executionEstimateHours)||1)}if(def.kind==='development'){if(def.subkind==='test-development')return Math.max(.5,Number(def.testRequirement?.developmentEstimateHours)||2);const dev=(App.state.processDevelopments||[]).find(x=>x.id===def.processDevelopmentId);return Math.max(.5,Number(dev?.planningEstimateHours)||2)}if(def.kind==='closeout')return 4;return 2}
function v1078ManualTaskRows(r){
  const defs=v1078ManualTaskDefinitions(r),existing=(App.state.bookings||[]).filter(x=>x.requestId===r.id),byStep=new Map(existing.map(b=>[b.stepId,b]));let suggested=new Map();
  if(!existing.length){try{const clone=P.deepClone(App.state);new P.PlannerService().autoPlan(clone,r.id);suggested=new Map((clone.bookings||[]).filter(b=>b.requestId===r.id).map(b=>[b.stepId,b]));}catch(_){}}
  let cursor=planningNextWorkStartV1064(new Date(Date.now()+3600000));
  return defs.map((def,i)=>{const b=byStep.get(def.id)||suggested.get(def.id)||def.bookingOnly||null,duration=v1078ManualTaskDuration(r,def,b),req=v1078ManualTaskRequirement(r,def,b);let start=b?new Date(b.start):new Date(cursor);start=planningNextWorkStartV1064(start);cursor=planningAddWorkHoursV1064(start,duration);const eqs=req.capability?(App.state.equipment||[]).filter(e=>(P.equipmentPlanningCapability?P.equipmentPlanningCapability(e):e.capability)===req.capability):[],staff=(App.state.staff||[]).filter(st=>st.available!==false&&(!req.skillId||(st.competencies||[]).includes(req.skillId)||(App.state.trainingCertificates||[]).some(c=>c.staffId===st.id&&c.skillId===req.skillId)));return {def,step:def.step||{id:def.id,name:def.name,order:def.order},index:i,duration,req,b,start,eqs,staff}});
}
function v1078ManualPlanModal(requestId){
  if(!can('plan')&&currentRole()!=='administrator'){toast('Lab Planner permission is required for manual planning.',true);return}
  const r=requestById(requestId);if(!r)return;
  const rows=v1078ManualTaskRows(r);if(!rows.length){toast('Define the route before creating a manual plan.',true);return}
  const tr=rows.map((x,i)=>{const iso=x.start.toISOString(),date=iso.slice(0,10),period=x.start.getHours()<13?'AM':'PM',eq=x.b?(x.b.equipmentId||''):(x.eqs[0]?.id||''),selectedStaff=x.b?.staffId||x.staff[0]?.id||'';return `<tr data-v1078-manual-row="${esc(x.step.id)}" data-v1078-original-start="${esc(x.b?.start||'')}"><td><strong>${x.step.order||i+1} · ${esc(x.step.name)}</strong><small>${x.req.capability?`Equipment: ${esc(x.req.capability)}`:'No fixed equipment capability'}${x.req.skillId?` · Skill: ${esc((App.state.competencies||[]).find(c=>c.id===x.req.skillId)?.name||x.req.skillId)}`:''}</small></td><td><input type="date" data-v1078-date value="${date}"></td><td><select data-v1078-period><option value="AM" ${period==='AM'?'selected':''}>Morning</option><option value="PM" ${period==='PM'?'selected':''}>Afternoon</option></select></td><td><select data-v1078-eq>${x.eqs.length?x.eqs.map(e=>`<option value="${esc(e.id)}" ${e.id===eq?'selected':''}>${esc(e.id)} · ${esc(e.name)}</option>`).join(''):'<option value="">No equipment required</option>'}</select></td><td><select data-v1078-staff>${x.staff.map(person=>`<option value="${esc(person.id)}" ${person.id===selectedStaff?'selected':''}>${esc(person.name)}</option>`).join('')}${!x.staff.length?'<option value="">Unassigned</option>':''}</select></td><td>${x.duration.toFixed(2)} h</td></tr>`}).join('');
  openModal(`Manual plan · ${r.id}`,`<div class="callout info"><strong>Manual controlled planning</strong><p>Edit the proposed date, Morning/Afternoon start, equipment and person. These become explicit constraints passed to the same solver kernel used by AUTO PLAN. The solver then fills/verifies the complete canonical task graph and rejects any overlap, invalid capability, readiness, qualification or sequence conflict.</p></div><div class="table-wrap"><table class="data-table manual-plan-table-v1078"><thead><tr><th>Route step</th><th>Date</th><th>Period</th><th>Equipment</th><th>Person</th><th>Duration</th></tr></thead><tbody>${tr}</tbody></table></div><div id="v1078ManualIssues"></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save manual plan →',`data-v1078-save-manual="${esc(r.id)}"`,'button next-action')}`,true);
}
/* REV 1.0.95: removed shadowed legacy manual-plan writer. The canonical implementation below uses planningTasksForRequest + planningTaskCoverage. */
