const _reserveAllMaterialsV1082=reserveAllMaterials;
reserveAllMaterials=async function(requestId){await _reserveAllMaterialsV1082(requestId);const r=requestById(requestId);if(r&&!P.materialPlanningAssessment(App.state,r).planningReady)setTimeout(()=>v1082MaterialResolver(requestId),60)};
