/* REV 1.0.83 — standalone laboratory stock register and physical receiving. */
function v1083LabStockSection(){
  const stock=(App.state.materials||[]).filter(m=>m.status==='Available'&&Number(m.quantity||0)>0).sort((a,b)=>String(a.partNumber||'').localeCompare(String(b.partNumber||''))||String(a.lot||'').localeCompare(String(b.lot||'')));
  const total=stock.reduce((n,m)=>n+Number(m.quantity||0),0),parts=new Set(stock.map(m=>`${m.partNumber}|${m.revision}`)).size,canReceive=can('materials:receive')||can('materials:allocate')||currentRole()==='administrator';
  const rows=stock.map(m=>`<tr><td><strong>${esc(m.partNumber)}</strong><small>Rev ${esc(m.revision||'—')} · ${esc(m.description||'—')}</small></td><td>${esc(m.lot||'—')}</td><td><strong>${esc(m.quantity)}</strong></td><td>${esc(m.supplier||'—')}</td><td>${esc(m.certificate||'—')}</td><td>${P.formatDate(m.received)}</td></tr>`).join('');
  return `<details id="std-material-stock" class="card fold lab-master-section-v1075" open><summary><span><b>Lab material stock</b><small>Physical lot inventory available for exact BOM reservation</small></span><span class="pill">${stock.length} active lot${stock.length===1?'':'s'}</span></summary><div class="section-title-row compact-heading-v1075"><div><span class="eyebrow">CONTROLLED INVENTORY</span><h3>On-hand material</h3><div class="subtle">Receive stock here before a build needs it. A build-specific material resolver can then reserve the exact part and revision.</div></div>${canReceive?btn('+ Receive lab stock','data-v1083-open-stock-receipt','button small primary'):''}</div><div class="grid cols-3"><div class="mini-kpi"><span>Available lots</span><strong>${stock.length}</strong></div><div class="mini-kpi"><span>Part / revisions</span><strong>${parts}</strong></div><div class="mini-kpi"><span>Available quantity</span><strong>${Number(total).toLocaleString()}</strong></div></div><div class="table-wrap" style="margin-top:12px"><table class="data-table"><thead><tr><th>Part / revision</th><th>Lot / batch</th><th>Available</th><th>Supplier / source</th><th>Receipt evidence</th><th>Received</th></tr></thead><tbody>${rows||'<tr><td colspan="6">No available lab stock is recorded yet. Receive the first lot to make it available for matching BOMs.</td></tr>'}</tbody></table></div></details>`;
}
function v1083StandaloneStockModal(){openModal('Receive lab material stock',`<div class="callout"><strong>Register physical inventory</strong><p>Add a received lot to the controlled lab-stock register. The lot will be available for exact part/revision reservation when a build requires it.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Part number</label><input id="v1083StandalonePart" placeholder="e.g. PWT-DRL-18-HSG"></div><div class="field"><label>Revision</label><input id="v1083StandaloneRevision" placeholder="e.g. B"></div><div class="field full"><label>Description</label><input id="v1083StandaloneDescription" placeholder="Controlled material description"></div><div class="field"><label>Actual lot / batch</label><input id="v1083StandaloneLot" placeholder="Required lot or batch"></div><div class="field"><label>Received quantity</label><input id="v1083StandaloneQty" type="number" min="0" step="any"></div><div class="field"><label>Supplier / source</label><input id="v1083StandaloneSupplier" value="Lab supplied"></div><div class="field"><label>Receipt / PO / certificate reference</label><input id="v1083StandaloneReference" placeholder="Required controlled reference"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Receive into lab stock','data-v1083-save-stock-receipt','button next-action')}`,true)}
async function v1083SaveStandaloneStock(){const part=$('#v1083StandalonePart')?.value.trim()||'',revision=$('#v1083StandaloneRevision')?.value.trim()||'',description=$('#v1083StandaloneDescription')?.value.trim()||'',lot=$('#v1083StandaloneLot')?.value.trim()||'',qty=Number($('#v1083StandaloneQty')?.value||0),supplier=$('#v1083StandaloneSupplier')?.value.trim()||'',reference=$('#v1083StandaloneReference')?.value.trim()||'';if(!part||!revision||!description||!lot||!(qty>0)||!supplier||!reference){toast('Part number, revision, description, lot, positive quantity, supplier and controlled reference are required.',true);return}App.state.materials.push({id:P.uid('MAT'),partNumber:part,revision,description,lot,quantity:qty,status:'Available',supplier,certificate:reference,specialHandling:'Standard',expiry:null,received:P.todayISO()});P.audit(App.state,'Lab material stock received','Material inventory',part,'Not in stock',`${qty} ${part} Rev ${revision} · lot ${lot} available`,`${supplier} · ${reference}`);await persist();closeModal();render();toast(`${part} Rev ${revision} · lot ${lot} is now available for exact BOM reservation.`)}
const _renderProcessLibraryV1083Base=renderProcessLibrary;
renderProcessLibrary=function(){return _renderProcessLibraryV1083Base()+v1083LabStockSection()};
function installV1083Stock(){if(App._v1083StockInstalled)return;App._v1083StockInstalled=true;document.addEventListener('click',e=>{const t=e.target.closest?.('[data-v1083-open-stock-receipt],[data-v1083-save-stock-receipt]');if(!t)return;e.preventDefault();e.stopPropagation();if(t.hasAttribute('data-v1083-open-stock-receipt'))v1083StandaloneStockModal();else v1083SaveStandaloneStock()},true)}

/* REV 1.0.86 — first-class Materials & Inventory workspace. */
function materialExpiryStateV1086(m){if(!m.expiry)return {label:'No expiry',cls:'neutral'};const days=P.daysBetween(P.todayISO(),m.expiry);return days<0?{label:'Expired',cls:'bad'}:days<=30?{label:`${days} d remaining`,cls:'warn'}:{label:P.formatDate(m.expiry),cls:'good'}}
function renderMaterialInventoryV1086(){
  const all=[...(App.state.materials||[])],alloc=App.state.allocations||[],available=all.filter(m=>m.status==='Available'&&Number(m.quantity||0)>0),reserved=alloc.filter(a=>a.status==='Reserved').reduce((n,a)=>n+Number(a.qty||0),0),issued=alloc.filter(a=>a.status==='Issued').reduce((n,a)=>n+Number(a.qty||0),0),expiring=available.filter(m=>m.expiry&&P.daysBetween(P.todayISO(),m.expiry)<=30).length,canReceive=can('materials:receive')||can('materials:allocate')||currentRole()==='administrator';
  const rows=all.sort((a,b)=>String(a.partNumber||'').localeCompare(String(b.partNumber||''))||String(a.lot||'').localeCompare(String(b.lot||''))).map(m=>{const ex=materialExpiryStateV1086(m),used=alloc.filter(a=>a.materialId===m.id),reservedQty=used.filter(a=>a.status==='Reserved').reduce((n,a)=>n+Number(a.qty||0),0),issuedQty=used.filter(a=>a.status==='Issued').reduce((n,a)=>n+Number(a.qty||0),0),search=[m.partNumber,m.revision,m.description,m.lot,m.supplier,m.storageLocation,m.certificate,m.status].join(' ').toLowerCase();return `<tr data-v1086-stock-row data-search="${esc(search)}"><td><strong>${esc(m.partNumber||'—')}</strong><small>${esc(m.description||'—')}</small></td><td><strong>${esc(m.revision||'—')}</strong></td><td>${esc(m.lot||'—')}</td><td><strong>${esc(m.quantity||0)}</strong> ${esc(m.unit||'')}</td><td>${esc(m.storageLocation||'Not set')}</td><td>${status(ex.label)}</td><td><span class="status ${reservedQty?'warn':'neutral'}">${reservedQty} reserved</span><small>${issuedQty} issued</small></td><td><strong>${esc(m.supplier||'—')}</strong><small>${esc(m.certificate||'No reference')}</small></td></tr>`}).join('');
  return pageHeader('Materials & Inventory','Receive, locate and trace physical lab stock before it is reserved to a build.',canReceive?btn('+ Receive lab stock','data-v1083-open-stock-receipt','button primary'):'')+`<div class="grid cols-4 material-kpis-v1086">${metric('Available lots',available.length)+metric('Available quantity',available.reduce((n,m)=>n+Number(m.quantity||0),0))+metric('Reserved quantity',reserved)+metric('Expiry attention',expiring,expiring?'Review expiring / expired lots':'No expiry alerts',expiring?'warn':'good')}</div><div class="card material-register-v1086"><div class="section-title-row"><div><span class="eyebrow">CONTROLLED LOT REGISTER</span><h2>Laboratory material stock</h2><div class="subtle">Exact part and revision matching prevents substitution. Receipt evidence and allocation state remain visible together.</div></div><span class="pill">${issued} issued historically</span></div><div class="material-register-tools-v1086"><input id="v1086StockSearch" type="search" placeholder="Search part, revision, lot, supplier, location or reference…" aria-label="Search material inventory"><span id="v1086StockCount">${all.length} lot${all.length===1?'':'s'}</span></div><div class="table-wrap"><table class="data-table material-register-table-v1086"><thead><tr><th>Part / material</th><th>Rev</th><th>Lot / batch</th><th>Available</th><th>Location</th><th>Expiry</th><th>Allocation</th><th>Source / evidence</th></tr></thead><tbody>${rows||'<tr><td colspan="8">No material lots are recorded. Use Receive lab stock to create the first controlled receipt.</td></tr>'}</tbody></table></div></div>`;
}
function v1086StockReceiptModal(){openModal('Receive lab material stock',`<div class="callout"><strong>Create a controlled physical receipt</strong><p>The lot becomes available to every build with the exact same part number and revision. Required fields protect inventory identity and traceability.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Part number</label><input id="v1083StandalonePart" placeholder="e.g. PWT-DRL-18-HSG"></div><div class="field"><label>Revision</label><input id="v1083StandaloneRevision" placeholder="e.g. B"></div><div class="field full"><label>Description</label><input id="v1083StandaloneDescription" placeholder="Controlled material description"></div><div class="field"><label>Actual lot / batch</label><input id="v1083StandaloneLot" placeholder="Required lot or batch"></div><div class="field"><label>Received quantity</label><input id="v1083StandaloneQty" type="number" min="0" step="any"></div><div class="field"><label>Unit</label><input id="v1086StandaloneUnit" value="pcs"></div><div class="field"><label>Storage location</label><input id="v1086StandaloneLocation" placeholder="e.g. Stores A · Bin 04"></div><div class="field"><label>Supplier / source</label><input id="v1083StandaloneSupplier" value="Lab supplied"></div><div class="field"><label>Receipt / PO / certificate reference</label><input id="v1083StandaloneReference" placeholder="Required controlled reference"></div><div class="field"><label>Expiry / retest date</label><input id="v1086StandaloneExpiry" type="date"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Receive into inventory','data-v1083-save-stock-receipt','button next-action')}`,true)}
async function v1086SaveStandaloneStock(){const part=$('#v1083StandalonePart')?.value.trim()||'',revision=$('#v1083StandaloneRevision')?.value.trim()||'',description=$('#v1083StandaloneDescription')?.value.trim()||'',lot=$('#v1083StandaloneLot')?.value.trim()||'',qty=Number($('#v1083StandaloneQty')?.value||0),unit=$('#v1086StandaloneUnit')?.value.trim()||'pcs',storageLocation=$('#v1086StandaloneLocation')?.value.trim()||'',supplier=$('#v1083StandaloneSupplier')?.value.trim()||'',reference=$('#v1083StandaloneReference')?.value.trim()||'',expiry=$('#v1086StandaloneExpiry')?.value||null;if(!part||!revision||!description||!lot||!(qty>0)||!storageLocation||!supplier||!reference){toast('Part, revision, description, lot, positive quantity, location, supplier and controlled reference are required.',true);return}if(expiry&&expiry<P.todayISO()){toast('Expiry/retest date cannot be before the receipt date.',true);return}App.state.materials.push({id:P.uid('MAT'),partNumber:part,revision,description,lot,quantity:qty,unit,status:'Available',storageLocation,supplier,certificate:reference,specialHandling:'Standard',expiry,received:P.todayISO()});P.audit(App.state,'Lab material stock received','Material inventory',part,'Not in stock',`${qty} ${unit} · ${part} Rev ${revision} · lot ${lot}`,`${storageLocation} · ${supplier} · ${reference}${expiry?` · expiry ${expiry}`:''}`);await persist();closeModal();render();toast(`${part} Rev ${revision} · lot ${lot} is available in ${storageLocation}.`)}
v1083StandaloneStockModal=v1086StockReceiptModal;v1083SaveStandaloneStock=v1086SaveStandaloneStock;
const _renderNavV1086Base=renderNav;
renderNav=function(){_renderNavV1086Base();if(['engineering_requester','auditor'].includes(currentRole()))return;const existing=document.querySelector('[data-nav="materials"]');if(existing)return;const anchor=document.querySelector('[data-nav="products"]')||document.querySelector('[data-nav="process-library"]');if(!anchor)return;const b=document.createElement('button');b.className=`nav-link ${App.currentView==='materials'?'active':''}`;b.dataset.nav='materials';b.innerHTML='<span>Materials & Inventory</span>';anchor.insertAdjacentElement('afterend',b)};
function installV1086Inventory(){if(App._v1086InventoryInstalled)return;App._v1086InventoryInstalled=true;document.addEventListener('input',e=>{if(e.target?.id!=='v1086StockSearch')return;const q=e.target.value.trim().toLowerCase(),rows=$$('[data-v1086-stock-row]');let visible=0;rows.forEach(row=>{row.hidden=!!q&&!row.dataset.search.includes(q);if(!row.hidden)visible++});const count=$('#v1086StockCount');if(count)count.textContent=`${visible} lot${visible===1?'':'s'} shown`})}

/* REV 1.0.87 — decision-first prototype flow, planning cockpit and KPI hierarchy. */
function enhancePrototypeFlowV1087(){if(App.currentView!=='workspace'||!App.workspaceId||$('#workspaceCommandV1087'))return;const r=requestById(App.workspaceId);if(!r)return;const steps=buildGuidedSteps(r),done=steps.filter(s=>s.done).length,blocked=steps.filter(s=>s.state==='blocked'),current=steps.find(s=>['blocked','current'].includes(s.state))||steps.find(s=>!s.done)||steps.at(-1),pct=Math.round(100*done/Math.max(1,steps.length)),mat=P.materialPlanningAssessment(App.state,r),commit=P.commitmentMetrics(r),owner=current?.owner||r.owner||'Unassigned';const el=document.createElement('section');el.id='workspaceCommandV1087';el.className=`workspace-command-v1087 ${blocked.length?'has-blocker':done===steps.length?'complete':'active'}`;el.innerHTML=`<div class="workspace-command-progress-v1087"><div><span class="eyebrow">PROTOTYPE BUILD CONTROL</span><strong>${done}/${steps.length} steps complete</strong></div><span>${pct}%</span><div class="workspace-progress-track-v1087"><i style="width:${pct}%"></i></div></div><div class="workspace-command-current-v1087"><span>${blocked.length?'CURRENT BLOCKER':'CURRENT CONTROLLED STEP'}</span><strong>${esc(current?.title||'Workflow complete')}</strong><small>${current?.done?'All required evidence is complete.':`Owner: ${esc(owner)} · ${esc(current?.next||'Complete the required evidence below.')}`}</small></div><div class="workspace-command-facts-v1087"><div><span>Material</span><b class="${mat.buildReady?'good-text':mat.planningReady?'warn-text':'bad-text'}">${mat.buildReady?'Ready':mat.planningReady?'Planned':'Blocked'}</b></div><div><span>Forecast</span><b>${P.formatDate(r.forecastDate)}</b></div><div><span>Commitment</span><b>${P.formatDate(commit.current)}</b></div></div>${current&&!current.done?btn(`${blocked.length?'Resolve':'Continue'} · ${esc(current.title)} →`,`data-workspace-tab="${esc(current.id)}"`,'button next-action workspace-command-action-v1087'):''}`;const spacer=$('.workspace-cockpit-spacer');if(spacer)spacer.insertAdjacentElement('afterend',el);else $('#page')?.prepend(el)}
function enhancePlanningCockpitV1087(){if(App.currentView!=='planning'||$('#planningDecisionV1087'))return;const open=(App.state.requests||[]).filter(r=>!['CLOSED','DELIVERED'].includes(r.status)),booked=new Set((App.state.bookings||[]).map(b=>b.requestId)),unplanned=open.filter(r=>!booked.has(r.id)).length,late=open.filter(r=>r.requiredDate&&r.forecastDate&&P.daysBetween(r.requiredDate,r.forecastDate)>0).length,pending=open.filter(r=>r.currentCommitmentDate&&r.forecastDate&&r.currentCommitmentDate!==r.forecastDate).length,gaps=open.filter(r=>{const m=P.materialPlanningAssessment(App.state,r),p=P.processPlanningAssessment(App.state,r);return !m.planningReady||!p.ready}).length,state=late||gaps?'attention':pending||unplanned?'review':'clear';const message=state==='attention'?`${late} forecast late · ${gaps} build${gaps===1?'':'s'} missing planning inputs`:state==='review'?`${pending} commitment movement${pending===1?'':'s'} · ${unplanned} unplanned build${unplanned===1?'':'s'}`:'Portfolio is feasible with no unresolved planning signal';const el=document.createElement('section');el.id='planningDecisionV1087';el.className=`planning-decision-v1087 ${state}`;el.innerHTML=`<div class="planning-decision-status-v1087"><span>${state==='clear'?'✓':state==='attention'?'!':'●'}</span><div><small>PLANNING DECISION STATUS</small><strong>${esc(message)}</strong></div></div><div class="planning-decision-facts-v1087"><span><b>${open.length}</b> open builds</span><span><b>${unplanned}</b> unplanned</span><span><b>${late}</b> forecast late</span><span><b>${pending}</b> commitment movement</span></div>${can('plan')?btn('Review & optimize portfolio →','data-plan-portfolio','button next-action'):''}`;const head=$('#page .page-header');head?.insertAdjacentElement('afterend',el)}
function enhanceKpisV1087(){if(App.currentView!=='management'||$('#kpiGuideV1087'))return;const page=$('#page'),head=page?.querySelector('.page-header');if(!head)return;const el=document.createElement('div');el.id='kpiGuideV1087';el.className='kpi-guide-v1087';el.innerHTML='<span><i class="bad"></i><b>Act now</b> Release, safety or delivery risk</span><span><i class="warn"></i><b>Watch</b> Trending away from target</span><span><i class="good"></i><b>On control</b> Within operating expectation</span><small>Click an exception or Open action to drill into the controlled source record.</small>';head.insertAdjacentElement('afterend',el);page.querySelectorAll('.kpi-pillar').forEach(x=>{x.classList.add('kpi-pillar-v1087');const text=(x.textContent||'').toLowerCase();if(/overdue|below|late|hold|gap|fail/.test(text))x.classList.add('attention-v1087')})}
function installExperienceV1087(){enhancePrototypeFlowV1087();enhancePlanningCockpitV1087();enhanceKpisV1087()}

/* REV 1.0.83 — accessible modal lifecycle.  The UI previously focused the first
   control but did not retain the trigger, trap keyboard navigation or support Escape. */
const _openModalV1083=openModal,_closeModalV1083=closeModal;
function v1083FocusableModalNodes(){return Array.from(document.querySelectorAll('#modalRoot .modal a[href],#modalRoot .modal button:not([disabled]),#modalRoot .modal input:not([disabled]),#modalRoot .modal select:not([disabled]),#modalRoot .modal textarea:not([disabled]),#modalRoot .modal [tabindex]:not([tabindex="-1"])')).filter(x=>x.offsetParent!==null)}
openModal=function(title,body,footer='',large=false){
  App.modalReturnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;
  _openModalV1083(title,body,footer,large);
  const dialog=$('#modalRoot .modal');
  if(!dialog)return;
  dialog.setAttribute('aria-labelledby','labosModalTitleV1083');
  const heading=dialog.querySelector('.modal-head h2');if(heading)heading.id='labosModalTitleV1083';
  dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const nodes=v1083FocusableModalNodes();if(!nodes.length){e.preventDefault();return}const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
};
closeModal=function(){const restore=App.modalReturnFocus;App.modalReturnFocus=null;_closeModalV1083();if(restore&&document.contains(restore))setTimeout(()=>restore.focus({preventScroll:true}),0)};
function installV1083(){if(App._v1083Installed)return;App._v1083Installed=true;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modalRoot .modal')){e.preventDefault();closeModal()}})}
const _renderV1083Base=render;
render=function(){_renderV1083Base();installV1083();installV1083Stock();installV1086Inventory();installExperienceV1087();};

/* REV 1.0.81 — one-time repair for the invalid shortcut-generated REV 1.0.79/80
   demo schedule. The repair is atomic and uses the production optimizer, so saved
   user planning events (including whole-lab closures) remain hard constraints. */
function v1081RepairLegacySeedPlanOnLoad(){
  if(!P.repairSeedPlanningIntegrityV1081)return {changed:false,reason:'repair-service-unavailable'};
  try{return P.repairSeedPlanningIntegrityV1081(App.state)}catch(err){console.error('REV 1.0.81 seed-plan repair failed',err);App.state.settings=App.state.settings||{};App.state.settings.planningNeedsReview=true;return {changed:false,reason:'exception',failed:true,error:err.message||String(err)}}
}


/* ============================================================
   LabOS REV 1.0.88 — planner fault-containment and manual-plan
   final integrity gates.
   ============================================================ */
function v1088PlanningAuditRows(state){const a=P.planningIntegrityAudit?P.planningIntegrityAudit(state):null;return a?Object.entries(a).filter(([,v])=>Array.isArray(v)).flatMap(([kind,v])=>v.map(row=>({kind,...row}))):[]}
function v1088AuditTouches(row,ids){const set=ids instanceof Set?ids:new Set(ids||[]);return [row.requestId,row.aRequestId,row.bRequestId].some(x=>x&&set.has(x))}
function v1088ValidatePlanningState(state,ids){const inv=P.validateInvariants(state),rows=v1088PlanningAuditRows(state),touch=ids?.length?rows.filter(x=>v1088AuditTouches(x,new Set(ids))):rows;return {ok:!inv.length&&!touch.length,invariants:inv,issues:touch,allIssues:rows}}

const _simulateBuildMoveV1088=simulateBuildMoveV1070;
simulateBuildMoveV1070=function(baseState,bookingId,target){const out=_simulateBuildMoveV1088(baseState,bookingId,target);if(!out?.ok)return out;const selected=(baseState.bookings||[]).find(x=>x.id===bookingId),ids=new Set([selected?.requestId,...(out.externalChanges||[]).map(x=>x.requestId)].filter(Boolean)),gate=v1088ValidatePlanningState(out.nextState,[...ids]);if(!gate.ok)return {ok:false,error:`Move rejected by final planning-integrity gate: ${gate.invariants[0]||`${gate.issues[0]?.kind}${gate.issues[0]?.stepName?` · ${gate.issues[0].stepName}`:''}`}`};return out};

const _commitMoveProposalV1088=commitMoveProposalV1070;
commitMoveProposalV1070=function(prop,rationale=''){if(!prop?.ok)return;const ids=[prop.requestId,...(prop.externalChanges||[]).map(x=>x.requestId)].filter(Boolean),gate=v1088ValidatePlanningState(prop.nextState,ids);if(!gate.ok){toast(`Move is no longer valid: ${gate.invariants[0]||gate.issues[0]?.kind||'planning integrity failure'}. Options were refreshed.`,true);const b=(App.state.bookings||[]).find(x=>x.id===prop.bookingId);if(b)planningMovePanelV1070(b);return}_commitMoveProposalV1088(prop,rationale)};

const _v1080SaveManualPlanV1088=v1080SaveManualPlan;
v1080SaveManualPlan=async function(requestId){const draft=App.manualPlanningDraftV1080,issue=$('#v1078ManualIssues');if(!draft||draft.requestId!==requestId)return;if(draft.seeded&&draft.decisions.length===0){if(issue){issue.innerHTML='<div class="callout warn"><strong>No manual decision has been made.</strong><p>The displayed scratch baseline came from AUTO-PLAN only. Choose at least one Green / Yellow / Red alternative before saving it as a manual plan, or use AUTO-PLAN directly.</p></div>';issue.scrollIntoView({behavior:'smooth',block:'center'})}return}const allIds=(draft.state.requests||[]).filter(x=>!['DELIVERED','CLOSED','RELEASED'].includes(x.status)).map(x=>x.id),changes=planProposalChanges(draft.originalState,draft.state,allIds),impacted=[...new Set([requestId,...changes.map(x=>x.requestId)].filter(Boolean))],gate=v1088ValidatePlanningState(draft.state,impacted);if(!gate.ok){if(issue){const first=gate.invariants[0]||gate.issues[0];issue.innerHTML=`<div class="callout bad"><strong>Manual plan rejected by the final end-to-end integrity gate.</strong><p>${esc(typeof first==='string'?first:`${first?.kind||'Planning integrity'}${first?.stepName?` · ${first.stepName}`:''}`)}</p><p>No live booking has changed. Refresh alternatives and resolve the highlighted conflict.</p></div>`;issue.scrollIntoView({behavior:'smooth',block:'center'})}return}return _v1080SaveManualPlanV1088(requestId)};
v1078SaveManualPlan=v1080SaveManualPlan;

