  const rows=teams.map(t=>{const members=(App.state.users||[]).filter(u=>u.teamId===t.id||t.memberUserIds?.includes(u.id));return `<tr data-v1089-team-row><td><strong>${esc(t.name)}</strong><small>${esc(t.id)}</small></td><td>${esc(t.businessUnit||'—')}</td><td>${esc(t.defaultSite||'—')}</td><td>${esc(t.teamLead||'—')}</td><td>${members.length}<small>${esc(members.map(x=>x.name).join(', ')||'No assigned users')}</small></td><td><span class="status ${t.active===false?'neutral':'good'}">${t.active===false?'Inactive':'Active'}</span></td><td>${admin?`${btn('Edit',`data-v1089-edit-team="${esc(t.id)}"`,'button tiny secondary')}${btn(t.active===false?'Activate':'Deactivate',`data-v1089-toggle-team="${esc(t.id)}"`,'button tiny '+(t.active===false?'secondary':'danger'))}`:''}</td></tr>`}).join('');
  return `<details id="config-requesting-teams-v1089" class="card fold" open><summary><span><b>Organization · Requesting / Engineering Teams</b><small>Shared master data for Prototype, Validation and Failure Analysis requests</small></span><span class="pill">${teams.filter(t=>t.active!==false).length} active</span></summary><div class="section-title-row"><div><span class="eyebrow">ORGANIZATION MASTER DATA</span><h2>Requesting teams</h2><div class="subtle">These teams are maintained here—not in Lab Standards & Resources. Engineering users may have a default team; planners/admins must deliberately select the team when creating a request on someone else's behalf. Historical requests retain the recorded team snapshot.</div></div>${admin?btn('+ Add requesting team','data-v1089-add-team','button small primary'):''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Team</th><th>Business unit</th><th>Default site</th><th>Team lead</th><th>Assigned users</th><th>Status</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="7">No requesting teams configured. An Administrator must create one before a new request can be submitted.</td></tr>'}</tbody></table></div></details>`;
