  root?.querySelectorAll('[data-edit-pipeline]').forEach(el=>el.onclick=()=>pipelineProjectModal(el.dataset.editPipeline));
  root?.querySelectorAll('[data-pipeline-impact]').forEach(el=>el.onclick=()=>pipelineImpactModal(el.dataset.pipelineImpact));
