  const head=page.querySelector('.page-header');head?.after(nav);
  nav.querySelectorAll('[data-v1090-jump]').forEach(b=>b.onclick=()=>{const t=document.getElementById(b.dataset.v1090Jump);if(!t)return;if(t.tagName==='DETAILS')t.open=true;t.scrollIntoView({behavior:'smooth',block:'start'})});
