  const header=page.querySelector('.page-header .header-actions');if(header){const auto=header.querySelector('[data-plan-portfolio]');if(auto){auto.textContent='AUTO PLAN · TIERED';auto.classList.add('next-action')}if(!header.querySelector('[data-v1094-escalation]'))header.insertAdjacentHTML('beforeend',`${btn('ESCALATION MODE','data-v1094-escalation','button danger')}`)}
