function v1094ApplyHealthFilter(key){App.filters.planHealth=key||'all';render()}
function v1094FriendlyPlannerFailure(candidate,tier){
  const f=candidate?.failures?.[0]||candidate?.results?.find(x=>!x.ok);if(!f)return 'No end-to-end valid candidate is available in this tier.';const d=f.details||{},task=d.taskName?` for ${d.taskName}`:'';
  if(f.code==='RECOVERY_REQUIRED')return `Current released capability needs a controlled readiness or qualification action${task}. Yellow can schedule that recovery without moving another project.`;
  if(f.code==='ZERO_EQUIPMENT_CAPABILITY')return `A required equipment capability is not registered${task}. Add/borrow the capability or configure an approved sister-lab / external route before planning can be complete.`;
  if(f.code==='ZERO_REQUIRED_SKILL')return `A required competency is not available${task}. Add an authorised person or a controlled training path.`;
  if(f.code==='STAFF_UNAVAILABLE')return `The required person is unavailable${task}. Use another qualified person, a training recovery, or a portfolio trade-off.`;
  if(['CAPACITY_UNRESOLVABLE','READINESS_SLOT_UNRESOLVABLE'].includes(f.code))return `This tier cannot fit all remaining controlled work in the useful planning window${task}. LabOS evaluates the higher tiers rather than presenting a remote multi-year date as “best feasible”.`;
  if(f.code==='PLANNING_INTEGRITY_FAILED')return 'The candidate failed the final collision / readiness integrity gate and has been rejected automatically.';
  return 'The candidate was rejected by the planner safety gate. Existing planning remains unchanged.';
}
function v1094MetricDelta(label,before,after,suffix=''){const diff=Number(after||0)-Number(before||0),cls=diff<0?'good-text':diff>0?'bad-text':'';return `<div class="mini-kpi"><span>${esc(label)}</span><strong class="${cls}">${esc(String(after))}${suffix}</strong><small>${before===after?'unchanged':`${before} → ${after}${suffix}`}</small></div>`}
function v1094TierCard(row,baseline,recommendedTier,targetRequestId){
  const c=row.candidate,ok=!!c?.ok,eligible=!!row.eligible,recommended=row.tier===recommendedTier,metrics=c?.metrics,target=targetRequestId&&c?.state?(c.state.requests||[]).find(r=>r.id===targetRequestId):null,worsened=c?.worsened||[],className=`planner-tier-v1094 ${row.tier} ${recommended?'recommended':''} ${eligible?'eligible':'disabled'}`;
  const body=ok?`<div class="planner-tier-metrics-v1094">${v1094MetricDelta('Total days late',baseline.totalLateDays,metrics.totalLateDays,' d')}${v1094MetricDelta('Max project delay',baseline.maxLateDays,metrics.maxLateDays,' d')}${v1094MetricDelta('Unplanned',baseline.unplanned,metrics.unplanned)}${v1094MetricDelta('Commitment worsening',baseline.commitmentWorseningDays,metrics.commitmentWorseningDays,' d')}</div>${target?`<div class="planner-target-outcome-v1094"><span>Target forecast</span><strong>${P.formatDate(target.forecastDate)}</strong></div>`:''}${worsened.length?`<details class="planner-impact-v1094"><summary>${worsened.length} project${worsened.length===1?'':'s'} become later</summary>${worsened.slice(0,8).map(x=>`<div><strong>${esc(x.requestId)}</strong><span>${P.formatDate(x.from)} → ${P.formatDate(x.to)} · +${x.shift} d</span></div>`).join('')}</details>`:'<div class="planner-no-worsening-v1094">✓ No other project becomes later.</div>'}`:`<div class="callout compact"><strong>Not available in this tier</strong><p>${esc(v1094FriendlyPlannerFailure(c,row.tier))}</p></div>`;
  const action=eligible?btn(recommended?'Review recommended plan →':'Review this tier →',`data-v1094-review-tier="${row.tier}"`,'button small '+(recommended?'primary':'secondary')):`<button class="button small" type="button" disabled>${row.tier==='red'&&ok?'Not justified by whole-lab objective':'Unavailable'}</button>`;
  return `<section class="${className}"><div class="planner-tier-head-v1094"><span class="planner-tier-number-v1094">${row.tier==='green'?'1':row.tier==='yellow'?'2':'3'}</span><div><span class="eyebrow">${recommended?'RECOMMENDED · ':''}${esc(row.tier.toUpperCase())}</span><h3>${esc(row.label)}</h3><p>${esc(row.description)}</p></div>${action}</div>${body}${row.reason&&!eligible?`<small class="planner-tier-reason-v1094">${esc(row.reason)}</small>`:''}</section>`;
}
function v1094OpenTieredPlanner(targetRequestId=null,contextEvent=null){
  const label=targetRequestId?`AUTO PLAN · ${targetRequestId}`:'AUTO PLAN · PORTFOLIO';openModal(label,`<div class="planner-computing-v1094"><span class="spinner"></span><div><strong>Evaluating Green, Yellow and Red planning strategies…</strong><small>All candidates are rechecked for resource collisions, readiness, qualifications and workflow integrity before they are shown.</small></div></div>`,btn('Cancel','data-modal-close','button'),true);
  setTimeout(()=>{let pack;try{pack=P.buildAutoPlanTiersV1094(App.state,{targetRequestId})}catch(e){console.error(e);openModal('AUTO PLAN safety stop',`<div class="callout bad"><strong>The planning analysis could not complete safely.</strong><p>The current plan has not changed. ${esc(e.message||'Unexpected planner error')}</p></div>`,btn('Close','data-modal-close','button'),true);return}App.pendingTieredPlannerV1094={pack,targetRequestId,contextEvent};const rec=pack.recommended?.tier||null,suggestions=pack.suggestions||[],available=pack.candidates.some(x=>x.eligible)||!!pack.recommended;const target=requestById(targetRequestId);openModal(label,`<div class="planner-policy-v1094"><strong>${target?`Target · ${esc(target.id)} · ${esc(target.title||target.productFamily||'')}`:'Whole-lab optimization'}</strong><span>Red is selectable only when a quantified whole-lab objective improves. No candidate is allowed to convert a capacity failure into a years-away “best” date.</span></div>${pack.candidates.map(x=>v1094TierCard(x,pack.baseline,rec,targetRequestId)).join('')}${suggestions.length?`<section class="planner-improvements-v1094"><span class="eyebrow">IMPROVE BEYOND THE PROPOSAL</span><h3>Capability suggestions</h3>${suggestions.map(s=>`<div><strong>${esc(s.title)}</strong><span>${esc(s.detail)}</span></div>`).join('')}</section>`:''}${!available?`<div class="callout warn"><strong>Current plan retained</strong><p>No complete valid alternative passed the safety gates. Use the capability suggestions above or Escalation Mode after adding the missing capability. LabOS has not fabricated a remote date.</p></div>`:''}`,`${btn('Close','data-modal-close','button')}${targetRequestId?btn('Escalation mode…','data-v1094-escalation-from-tier','button danger'):''}`,true)},30);
}
function v1094ReviewTier(tier){
  const pending=App.pendingTieredPlannerV1094;if(!pending)return;let row=pending.pack.candidates.find(x=>x.tier===tier&&x.eligible);if(!row&&pending.pack.recommended?.tier===tier)row=pending.pack.recommended;if(!row?.candidate?.ok){toast('That tier is not an eligible planning proposal.',true);return}const c=row.candidate,ids=(c.state.requests||[]).filter(r=>!['DELIVERED','CLOSED','RELEASED','ARCHIVED'].includes(r.status)).map(r=>r.id);showPlanProposal({mode:pending.targetRequestId&&tier!=='red'?'single':'portfolio',proposedState:c.state,requestIds:ids,results:c.results,contextEvent:pending.contextEvent});const note=$('#planProposalNote');if(note)note.value=`${row.label}. Reviewed against ${c.worsened?.length||0} worsened project(s); whole-lab total lateness ${pending.pack.baseline.totalLateDays} → ${c.metrics.totalLateDays} days.`;
}
function v1094EscalationChooser(defaultId=null){
  const rows=planningHealthModelV1094().items.slice().sort((a,b)=>b.lateDays-a.lateDays||String(a.r.requiredDate||'').localeCompare(String(b.r.requiredDate||''))),selected=defaultId&&rows.some(x=>x.r.id===defaultId)?defaultId:(rows[0]?.r.id||'');
  openModal('Escalation Mode',`<div class="callout bad"><strong>Target-first planning</strong><p>Escalation gives the selected project the earliest valid schedule available from all movable future capacity. The remaining projects are then replanned to minimize the resulting lab-wide delay. Completed work and hard locks remain protected.</p></div><div class="field" style="margin-top:12px"><label>Escalated project</label><select id="v1094EscalationTarget">${rows.map(x=>`<option value="${esc(x.r.id)}" ${x.r.id===selected?'selected':''}>${esc(x.r.id)} · ${esc(x.r.title||x.r.productFamily||'')} · ${x.lateDays?`${x.lateDays} d late`:'not late'}</option>`).join('')}</select></div><div class="callout warn"><strong>Governance</strong><p>This mode may worsen other projects. Nothing is applied until the complete before/after impact is reviewed and explicitly accepted.</p></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Calculate absolute best plan','data-v1094-run-escalation','button danger')}`,true)
}
function v1094RunEscalation(){const id=$('#v1094EscalationTarget')?.value;if(!id)return;openModal(`Escalation analysis · ${id}`,`<div class="planner-computing-v1094"><span class="spinner"></span><div><strong>Reserving best possible capacity for ${esc(id)}…</strong><small>Then minimizing the delay imposed on every remaining project.</small></div></div>`,btn('Cancel','data-modal-close','button'),true);setTimeout(()=>{const out=P.buildEscalationPlanV1094(App.state,id);if(!out.ok){openModal(`Escalation · ${id}`,`<div class="callout bad"><strong>No safe escalation plan is currently possible.</strong><p>${esc(out.reason)}</p></div>${(out.suggestions||[]).map(s=>`<div class="callout"><strong>${esc(s.title)}</strong><p>${esc(s.detail)}</p></div>`).join('')}`,btn('Close','data-modal-close','button'),true);return}App.pendingEscalationV1094=out;const b=P.planningPortfolioScoreV1094(App.state,App.state),a=out.candidate.metrics;openModal(`Escalation result · ${id}`,`<div class="planner-policy-v1094"><strong>${esc(id)} receives the earliest valid target-first schedule.</strong><span>The remainder of the portfolio has been re-optimized after that reservation.</span></div><div class="grid cols-4">${v1094MetricDelta('Target forecast',out.targetBefore||'—',out.targetAfter||'—')}${v1094MetricDelta('Total days late',b.totalLateDays,a.totalLateDays,' d')}${v1094MetricDelta('Max project delay',b.maxLateDays,a.maxLateDays,' d')}${v1094MetricDelta('Projects worsened',0,out.worsened.length)}</div>${out.worsened.length?`<section class="planner-impact-table-v1094"><h3>Consequences for other projects</h3>${out.worsened.map(x=>`<div><strong>${esc(x.requestId)} · ${esc(x.title||'')}</strong><span>${P.formatDate(x.from)} → ${P.formatDate(x.to)} · +${x.shift} d</span></div>`).join('')}</section>`:'<div class="callout good"><strong>No other project becomes later.</strong></div>'}${(out.suggestions||[]).length?`<section class="planner-improvements-v1094"><h3>Ways to reduce the escalation impact</h3>${out.suggestions.map(s=>`<div><strong>${esc(s.title)}</strong><span>${esc(s.detail)}</span></div>`).join('')}</section>`:''}`,`${btn('Cancel','data-modal-close','button')}${btn('Review complete escalation plan →','data-v1094-review-escalation','button danger')}`,true)},30)}
function v1094ReviewEscalation(){const out=App.pendingEscalationV1094;if(!out?.ok)return;const ids=(out.candidate.state.requests||[]).filter(r=>!['DELIVERED','CLOSED','RELEASED','ARCHIVED'].includes(r.status)).map(r=>r.id);showPlanProposal({mode:'portfolio',proposedState:out.candidate.state,requestIds:ids,results:out.candidate.results});const note=$('#planProposalNote');if(note)note.value=`Escalation Mode · ${out.targetRequestId} target-first. Target ${out.targetBefore||'—'} → ${out.targetAfter||'—'}; ${out.worsened.length} other project(s) become later and were replanned to minimize overall delay.`}

